(function(){if(!window.CET_DATA)window.CET_DATA={meta:{},exams:[]};var a=[{"id":"2025-12-cet6-1","level":"CET6","year":2025,"month":12,"set":1,"title":"2025 年 12 月 · CET6 第 1 套","source":"2025年12月 第1套","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence “Living in an\nincreasingly competitive world, college students should better prepare themselves to confront various challenges.\" You\ncan make comments, cite examples or use your personal experiences to develop your essay. You should write at least 150\nwords but no more than 200 words.\n\nYou should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":["先明确建议对象与目的。","两条具体建议 + 一条预期效果。","结尾礼貌收束，不引入新论点。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"He has distinguished himself in foreign service","C":"He is currently an electrical engineer","B":"He is his country's ambassador to Winopia","D":"He craves attention from the media"},"answer":"A","stem":""},{"n":2,"options":{"A":"A government reshuffle","C":"Some sort of political reorientation","B":"A fundamental reform","D":"Some sort of crisis of legitimacy"},"answer":"D","stem":""},{"n":3,"options":{"A":"All diplomats have more or less similar stories to tell","B":"It is a prerequisite to get some practice in diplomacy","C":"Different people can take different paths","D":"It is a must to first obtain a law degree"},"answer":"C","stem":""},{"n":4,"options":{"A":"Key skills required of a diplomat","C":"Diplomatic discourse and rhetoric","B":"The making of an expert diplomat","D":"Contributions by diplomatic envoys."},"answer":"A","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"They have got their work done","C":"They can meet again tomorrow anyway","B":"They both look tired","D":"They are both anxious to go home"},"answer":"B","stem":""},{"n":6,"options":{"A":"The board members’ insufficient support","C":"Working two months without any progress","B":"Two months devoted to the same contract","D":"The man's long concentration on the project"},"answer":"B","stem":""},{"n":7,"options":{"A":"Unprofessional","C":"Exceptional","B":"Inspirational","D":"Delusional"},"answer":"D","stem":""},{"n":8,"options":{"A":"Fewer rectifications of the contract","B":"More support from the board members","C":"The early implementation of the project","D":"The alignment of all sections of the contract"},"answer":"C","stem":""}]},{"intro":"Questions 9 to 11 are based on the you have just heard","questions":[{"n":9,"options":{"A":"When two employees propose contrary solutions to their dispute","B":"When two employees are directed by their respective manager","C":"When two people behave in an apparently clashing manner","D":"When two people tell different stories of the same event"},"answer":"D","stem":""},{"n":10,"options":{"A":"How it got resolved","C":"What it was about","B":"How it happened","D":"When it was settled"},"answer":"A","stem":""},{"n":11,"options":{"A":"They intervened promptly lest their dispute escalate","C":"They assumed the best about them and moved on","B":"They tried to ascertain the actual facts of the matter","D":"They persuaded them to put their conflict aside."},"answer":"C","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"Dine out daily","C":"Enjoy cooking","B":"Budget sensibly","D":"Shop at groceries"},"answer":"A","stem":""},{"n":13,"options":{"A":"Shopping","C":"Entertaining oneself","B":"Sewing","D":"Fashion designing"},"answer":"B","stem":""},{"n":14,"options":{"A":"Satisfy their taste","C":"Eat more healthily","B":"Cut down expenses","D":"Cultivate new hobbies"},"answer":"B","stem":""},{"n":15,"options":{"A":"People's intense focus on convenience","C":"People's strong aversion to junk foods","B":"People's deteriorating family finances","D":"People's increasing dislike of cooking"},"answer":"D","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"Its owner's flight is delayed because of bad weather","B":"Airlines cannot find its owner without an ID tag on it","C":"Airline staff have not correctly coded its destination tag","D":"Its owner has forgot to pick it up from the baggage claim"},"answer":"B","stem":""},{"n":17,"options":{"A":"Its tag may get tom off on the conveyor belt","C":"It may be sent to a wrong destination","B":"Its tag may get stuck in the sorting machine","D":"It may be picked up by someone else"},"answer":"A","stem":""},{"n":18,"options":{"A":"Purchase irretrievably lost things at auction","B":"Contact the airport staff to find our missing bag","C":"Get the airline agent’s phone number before boarding","D":"Avoid packing valuable items in our checked baggage"},"answer":"D","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"It can be behaviorally hazardous","C":"It can be socially harmful","B":"It can be especially disappointing","D":"It can be really embarrassing"},"answer":"C","stem":""},{"n":20,"options":{"A":"They considered it inevitable","C":"They were concerned with its effects","B":"They held a negative view towards it","D":"They saw it as a sign of social evolution"},"answer":"B","stem":""},{"n":21,"options":{"A":"Elaborate forms of social contact","C":"Poor relationships with others","B":"Ill effects on one's sense of pride","D":"Vicious cycles of detachment."},"answer":"D","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"The ill treatment they get as tourists","C":"The impersonal accommodations","B":"The nonprofessional business they see","D":"The many adventures on their way"},"answer":"C","stem":""},{"n":23,"options":{"A":"They have been the classic way to visit Europe","C":"They have long been competing with chain hotels","B":"They attract tourists with location and decoration","D":"They are in fact a completely new idea in America"},"answer":"A","stem":""},{"n":24,"options":{"A":"Your financial status","C":"Your property","B":"Your family's consent","D":"Your personality"},"answer":"C","stem":""},{"n":25,"options":{"A":"Costs for starting the business","C":"The facilities to provide","B":"The number of guests to receive","D":"Opportunities for income"},"answer":"D","stem":""}]}]},"cloze":{"passage":"By now, it is generally accepted that regular exercise comes with an assortment of health benefits for people who maintain \nthe habit over time. But is it ___26___ too late to start? \nNew research looked at people who increased their exercise levels after their 40s beyond levels they had when they were \nyounger and those individuals showed declines in their risk of early  ___27___ which were similar to those of  people who \nexercised consistently throughout their lives. This was a ___28___ of 32% to 35% compared to people who did not exercise. \nThose who began exercising in middle age also saw reductions in their incidence of ___29___ diseases, such as heart disease \nand cancer, which were similar to the steady exercisers. \nSo why bother exercising consistently throughout your life? The authors of the study ___30___ that some might interpret \nthe study's findings to mean that the y can delay starting an exercise program , but this would be a mistake. There are other \nbenefits, both mental and physical, to staying consistently active that we should  not ___31___. These real health benefits \ninclude better ___32___ functioning and lowered risk of gaining weight. The latter is ___33___ important given the global \nobesity epidemic. In addition, experts assert that starting younger  is better because, if you make a habit of exercising when \nyou are young, you are more likely to keep up those ___34___ later in life. It is ideal, then, for people to start exercising when \nthey are children or ___35___, and it is good to maintain an active lifestyle at all times regardless of your age. However, this \nstudy does indicate that, if you have not been active, you can still benefit if you start becoming active in your 40s and 50s.","bank":[["A","adolescents"],["I","maneuver"],["B","arbitrarily"],["J","mortality"],["C","chronic"],["K","particularly"],["D","cognitive"],["L","patterns"],["E","concede"],["M","refute"],["F","disregard"],["N","stereotype"],["G","drop"],["O","vocal"],["H","ever"]],"answers":{"26":"H","27":"J","28":"G","29":"C","30":"E","31":"F","32":"D","33":"K","34":"L","35":"A"}},"matching":{"statements":[{"n":36,"text":"36. It is now possible to fully automate a burger restaurant with little human supervision","answer":"C"},{"n":37,"text":"37. At a robot-powered US company, complicated tasks still have to be performed by humans","answer":"H"},{"n":38,"text":"38. More automation appears to be a certainty in industries eager to cut labour costs and raise profits","answer":"D"},{"n":39,"text":"39. There are often front-page reports of failures in technological innovation of the restaurant industry","answer":"L"},{"n":40,"text":"40. Robot-chef Flippy does not fear laborious work, nor does it make any complaints","answer":"A"},{"n":41,"text":"41. Digital technology makes it possible for businesses to innovate restaurant models","answer":"F"},{"n":42,"text":"42. Fondness for human warmth in catering to customers will give hope to employees who are afraid of losing jobs to robots","answer":"M"},{"n":43,"text":"43. There is an acute shortage of experienced chefs in the catering industry and automated cooking is expected to fill the gap","answer":"J"},{"n":44,"text":"44. Over the coming decade, many jobs in traditional restaurants will disappear due to robot delivery","answer":"O"},{"n":45,"text":"45. According to an expert in AI and robotics, it may be quite some time before a master robot-chef appears","answer":"G"}],"paragraphs":{"A":"Like most chefs, Flippy is not afraid of hard work. Since last summer, that has meant 11am until 7pm shifts at Caliburger in Pasadena, California, as well as short assignments at Chick -N-Tots at Dodger Stadium in Los Angeles. These are long hours of repetitive work, where the boss demands absolute consistency. But you won't hear Flippy complain or say anything, in fact. For Flippy is a robot — a cloud-connected mechanical arm with 3D thermal scanners for eyes — that can flip burgers or fry 80 baskets of food an hour, monitor that food and even clean up afterwards","B":"Flippy was created by Miso Robotics, part of the Cali Group, which is described by its CEO, John Miller, as: “A technology company that happens to sell cheeseburgers. ” Cali creates new machines that it road -tests in its Caliburger restaurants across the world, into which Flippy will be deployed this year. And Flippy is not alone. Also in California, Bear Robotics has developed a self-guiding robot, Penny, which has so far served 40,000 diners","C":"Ten years ago, robot-chefs and waiters were pure science fiction. Today, they are a reality, and at prices that make them a plausible investment. From May, Penny will be shipped on a subscription basis that offers “an immediate return”, says Bear Robotics’ chief operating officer, Juan Higueros. Flippy will cost a reported $60,000 to $100,000. Fully automated burger restaurants managed with minimal human oversight — where customers order at screens, pay electronically and eat food cooked and delivered by robots — are now a possibility","D":"The technology exists, it just needs knitting together cost-effectively and in a way diners buy into. In an industry keen to slash labour costs and increase profits, further automation seems inevitable. After an eight -month test at Kang Nam Tofu House in California, Bear Robotics credited Penny with driving a 28% increase in sales. Meanwhile, in US trials, the self- ordering screens that McDonald’s is currently installing at its 1,300 UK restaurants yielded a reported 30% rise in order values","E":"Personalisation is seen as key to the appeal of this technology, alongside its ability to reliably push so -called “upsells” (meal deals, extras, larger drinks) to customers. Soon when you log into a restaurant app, it will be able to use your data and purchasing history to recommend dishes to you — factoring in everything from the weather to, if you are ordering at a screen that can read your face, your mood","F":"“Right now people compromise on choice. We're presented with a one-size-fits-all menu. Ultimately, technology can allow us to make personal choices. You love spicy food and chicken? Here's the dish people like you mostly order,” says Tom Weaver, CEO at the hospitality tech company Flyt. He talks enthusiastically about the Helsinki pop -up Take-In, a full - service restaurant where diners ordered dishes in from various delivery services. “For the first time in a few hundred years, digital is allowing us to create new versions of restaurants.”","G":"If high -street fast food is automation -ready, its impact on high-end restaurants is likely to be subtler and slower. “It’ll probably be a very long time before we see a five-star robot-chef,” says Noel Sharkey, professor of AI and robotics at the University of Sheffield. “Apart from the AI creativity gap, great cooking involves a subtle understanding of ingredients and delicate cooking that would be enormously challenging for robots. Placing fragile foods on plates would be incredibly slow.”","H":"Currently, robots have limited functionality. A human needs to load Penny with plates that diners lift off themselves. At the robot-powered US pizza -delivery company Zume, the more difficult jobs, such as topping pizzas, are still done by humans. But Moley, which will launch soon, offers an idea of the sophistication to come. Modelled on the movements of a MasterChef contest winner, Tim Anderson, its robotic arms are fixed over a stove and programmed to prepare dishes from raw ingredients. It is designed for domestic use, but a commercial version is planned that opens up the po ssibility of restaurant kitchens automating even highly technically challenging tasks","I":"For now, the kitchen technology that QSR Automations supplies to Mitchells & Butlers ’ pubs or KFC is less glamorous. Rather than having a chef shouting out diners' orders, the QSR system automatically distributes those orders across screens. The kitchen screens then tell chefs when to start cooking each dish, so that your plate of fish, chips and peas comes together at the right time","J":"The restaurant industry is currently suffering a severe shortage of skilled chefs — a deficit of 11,000, according to the skills agency People 1st. “Automation systems designed to make the process more idiot-proof are trying to bridge that gap,” says Stefan Chomka, the editor of Restaurant magazine","K":"In terms of simplifying or enhancing the customer experience, online restaurant booking has been the easily-won success of the internet age. Automated at-table ordering and payment is seen as the next landmark. Until then, early adopters, such as the Manchester bar owner Andy Smith, who uses the Ordoo app at his venue 33 Oldham Street, may well experience growing but “lower than expected” acceptance","L":"Embarrassing failures in restaurant tech frequently hit the headlines. The TGI Fridays drone (无人机) that injured a Brooklyn Daily photographer; US burger chain Shake Shack having to retreat from plans for entirely cashless ordering sites. But, says Chomka, such technology could miss the mark if it only offers “solutions to problems that don’t really exist”. “Payments being automatic” could be useful, he adds. But, in an expensive restaurant, “how quick do you need dinner to be?”","M":"That attachment to the human art of hospitality will be heartening for staff who see automation as a threat to jobs. “Unite is concerned that without safeguards, any benefits will bypass workers in low-paying jobs, such as waiters,” says the union's London regional officer, Dave Turnbull. \"We're urging Members of Parliament to ensure automation does not just benefit a wealthy few like previous industrial revolutions.”","N":"The industry principle is that automation will allow it to redeploy staff more effectively. Jobs will change, i f not immediately decrease in number,” Self-order screens mean more demand for people front-of-house. Last year, we recruited 1,000 new managers,” says McDonald's COO, Jason Clark. Caliburger has a programme to retrain staff as robot engineers or “chef techs”","O":"But ultimately the chance to reduce overheads ( 管理费用) by employing fewer people or at lower rates will be what attracts big brands to technology. Invariably, over the next 10 years, jobs will go in conventional bricks-built restaurants, not least because automation will boost their rapidly growing rival: delivery. Companies such as Domino and Just Eat have both experimented with robot and drone delivery, which is already legal in Reykjavik, Iceland. “Robot food deliveries are the future,” says Noel Sharkey. “Small, 4mph ground robots are safe and will work 24 hours a day.”","P":"Combined with machine learning of anticipated order volumes and the minute -by-minute cooking data generated by systems such as QSR, that robot fleet could deliver almost instantly. “Restaurants will prepare food ahead of orders coming in,” predicts Just Eat’s director of engineering, Daniel Richardson. “I’ll be able to say ‘Let's have pizza’ to my family, my intelligent assistant will hear and 10 minutes later the food will be at my door.” No one is putting an exact date on it yet. But in the dining room and on your doorstep, the robots are coming"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O","P"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Many see friendships as a comfort blanket: a shoulder to cry on, a reliable soul to confide in. However, more often than \nnot, in our eagerness to seek individual success, we lose friends along the way and that has become part of the process. \nThe chaos and never -ending turmoil that accompanies everyday life is an aggressive obstacle in the pursuit  of stable \nfriendships. As students, we use this excuse to shrug off losing people who we once thought to be loved ones. \nInstead of viewing our lives as a race, where everyone is on their own path to some form of success, we must relearn to \nvalue the connections we make along the track. We must reevaluate the harm of radical, individual freedom. \nRadical individualism elevates the freedom of the individual over the collective. It argues, for instance, that  universal \nhealthcare, an example of collectivism, threatened the dream of many Americans. \nMany of us have fallen victim to an individualistic culture. Society tends to celebrate personal achievement and commend \nit based on the assumption that winning or succeeding is a consequence of working harder than the next person. \nAs a society, we idolize the concept of “losing friends on the road to success.” I remember hearing in high school, “Don’t \nworry about losing friendships, just focus on study and getting into college. Tha t’s all that will  matter in the long run, ” a \nsentiment that is not unique to my experience. I t’s preached in many success stories,  and it’s embedded in the way we see \ngrowth. Motivational speakers will push their audience to be complacent to  the inevitable end of losing friends. Spend too \nmuch time with friends? You’re losing time better utilized on your  achievements. Invest time in your relationships ? Invest \ntime in your work instead.  \nThis constant need to succeed has blinded us from seeing through the whirlwind of change that accompanies our everyday \nlives. We are expected to tangibly succeed, earn awards, get higher positions, earn better grades. In order to succeed, we lose \nfriends, and that has sadly become normalized. \nWe cannot be complacent with losing friendships because they are our anchors. \n\f\nYes, pursue success. Challenge yourself. Push limits. But contrary to all the self -proclaimed success experts, doing it \nalone does not make you more successful or any better than someone who achieved it with the help of others. \nPut effort into fostering healthy relationships, and maintaining them through your busy schedule that seems like it leaves \nno time for anyone else. Although we may be living in a society that treasures the independent pursuit of achievement, having \npeople to support and love you on the way is far more important than any end result.","questions":[{"n":46,"stem":"46. What often happens when people are eager to pursue individual success?","options":{"A":"They lack a shoulder to cry on","C":"They cannot find reliable friends","B":"They have no soul to confide in","D":"They ignore their ties with friends"},"answer":"D"},{"n":47,"stem":"47. What does the author advise people to do in their pursuit of radical individualism?","options":{"A":"Reexamine its detrimental effects","C":"Avoid the chaos and turmoil involved","B":"Shrug off the loss of their loved ones","D":"Remove aggressive obstacles in the way"},"answer":"A"},{"n":48,"stem":"48. What is American society’s assumption of personal achievement?","options":{"A":"It is to be duly celebrated and highly commended","C":"It revolves around an individualistic culture","B":"It is a sure way to fulfill a person’s dream","D":"It reflects a person’s exceptional endeavor"},"answer":"D"},{"n":49,"stem":"49. What is preached in many success stories?","options":{"A":"Attaching importance to academic gains on the road to success","B":"Investing one’s time in work instead of connecting with friends","C":"Trying to strengthen friendships in one’s pursuit of personal success","D":"Excelling in academic performance to get into a prestigious college"},"answer":"B"},{"n":50,"stem":"50. What can we infer from the passage regarding the pursuit of success?","options":{"A":"No one can succeed without pushing limits","C":"Collectivism is superior to individualism","B":"No one can afford to neglect close friends","D":"Success experts often lead people to ruin"},"answer":"B"}]},{"title":"Passage Two","passage":"During his acceptance speech for the Nobel Peace Prize, Martin Luther King Jr. said, “I believe that unarmed truth and \nunconditional love will have the final word in reality.”  \nMore than five decades later, our society is still struggling to separate truth from fantasy, fact from fiction. From disputes \nover the climate change to debates about how slavery is taught, America is at a crossroads. And the battle for equity is at the \nheart of these vital conversations.  \nStudy after study shows that inequity has had appalling consequences. A 2020 report by Citi indicated that “Black \nstudents could have increased their lifetime incomes $90-$113 billion” if equity issues related to higher education had been \nadequately addressed over the past two decades.  \nThis statistic represents a flood of issues we’ve failed to confront as a nation. It also highlights one truth: We're missing \nout on valuable opportunities to bridge the differences that divide us. However, by h onoring King’s legacy, we can get our \ncountry back on the path toward true equity. \nStudents — and adults for that matter — simply cannot understand the conflicts we have today without  understanding \nwhat caused them in the first place. That means we have a responsibility to help them make connections between U.S. history \nand current events. It also means giving them the tools they need to address  inequity and bias in their own lives. Adherence \nto these principles, along with a commitment to truthful dialogue, can help every student better appreciate how far we've come \nand more clearly see the roads we have yet to travel. \nWith more truthful analysis of the need for more qualified, diverse educators, we can improve our recruiting,  training, \nand retention strategies for schools across the country. \nUnfortunately, our deeply rooted divisions are delaying these advancements. A recent survey found that 77  percent of \nAmericans believe the nation is “more divided than ever before”. But reports of increased polarization shouldn’t persuade us \nto look away from one another. Instead, they should compel us to address our shared issues head-on. \nWe are not, as some would suggest, living in a “post-racial society”. We simply cannot afford to keep our heads buried \nin the sand when it comes to racial inequity. Unless we get honest about intolerance, bias, and how  these social diseases \n\f\nimpact the ways we treat one another, injustice will continue to haunt us. But our children  and our grandchildren deserve \nbetter. \nOn this Martin Luther King Day and beyond, let’s commit to working together to disrupt the status quo. Let’s continue \nto build a better, more inclusive nation; and in the words of Martin Luther King Jr., “A society at peace with itself, a society \nthat can live with its conscience.”","questions":[{"n":51,"stem":"51. What does the author think about today's America?","options":{"A":"It is struggling to transform fiction into reality","B":"It has been the focus of many vital conversations","C":"It still has a long way to go before equity can be truly realized","D":"It has got to a point where people disagree on nearly every issue"},"answer":"C"},{"n":52,"stem":"52. What do we learn from the passage about black students in the past 20 years?","options":{"A":"They have been unfairly treated regarding higher education","B":"They have been battling hard to address equity issues","C":"They have boosted their lifetime incomes by billions of dollars","D":"They have come to see the consequences of racial discrimination"},"answer":"A"},{"n":53,"stem":"53. How can Americans bridge the differences that divide them?","options":{"A":"By dealing with the thorny issues confronting them","B":"By seizing every chance to enhance racial harmony","C":"By continuing to pursue Martin Luther King Jr.'s cause","D":"By striving to identify exceedingly valuable opportunities"},"answer":"C"},{"n":54,"stem":"54. How do most Americans view America as a nation according to a recent survey?","options":{"A":"It is compelled to address its historical social issues","B":"It is delaying advancements toward racial equality","C":"It has kept itself from polarization","D":"It has become increasingly split"},"answer":"D"},{"n":55,"stem":"55. What does the author suggest Americans do?","options":{"A":"Ensure the wellbeing of their children and grandchildren","B":"Make joint efforts to tackle the nation's equity issues","C":"Restrain their intolerance and discrimination","D":"Restore social order for a harmonious nation"},"answer":"B"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n\n尊老是中华民族的传统美德，深深植根于中国人的思想和行为中，是人们普遍遵守的行为规范和社会准则。在当今\n的中国，这种美德得到广泛传承。社会各界积极营造敬老助老的社会氛围。为老年人提供便利服务已成为社会共识，\n例如社区专门开设长者食堂，公共场所配置优先座位。政府还出台了一系列政策，为老年人的权益提供有力保障。\n尊老是社会和谐与发展的重要基石，有助于培育良好的社会氛围，推动整个社会文明进步。","guide":["先拆句：政策背景→数据→质量/研发→作用。","关键词：private economy, support policies, high-quality development, core competitiveness。","数字与百分比要准确。"]},"answersReady":true},{"id":"2025-12-cet6-2","level":"CET6","year":2025,"month":12,"set":2,"title":"2025 年 12 月 · CET6 第 2 套","source":"2025年12月 第2套","writing":{"prompt":"Directions: For this part you are allowed 30 minutes to write an essay that begins with the sentence “While striving for\nthe Chinese Dream, young people enjoy more opportunities to realize their self-worth.\" You can make comments, cite\nexamples or use your personal experiences to develop your essay. You should write at least 150 words but no more than 200\nwords.\nYou should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":["先明确建议对象与目的。","两条具体建议 + 一条预期效果。","结尾礼貌收束，不引入新论点。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"It is absurdly expensive","C":"It brings shame on the university","B":"It is appropriately priced","D":"It caters to students and teachers"},"answer":"B","stem":""},{"n":2,"options":{"A":"They never really appeal to her","C":"They are within students’ budgets","B":"They are never actually good value","D":"They always come at a high speed"},"answer":"A","stem":""},{"n":3,"options":{"A":"The food","C":"The speed","B":"The space","D":"The environment"},"answer":"C","stem":""},{"n":4,"options":{"A":"A complete refurnishing","C":"A substantial expansion","B":"A ruinous burning down","D":"A massive renovation."},"answer":"D","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"They have a poor work ethic","C":"They are struggling in the workplace","B":"They don't get along with managers","D":"They aren't as varied as their predecessors"},"answer":"A","stem":""},{"n":6,"options":{"A":"Learning about the way they adhere to their own values","B":"Recognizing how they try to strike a work-life balance","C":"Knowing how they struggle to connect with managers","D":"Understanding the way they seek career advancement"},"answer":"B","stem":""},{"n":7,"options":{"A":"In terms of the number of hours spent","C":"In terms of the work done in 8 hours","B":"By the amount of work they perform","D":"By the quality of the work they do"},"answer":"D","stem":""},{"n":8,"options":{"A":"Those whose culture facilitates their advancement","C":"Those whose values align with their own","B":"Those allowing them to do projects of their choice","D":"Those refraining from discrediting their perspectives"},"answer":"C","stem":""}]},{"intro":"Questions 9 to 11 are based on the you have just heard","questions":[{"n":9,"options":{"A":"They may unconsciously help customers choose greener dishes","B":"They may unintentionally encourage customers to eat meat","C":"They raise customers’ environmental awareness","D":"They enable customers to eat in a healthy way"},"answer":"B","stem":""},{"n":10,"options":{"A":"By inviting them to taste different kinds of food","B":"By observing the eating behaviour of strict vegetarians","C":"By comparing participants eating vegetarian food frequently with those doing so rarely","D":"By requiring participants to choose a meal as if they were feasting at a family gathering"},"answer":"C","stem":""},{"n":11,"options":{"A":"They are less likely to choose a vegetarian dish","B":"They find vegetarian dishes become more appealing","C":"They tend to consume larger portions of unhealthy food","D":"They are less likely to choose dishes recommended by chefs."},"answer":"A","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"They have found a solution to the global problem of air pollution","B":"They have managed to freeze polluting particles to around -18℃","C":"They have been seeking a way to prevent pollutants from penetrating indoors","D":"They have been cooperating closely on developing a new type of air-conditioner"},"answer":"C","stem":""},{"n":13,"options":{"A":"They can be costly and inefficient","C":"They are by-products of health research","B":"They are constantly being perfected","D":"They can save over 40,000 lives each year"},"answer":"A","stem":""},{"n":14,"options":{"A":"They keep their windows closed","C":"They make more use of air-conditioners","B":"They spend a lot more time indoors","D":"They try various ways to purify indoor air"},"answer":"B","stem":""},{"n":15,"options":{"A":"It shows the importance of eliminating indoor pollution","B":"It may change the way of future environmental research","C":"It demonstrates the fruitful cooperation between UK and Chinese scientists","D":"It may make household appliances serve an additional air cleaner function"},"answer":"D","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"It distinguishes different species of animals","B":"It reflects distinct traits in animal behaviour","C":"It demonstrates animals’ ability to recognise themselves","D":"It gauges the level of intelligence of various animal species"},"answer":"C","stem":""},{"n":17,"options":{"A":"It meets few of the behavioural criteria set in the mirror test","B":"It behaves similarly to animals capable of self-recognition","C":"It removes marks from itself to show self-awareness","D":"It matches children over 18 months in intelligence"},"answer":"B","stem":""},{"n":18,"options":{"A":"They have conclusively established the criteria of animal intelligence","B":"They have advanced the concept of self-awareness to a higher level","C":"They incorporate more perspectives than one","D":"They raise more questions than answers."},"answer":"D","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"Small children are even more keen on screens than their elders","B":"Both parents and children preferred to read electronic books","C":"Parents differed from children in reading behavior","D":"Children reading electronic books learned more"},"answer":"D","stem":""},{"n":20,"options":{"A":"They came to conflicting conclusions","C":"They yielded unanticipated findings","B":"They were based on small samples","D":"They were focused on younger kids"},"answer":"A","stem":""},{"n":21,"options":{"A":"Those that prove simple enough for them to comprehend","B":"Those that produce both audio and visual effects on them","C":"Those that draw their attention to the educational content","D":"Those that contribute to their increased interest in reading."},"answer":"C","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Regret having wasted much time in making them","C":"Keep ourselves from regretting them","B":"Think how different we could have made them","D":"Live with them for the time being"},"answer":"C","stem":""},{"n":23,"options":{"A":"It has made us the person we are now","C":"It stems from our valuable knowledge","B":"It has been made with a lot of thinking","D":"It benefits us greatly one way or another"},"answer":"A","stem":""},{"n":24,"options":{"A":"Challenging things to do","C":"Choices to make","B":"Beautiful things to share","D":"Lessons to learn"},"answer":"D","stem":""},{"n":25,"options":{"A":"Foreseeing the possibility for regret later","C":"Perfecting the decision-making strategies","B":"Making proper use of the lessons learned","D":"Seeing them as obstacles to moving forward"},"answer":"B","stem":""}]}]},"cloze":{"passage":"We humans love to believe we are special, but science and technology have repeatedly proved this  conviction wrong. \nPeople ___26___ thought that humans were the only animals to use tools, to form teams or to propagate culture, but science \nhas shown that other animals do each of these things. \nMeanwhile, technology has quashed (使无效), one by one, claims that ___27___ tasks require a human brain. The first \nadding machine was invented in 1623. This past year, a computer -generated work won an art contest. I  believe the moment \nwhen computers meet and ___28___ human intelligence is on the horizon. \nHow will human intelligence and creativity be valued when machines become smarter and more creative  than the \nbrightest people? There will likely be a spectrum. In some ___29___, people still value humans doing  things, even if a \ncomputer can do it better. It's been a quarter of a century since a computer beat world champion Garry Kasparov, but human \nchess hasn't gone away. \nIn other fields, human skill will seem costly and ___30___. Take illustration for example: most readers don’t care whether \nthe graphic ___31___ a magazine article was drawn by a perso n or a computer — they just want it to be  relevant, new and \nperhaps ___32___. \nAnd, of course, this question isn ’t black or white. Many fields will be a ___33___, where some humans find a  lucky \nplace, but most of the work is done by computers, like in manufacturing today, where, much of the work is accomplished by \nrobots, but some humans must be there to ___34___ the machines. \nIf history is any guide, i t’s almost certain that advances in AI will cause more jobs to ___35___, that creative workers \nwith human-only skills will become richer but fewer in number, and that those who own creative technology will become the \nnew ultra-rich.","bank":[["A","accompanying"],["I","once"],["B","cognitive"],["J","oversee"],["C","domains"],["K","redundant"],["D","entertaining"],["L","stances"],["E","evoking"],["M","surpass"],["F","hybrid"],["N","tentatively"],["G","impetus"],["O","vanish"],["H","intuitive"]],"answers":{"26":"I","27":"B","28":"M","29":"C","30":"K","31":"A","32":"D","33":"F","34":"J","35":"O"}},"matching":{"statements":[{"n":36,"text":"36. Feeling like they have more control over something or someone than they do, people get more committed to their pursuit when they should give up","answer":"F"},{"n":37,"text":"37. If you regard yourself as one who never quits, you may end up trapped in your course of action","answer":"K"},{"n":38,"text":"38. One of the author’s clients found it hard to give up a design project, in which she had put in a lot of time and effort","answer":"J"},{"n":39,"text":"39. The author suggests that one should direct their thoughts to the gains of quitting timely so as to move on","answer":"E"},{"n":40,"text":"40. When making a decision, you'd better ask for opinions of those who have less stake in your decision","answer":"M"},{"n":41,"text":"41. For people associating their identity with their commitments, quitting can feel like their identity is threatened","answer":"I"},{"n":42,"text":"42. People who regard highly the quality of making wise decisions do not feel good when they make a bad one","answer":"O"},{"n":43,"text":"43. The wisest leaders learn to distinguish between giving up too soon and sticking with something irrationally","answer":"C"},{"n":44,"text":"44. When people are thinking of an endeavor, they should dig out reliable data that tells them how likely they are to succeed","answer":"N"},{"n":45,"text":"45. Having a clear view of what’s in your control and what’s not is vital to making a good decision regarding whether to give up or stick it out","answer":"H"}],"paragraphs":{"A":"Projects, relationships, and jobs don't always work out as planned - and it's not always clear when to give up. We've all repeatedly heard the saying that “quitters never win,” but sometimes the best decision is to cut our losses","B":"Think about that relationship you held on to even after it had run its course or the job you stayed in despite your boss making you miserable. Many of us try to hold onto the last ray of hope, thinking we can make it work, whatever “it” is. And while perseverance is generally an excellent quality, it may also incline you to over-invest in something that is no longer a good idea","C":"As an executive coach, I work with numerous passionate and hard -working leaders who don't want to “quit.” But the smartest leaders learn to discern the difference between quitting too soon and holding onto something that they shouldn’t","D":"We are all susceptible to the sunk-cost delusion, an unconscious bias that leads us to persist in an endeavor we have already invested time, effort, or money into — even when abandoning it would be more beneficial. We realize that we can't get back the resources we've given, so we persevere — investing in a project that should be halted, staying in a relationship that should be over, or finishing a book we no longer enjoy and should put down, because we're already halfway through it. If quitting is “not your thing,” you may be especially susceptible to this bias","E":"The sunk-cost delusion causes us to overly worry about what we ’ll lose if we move on and not think enough about the costs of not moving on. To offset this bias, deliberately refocus your thinking on the gains so you can more objectively weigh the alternatives. Ask yourself: What might I gain by cutting my losses now? Will you be happier or have time for another (better) opportunity? Then ask yourself: What will it cost me to soldier on? For example, is it possible that you'll be throwing more good money after what you've already lost? Or that you won't have the energy to capitalize on other promising possibilities?","F":"The illusion of control can also interfere with our best judgment, leading us to overesti mate our ability to control events and attain a positive outcome. This bias gives us a sense of agency and can promote mental health. However, the bias can also result in escalating commitment to a losing course of action. Especially when combined with an “I'm not a quitter ” mentality, feeling like we have more control over an event or person than we do puts us at risk of doubling down when we should pull out","G":"To counteract this bias, consider your situation and make a simple two-column list of what's in your control and what's not. Think rigorously. While you may be able to influence other people and various circumstances, you can’t force them to change or go your way","H":"Getting clear on what you can control and what you can't is essential to making a quality decision about whether to call it quits or persevere. With a written list in hand, you can ensure you focus on what you can control and better assess whether your continued efforts are worth the expense. Expending effort and emotion on things you can’t control can be both draining and disempowering","I":"Research indicates that people link their self-identity and social status to their commitments. And because we identify with our commitments, withdrawing from one can feel like a threat to our identity or status","J":"Take my client Ryan, a leader at a technology company. Ryan had invested two years and a lot of effort in a design project that wasn’t delivering the needed outcomes, but the thought of abandoning it after all she had put in was hard to bear. As Ryan and I explored whether she should cancel the initiative she’d been leading or continue to persevere, she stated, “The thing is, I’m not a quitter.” This singular, fixed sense of self was clouding her judgment and limiting her choices for action","K":"Our self-concept and identity are mental concepts that influence our behavior. If you strongly identify as not being a quitter, you can end up staying stuck in a course of action due to your narrow and rigid self -concept. To overcome this kind of internal obstacle, recall your other positive traits and personality characteristics. Ask yourself: What additional strengths do I have (or aspire to have) that would be helpful to employ here? For example, when I asked Ryan what other positive qualities from her personality she needed to leverage for decision making, she replied, “Discernment and bravery.”","L":"Now, examine your situation through the lens of each of these facets of yourself. What does the discerning part of you say? The brave part? Considering your decision through these different characteristics will enable you to see that you have more choices. It’s also helpful to seek external sources of information, rather than relying solely on your thinking and instincts. But it's important to think through whose opinions you solicit","M":"Ideally, seek out people who are less invested in your decision than you are. If you're considering whether to shut down your entrepreneurial venture, for instance, reach out to other founders as opposed to just your business partner. Similarly, if you're looking for love advice, ask someone removed from the ups and downs of your relationship instead of relying only on your best friend. In all cases, I recommend describing your situation and following up with a question like: “How would you manage this situation?”","N":"Alternately, you could also seek out hard data that illuminates your real chance of success in whatever endeavor you are contemplating. Sticking with the example of the entrepreneurial venture, numbers are your best friend. Use them to remove yourself from the love you have for this idea and consider your bum rate relative to growth plan, industry growth rates, and other factors that predict start -up success. External sources of information can help you see angles and possibilities you might not have considered","O":"When something that seemed so promising at the start doesn't turn out the way we imagined, we can become overly self- critical. Nobody likes to feel that they’ve made a poor decision, especially if making intelligent decisions is a quality you hold in high esteem. The most effective strategy here is to give yourself a break. Practicing self-compassion increases your resilience (韧性), emotional intelligence, compassion toward others, and can boost your performance as well as help you develop a growth mindset","P":"Instead of deliberating and criticizing yourself, focus instead on what you can learn from this situation. For example, Ryan recognized she had developed various new skills and leadership capabilities from leading the design project. And despite ultimately deciding to drop it, she was still happy she had tried and grateful for what the experience taught her","Q":"Undeniably, perseverance can help us succeed. But for your wellbeing, it’s important to learn how to distinguish quitting too soon and clinging to a losing course of action. While letting go can be difficult, it will free up your time, energy, and mental space to imagine new possibilities and pursue new opportunities"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O","P","Q"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"As interdependent beings we cannot thrive independent of others. We like to work with people who are like -minded, \nwith whom we share a common interest, or who also believe in a cause we are serious about. This is evident in how we have \norganised ourselves into various collective groups such as nations, regions, communities, organisations, and families. \nDoes the group you belong to have a strong collective consciousness or shared beliefs? Is there interdependence among \nits members? Do you consider this group a significant part of your existence? If your  answers are affirmative, then you are \nexperiencing a micro version of solidarity. \nWhat is solidarity? Its simplest definition in the dictionary is: “…a unifying opinion, feeling, purpose or interest among \na group of people.” \nIn this increasingly diverse society we live in, solidarity takes on a complex and multifaceted character as it forms bonds \nof interdependence among unique individuals living in a fast-changing environment and working within a complex division \n\f\nof labour. \nOne facet of solidarity fits well with the principles of communitarianism (社群主义). In this setting, individuals give up \ntheir own interests to serve the common good. However, its strict adherence to social cohesiveness and exclusiveness restricts \nexpression and practice of individual differences and preferences. Consequently, individuality and autonomy is sacrificed to \nmaintain the unity of the group. \nSolidarity is also viewed as a reaction to the extreme emphasis on individualism and freedom of choice. It goes against \nthe liberal idea of unrestricted individuals who see society as a hindrance to their freedom to make choices and to act according \nto what is good for them regardless of how these will affect others. \nBut despite its many facets, social theorists have viewed solidarity as a key factor in bringing about  order and progress \nin society. They believe that for human society to survive as it becomes more diverse,  more new bonds need to be formed \nbased on the differences. In the light of this, they regard a genuine solidarity as more than just shallow relationships based on \ncommon interests. Solidarity is not just a product  of strategic calculations of how much it will benefit the self. It is not an \nexclusive class founded on the you-and-me-against-the-world principle. Rather, it is inclusive and is not forced. Acting out of \nsolidarity means supporting and standing up for each other — in recognition that one’s fate is in the fate of the other. It is a  \nbond characterised by cooperative practices and strengthened by the concern for the well-being of others or the common good. \nIt fights for the protection of human dignity and listens to and acts on the cries of the most vulnerable.","questions":[{"n":46,"stem":"46. What does the author say about human beings?","options":{"A":"They cannot prosper without cooperating with each other","B":"They share a common interest and believe in a just cause","C":"They think and behave alike in different social groups","D":"They cannot gain independence without fighting for it"},"answer":"A"},{"n":47,"stem":"47. What do we learn about solidarity in an increasingly diverse society?","options":{"A":"It gives rise to a complicated division of labour","B":"It involves many aspects with great complexity","C":"It brings individuals together as environment changes","D":"It embraces the characteristics of different individuals"},"answer":"B"},{"n":48,"stem":"48. What would we witness in the setting of communitarianism?","options":{"A":"Ruling of social norms and ridding of individuality","B":"Emphasis on the adherence to individual differences","C":"Sacrifice of personal interests for the common good","D":"Elimination of individualism and personal choices"},"answer":"C"},{"n":49,"stem":"49. What does solidarity entail according to the passage?","options":{"A":"A limit to personal differences","C":"A hindrance to social advancement","B":"An opposition to individualism","D":"An inevitable end to liberal pursuits"},"answer":"B"},{"n":50,"stem":"50. What do social theorists think of solidarity?","options":{"A":"It is especially relevant to the most vulnerable","C":"It is essential to progress and order in society","B":"It is most effective in protecting human dignity","D":"It is indispensable to avoiding shallow relationships"},"answer":"C"}]},{"title":"Passage Two","passage":"People who repeatedly give unwanted advice can be well-meaning and genuinely want to help. Others might do this out \nof a sense of self-worth around the ability to influence others. One study found that people with a high tendency to seek power \nwere more likely to give advice than those with an opposite tendency.  \nUnder the guise (外表) of unselfishness, people may be driven to give you unwanted advice because it makes them feel \npowerful or in control. They may not be fully aware of this drive, however.  \nThese people may also display a problematic degree of emotional vulnerability, becoming upset very quickly, and taking \na long time to calm down. It is possible that their emotions were only validated in childhood when they were at their loudest, \nencouraging them to adopt responses to discomfort that are excessive in most situations.  \n\f\nWhen someone is giving advice in order to make themselves feel more powerful, there is underlying anxiety  to their \nbehavior that recipients of the advice tend to notice. It can be tempting in this situation to react harshly  to the advice giver \nand to accuse them of being manipulative, but this approach might produce an undesirable result. \nIf the act of giving advice is contributing actively to someone’s feelings of self -worth, an outright ( 直率的) rejection \nmay be perceived as a threat, activating their fight -or-flight response, possibly causing them to double  down on their \nvalidation-seeking behavior, or leading to a larger conflict.  \nThe key is to validate without over-identifying. You can let them know that you have heard them and appreciate where \nthey are coming from without taking on the potentially damaging narrative that you could not  have gotten by without their \nhelp. You had better say something like, “Thanks for the idea. I have my own plan  for handling this, but I really appreciate \nyour perspective and will take it into consideration. Can I let you know when I need help in the future?” \nIf you have trouble setting boundaries tactfully, prioritize working on your own ability to self-regulate. As uncomfortable \nas it may make you continuously receiving unwanted advice, if you can respond with compassion,  the situation will likely \ndiffuse much faster. \nThough it is usually not the intended out come of giving unsolicited advice, many who receive it often feel  stressed, \noffended, or simply annoyed by unwanted suggestions. Setting a boundary in this regard, if you feel you need one, is perfectly \nreasonable and something that can bring you increased emotional safety.  \nIt is best to set boundaries in a way that takes into account the individual ’s underlying reasons for doing what they are \ndoing to avoid unnecessary conflict and more stress.","questions":[{"n":51,"stem":"51. What is the finding of one study about people who keep giving unsolicited advice?","options":{"A":"They turn out to be well-meaning","C":"They are capable of influencing others","B":"They are genuinely kind-hearted","D":"They are inclined to crave for power"},"answer":"D"},{"n":52,"stem":"52. What is the problem with people who are driven to give you unsolicited advice?","options":{"A":"They may be quick to upset others","C":"They want their voice to be the loudest","B":"They may be emotionally vulnerable","D":"They respond to discomfort excessively"},"answer":"B"},{"n":53,"stem":"53. What is the advice receiver tempted to do when noticing the advice giver's underlying anxiety?","options":{"A":"Reveal the undesirable result of their approach","C":"Bring their real motives to the surface","B":"Refuse their advice in an undisguised manner","D":"Accuse them of trying to control others"},"answer":"D"},{"n":54,"stem":"54. How is the advice giver likely to react to the rejection of their advice?","options":{"A":"They may regard it as a threat","C":"They get ready for a larger conflict","B":"They may modify their behavior","D":"They begin to doubt their self-worth"},"answer":"A"},{"n":55,"stem":"55. What should the advice receiver do to avoid unnecessary conflict?","options":{"A":"Concede the advice is perfectly reasonable","B":"Give their reasons for not taking the advice","C":"Understand why the advice giver offers the advice","D":"Explain their chosen way of handling the situation"},"answer":"C"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n\n中华民族崇尚自强自立的精神，这一精神深植于中国文化之中，是民族生存与发展的重要支撑。改革开放以来，中\n国在自强自立的征程上，持续加大科研投入，在信息技术、人工智能、航天工程等领域不断取得新突破。5G 网络覆\n盖全国，远程医疗发展迅速，电子支付的使用全球领先，嫦娥探月工程展现了航天领域引人注目的发展。自强自立\n精神成为推动国家现代化进程的强大动力，激励着中国人民为实现民族复兴(rejuvenation)的中国梦不断奋进。","guide":["先拆句：政策背景→数据→质量/研发→作用。","关键词：private economy, support policies, high-quality development, core competitiveness。","数字与百分比要准确。"]},"answersReady":true},{"id":"2025-12-cet6-3","level":"CET6","year":2025,"month":12,"set":3,"title":"2025 年 12 月 · CET6 第 3 套","source":"2025年12月 第3套","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence “It is believed that\nteachers can exert a profound influence on their students’ academic pursuit and personal development.” You can make\ncomments, cite examples or use your personal experiences to develop your essay. You should write at least 150 words but no\nmore than 200 words.\nYou should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":["先明确建议对象与目的。","两条具体建议 + 一条预期效果。","结尾礼貌收束，不引入新论点。"]},"listening":{"audio":"","note":"本套官方未提供听力。","groups":[]},"cloze":{"passage":"It’s best to think of an accent as a distinct, systematic and rule-governed way of speaking. Accent is not a ___26___ for \ndialect, but it’s related. Dialect is an umbrella term for the way a community pronounces words,  creates words, and orders \nwords; accent refers to that first part only. \nMany ___27___ presume that there is a single standard way of speaking in each country, with one single standard accent, \nand that this perceived standard is ___28___ the best form of speech, but linguists (语言学家) often point out that the concept \nof a standard accent is better understood as an ideal rather than a ___29___. In other words, no one speaks “standard English”; \nrather, it is an imagined way of using language that exists only in grammar and style books. \nOne reason linguists agree there is no one true  standard is that, through the years, there have been  ___30___ supposed \nstandards, depending on time and place. The standard for English in British newsreels (新闻片) from the 1950s, for example, \ndiffers greatly from the standard found on American national ne ws broadcasts today. In fact, there has never been a single \nstandard that’s been fully agreed upon  — and broadcast outlets across the ___31___ have never consistently held to those \nstandards anyway. \nEven so, this idea of a standard accent is ___32___ and many workplace and educational environments perpetuate the \nidea that accents that ___33___ from the current standard are less appropriate, or even inappropriate.  Scholars have found \nthat southern U.S. accent features are more accepted in ___34___ such as government, law and service-oriented workplaces, \nbut less accepted in the technology sector. The acceptability of nonstandard accents may ___35___ with differences in class \nand culture, with newer or higher prestige industries expecting more standard speech in the workplace.","bank":[["A","affix"],["I","properties"],["B","correlate"],["J","reality"],["C","deviate"],["K","reciprocally"],["D","domains"],["L","specimen"],["E","influential"],["M","spectrum"],["F","inherently"],["N","synonym"],["G","laymen"],["O","unanimous"],["H","multiple"]],"answers":{"26":"N","27":"G","28":"F","29":"J","30":"H","31":"M","32":"E","33":"C","34":"D","35":"B"}},"matching":{"statements":[{"n":36,"text":"36. Upon seeing a flashing yellow arrow, a driver should let pedestrians and traffic pass first before taking the turn","answer":"Q"},{"n":37,"text":"37. The red and green automatic traffic light system originated in an American city","answer":"I"},{"n":38,"text":"38. Residents of an American city tend to share the opinion that time saved on the road justifies the cost of upgrading its traffic light system","answer":"A"},{"n":39,"text":"39. Mass production of cars made it possible for ordinary people to buy them","answer":"J"},{"n":40,"text":"40. What a traffic light means is almost the same everywhere despite some variations","answer":"R"},{"n":41,"text":"41. Pedestrian crossings came into being only in the mid-twentieth century","answer":"L"},{"n":42,"text":"42. People raced to address increasing traffic problems along with the expansion of cities and traffic","answer":"F"},{"n":43,"text":"43. When the warning yellow light was introduced, driving became safer and traffic accidents reduced","answer":"K"},{"n":44,"text":"44. The signal system on the railroad served as the basis for the first traffic light","answer":"B"},{"n":45,"text":"45. Even though a green light signals “go”, attention should be paid to traffic on either side in case some driver is being careless or ignoring a red light","answer":"N"}],"paragraphs":{"A":"Timed traffic lights are set according to schedules that are supposed t o coordinate with peak traffic hours. Cities need to monitor and update signal light time schedules at least every two years to keep these systems effective. In Los Angeles, California, an ambitious project to go a step further and synchronize (使同步) every red light in Los Angeles cost over 400 million dollars. Ask a resident of the city and they are likely t o agree that saving time on the road is well worth it. If implemented nationwide, synchronization could shave 10% off traffic congestion ( 堵塞 ) and 20% of f air pollution. Congestion costs time, money, and lives. Big data can help improve how millions of people safely share the road. However, none of this would be possible without the traffic light!","B":"The first traffic light was invented in London in the 1860’s, but it was hardly recognizable — or effective. It had been adapted from the railroad signal system by a railway manager, John Peak Knight, in 1868. The railroads used red gas lights at night to signal stops and green gas lights during the daytime. Knight installed a similar gas light, semaphore (臂板信号) system near London’s Westminster Bridge in December of 1868","C":"The life of the first traffic light signal was short -lived. A gas leak caused one of the signal lights to explode on its police officer operator within a month of being installed","D":"Automating traffic signals stalled after the London incident. Forty years passed before cars crowding city streets urged the development of traffic lights in the United States. London would not see another traffic light until 1929","E":"The United States is a car culture like no other country. Unlike most European cities that started urban planning when horses were high-tech, many cities in the United States were designed around urban sprawl, suburban tracts, and motor cars","F":"As traffic and cities grew, so did the race to solve growing traffic problems. The first traffic signals were semaphores. Semaphores are towers with moving arms signaling for traffic to stop or go. They could be manual or automatic. There was no consistent design. Various models were invented and put into place in cities as the need arose","G":"In 1912, Lester Wire was a police officer exhausted by traffic at Main Street and 200 South. He developed a manually switched stop light. The four-sided box, raised on a ten-foot pole, looked like a birdhouse and was operated manually by an officer. The officer would flip a switch to change between the dipped red and green lights","H":"Like the 1910 semaphore, the first electric signal used words. However, the words were no longer written on arms that raised and fell. The words “stop” or “move” were on lights. The posts lit up on each of four comer-posts around an intersection (十字路口). It was not automated, though. A booth with an operator was required to flip the switches","I":"The system allowed police officers to move from the middle of the street to a co rner. From that vantage ( 有利地位), an officer could oversee the crowd. If an emergency vehicle came, the officer could flip a switch and clear the intersection by triggering all red lights. The emergency vehicle could now pass ef fortlessly. Finally, in San Francisco , the first red and green electric light system that could be operated automatically (or manually) was introduced in 1917","J":"In 1920, the first three-color light system was introduced in Detroit — also known as Motor City, USA. The evolution of traffic light signals could not have a more appropriate context than Motor City. Ford Motor Company was founded in Detroit in 1903 (and other motor companies followed). Ford made cars affordable for more common people, rather than the wealthy, by creating larger scale factory production","K":"Stop and go were insufficient for the new volumes of cars zooming through intersections. Streets were full of new numbers of cars in addition to delivery wagons, bustling crowds, bicycles, horse-drawn carriages, and street cars. The introduction of the cautionary yellow light helped increase driver safety, decreasing accidents that come from running red lights","L":"Stop lights were incredibly important in chaotic city streets. Crosswalks weren ’t even introduced until 1951. The first pedestrian fatality in the United States was in 1899","M":"The development of the modem traffic light may have started in London, but it grew up in the United States. In Cleveland, an African-American inventor named Garrett Morgan came up with an affordable, patented traffic signal. The yellow light made intersections safer than the old stop and go system. The new design was inexpensive enough that it allowed the installation of a lot more lights","N":"Morgan sold the patent to General Electric — and the spread of the traffic light was green lighted. Green means go. It is that simple, but it’s still best to check both ways for oncoming traffic that may not be paying attention or is running the light. Yellow means slow down and prepare to stop. It does not mean full-throttle (全速) ahead. While you may get away with gunning it into the intersection, running a yellow can lead to tickets and dangerous accidents. Red lights are a clear and consistent warning to stop. Even where right turns are allowed on red lights, you must come to a complete stop before turning right. You must also yield to any through traffic, which has the right of way. In most states and cities, you can take a right on red unless otherwise indicated. New York City does not allow a right on red","O":"Red arrows mean you cannot turn right on a red in most states. The green arrow, in these cases, is the only time you can make the turn. However, you can take a right on a red arrow after a full stop in the states of Illinois, Kansas, Louisiana, Maryland, Michigan, New Hampshire, North Dakota, Oregon, South Carolina, Utah, Washington State and Wyoming","P":"Flashing Red is the same as a stop sign, generally used at four -way intersections where there is minimal traffic. When arriving at a flashing red light, make a full and complete stop. Flashing Red Arrows similarly mean to stop and then proceed to take the turn. Flashing Yellow lights mean yield or signal caution, like outside of a fire station. There are no all-direction flashing yellow lights, since it is prohibited in the United States. If you have a flashing yellow light, you are to yield to oncoming traffic","Q":"Flashing Yellow Arrows are part of a four -signal traffic light. These are used in some states after a protected green turn signal, or arrow, but before a steady yellow arrow. When a flashing yellow arrow is shown, you can take the turn after yielding to pedestrians and traffic. Steady Yellow Arrows maintain the normal yellow light caution in three-light signals, meaning to stop or prepare to stop. In a four -signal system that has a flashing yellow arrow, the steady yellow arrow is a signal that the yield period is ending. The red arrow is about to start. Vehicles should stop if safely possible. Traffic tickets are possible for running a steady yellow arrow","R":"Traffic light meaning is fairly consistent across the board with various deviations. Green means it’s safe to proceed (though you should still exercise caution). Yellow means caution and yield. Red means danger and stop. Always drive defensively and obey traffic signal"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O","P","Q","R"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Mindfulness has been shown to have a number of meaningful health benefits — it can help reduce anxiety and promote \nhealing in those suffering from chronic illness. \nThe practice is based on an insight first described in ancient Buddhist texts that human beings have  the capacity to \nobserve experience without being caught up in it. This means simply that it is possible to observe ourselves having a craving, \nor a happy thought, or even a scary emotion, without reacting in the moment in a way that amplifies the feeling or sends the \nmind spiraling off into thinking about old memories or anticipating events. \nThis practice of mindfulness can help calm the mind and the body as we learn not to react to experience  with likes and \n\f\ndislikes or judgments of good and bad. It does not make us cold or indifferent but more fully present. \nOne of the challenges of practicing mindfulness in o ur contemporary world is that there has been a profound  \ntransformation in human attention. The artist Jenny Odell argues that in our “attention economy” human attention has been \ntransformed into a commodity that big corporations buy and sell. This economy rests on a technological revolution of mobile \nphones and social media that makes it possible for corporations to target our attention with their content at every moment. \nThe devices most people use are a perpetual diversion from the present moment. The result is that it can feel as though \nour ability to focus, and be fully present, has been stolen. But mindfulness can help us resist the attention economy and relish \nthe things that make life special, like being together with those we love. \nMost mindfulness research focuses on the individual benefits of the practice, but some scholars assert that  we can not \nonly practice mindfulness for ourselves but also practice it for others. It can help us build stronger, healthier relationships. \nThe sad truth is that living in the attention economy, most of us have become bad listeners. However, just as it is possible \nto watch ourselves having an experience without reacting, it’s possible to watch another person have an experience without \ngetting tied up in reactivity and judgment. \nThe gift of mindfulness is a practice of listening with compassion to others describe their experiences.  To give this gift \nmeans putting away your phone, turning off social media, and setting aside other common  distractions. It means practicing \nbeing fully present in another person ’s presence and listening to them with  complete attention without judgment, while \nresisting the urge to make the interaction about you. \nIf we judge the value of gifts based on their price, this gift may seem worthless, but in a distracted world, itis a precious \none.","questions":[{"n":46,"stem":"46. What do we learn from the passage about practicing mindfulness?","options":{"A":"It triggers our mind to reflect on past experiences or anticipate future events","B":"It focuses our attention on the present moment without making judgments","C":"It concentrates our mind on our personal feelings, happy or scary","D":"It helps our mind to stay calm when facing judgments from others"},"answer":"B"},{"n":47,"stem":"47. What do we see in today’s “attention economy” according to Jenny Odell?","options":{"A":"Focus on technological advances continuously updates products and services","B":"People’s attention is turned into something that can be bought and sold","C":"Businesses profit from selling mobile phones and revolutionizing social media","D":"People tend to purchase products and services without careful thinking"},"answer":"B"},{"n":48,"stem":"48. What happens with the prevalent use of mobile phones or social media?","options":{"A":"They keep distracting users from the here and now","B":"They render users incapable of resisting temptation","C":"They rob users of their ability to observe experience","D":"They tempt users to endorse the attention economy"},"answer":"A"},{"n":49,"stem":"49. What benefit can practicing mindfulness bring to us according to some scholars?","options":{"A":"It prevents us from making arbitrary judgments about others","B":"It shifts our attention from material things to spiritual pursuits","C":"It is conducive to our forging better interpersonal relationships","D":"It is helpful in regaining our ability to enjoy what we have in life"},"answer":"C"},{"n":50,"stem":"50. What does the author suggest we do in another person's presence?","options":{"A":"Share each other’s experience frankly and compassionately","B":"Pay full attention to establishing close relationships with them","C":"Be attentive listeners while refraining from making judgments","D":"Remind them of the distraction from mobile phones and social media"},"answer":"C"}]},{"title":"Passage Two","passage":"The other day I had to log into a service I hadn’t used before. Since I was a new user, the website decided that it needed \n\f\nto check I wasn’t a robot and so set me a Captcha test to determine whether the user is a person or a machine. \nI was presented with an image of a roadside scene over which was laid a grid. My “challenge” was to click on each cell \nin the grid that contained a traffic sign. I did so, a bit irritated. Then I was presented with another image and another grid — \nalso with a request to identify road signs. Like a lamb, I complied, after which the website accepted my input. \nAnd then I realised what I had been doing was adding to a dataset for training the machine-learning software that guides \nself-driving cars. So, to gain access to an automated service that will benefit financially from my input, I first have to do some \nunpaid labour to help improve the performance of autonomous vehicles. \nNeat, eh? But note also the delicious additional irony that the Captcha is described as an “automated Turing test”. The \nTuring test was conceived, you may recall, as a way of enabling humans to determine wheth er a machine could respond in \nsuch a way that one couldn ’t tell whether it was a human or a robot. So we have  wandered into a world in which machines \nmake us do tricks to prove that we are humans! \nThe strangest aspect of this unparalleled shift is how under-discussed it has been. The metaphor of the boiling frog comes \nto mind. Have we become so subtly conditioned by digital technology that we don't see  what’s been happening to us? Have \nwe been conditioned to accept a world governed by “smart” tech, trading convenience to the point where we become a bit \nlike machines ourselves? \nIn a recent startling and thoughtful book, two scholars  — Brett Frischmann, a law professor, and Evan  Selinger, a \nphilosopher — argue that the answer to that question is “yes”. \nAnd they're right. There's nothing technophobic (技术恐惧的) about that. We shape our tools and then our tools shape \nus. Technology is supposed to provide tools that serve human ends. But, as the machine -learning Captcha demonstrates, a \nsignificant proportion of digit al tech now sees (and uses) humans as means to ends that  are not ours. In the process, they \nreduce us to the status of cheery rats running on treadmills (踏车) designed by people who do not have our interests at heart. \nSo back to the frog metaphor. Are we smart enough to jump out before it’s too late? You don’t even have to Google it to know \nthe answer.","questions":[{"n":51,"stem":"51. How did the author respond to the Captcha test?","options":{"A":"He clicked on the cells randomly","C":"He completed it confidently","B":"He accepted the challenge readily","D":"He worked on it submissively"},"answer":"D"},{"n":52,"stem":"52. What is ironic about the Captcha test?","options":{"A":"A machine can respond to the test as well as humans do","B":"A machine can outperform humans in object identification","C":"A test designed to test machines is now used by machines to test humans","D":"A test conceived to tell a human from a robot can now do tricks humans can’t"},"answer":"C"},{"n":53,"stem":"53. Why does the author use the metaphor of the boiling frog?","options":{"A":"To show that humans are unwilling to trade convenience for control by smart tech","B":"To show that humans are unaware of the potential danger brought by smart tech","C":"To question whether humans are conditioned to accept digital tech","D":"To question whether humans are as vulnerable as the boiling frog"},"answer":"B"},{"n":54,"stem":"54. Why does the author think that Brett Frischmann and Evan Selinger are right?","options":{"A":"A large part of digital tech is now making use of humans to meet its own ends","B":"Humans are now fast locked in a race against digital tech to control the world","C":"Digital tech can serve human needs in ways previously thought impossible","D":"Digital tech is now doing thinking while humans are doing repetitive work"},"answer":"A"},{"n":55,"stem":"55. What does the author imply by asking “Are we smart enough to jump out before it’s too late?” at the end of the passage?","options":{"A":"It is not sensible to expect digital tech to take humans’ interest to heart","B":"It is hard to say whether technology or humans will get the upper hand","C":"We may have to search the web to get the answer to the question","D":"We may not awake in time to the danger digital tech poses to us"},"answer":"D"}]}],"translation":{"prompt":"Directions: For this part, you are allowed 30 minutes to translate a passage from Chinese into English. You should write your\nanswer on Answer Sheet 2.\n节俭(frugality)是中华民族的传统美德。在中国古代，生产力低下，先人们深知劳动成果来之不易 ，因而秉持节俭\n的理念。到了物质极大丰富的今天，中国人民依然坚持节俭的生活方式，体现了理性消费的生活理念和对劳动的\n尊重。近年来，中国政府持续加强节约型社会的建设，倡导“光盘行动”，减少食物浪费，提倡简约低碳的生活方\n式，推进资源循环利用，反对过度消费。节约型社会的建设有力地推动了中国经济的高质量发展。","guide":["先拆句：政策背景→数据→质量/研发→作用。","关键词：private economy, support policies, high-quality development, core competitiveness。","数字与百分比要准确。"]},"answersReady":true},{"id":"2025-06-cet6-1","level":"CET6","year":2025,"month":6,"set":1,"title":"2025 年 6 月 · CET6 第 1 套","source":"2025年6月 第1套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"Met the computer technician","C":"Called the man’s company","B":"Told the man about her trouble","D":"Visited Alpha Maintenance"},"answer":"C","stem":""},{"n":2,"options":{"A":"Consulted someone in charge","C":"Informed the central office at once","B":"Came as soon as possible","D":"Designated an engineer to the case"},"answer":"B","stem":""},{"n":3,"options":{"A":"Frustration","C":"Desperation","B":"Intimidation","D":"Indignation"},"answer":"D","stem":""},{"n":4,"options":{"A":"Whether the contents have been backed up","B":"Whether they can find help somewhere else","C":"Whether all data stored on the hard drive has got lost","D":"Whether they need to wipe the system directories clean."},"answer":"A","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"It’s boring","C":"It’s a beautiful thing","B":"It’s challenging","D":"It’s unlike most jobs"},"answer":"A","stem":""},{"n":6,"options":{"A":"Arbitrating between disagreeing solicitors","C":"Buying and selling property","B":"Preventing disputes from escalating","D":"Mediating land disputes"},"answer":"D","stem":""},{"n":7,"options":{"A":"Courts are intended for fixing major legal disputes","B":"Courts are getting too bureaucratic to function","C":"Courts can be frustrating and expensive","D":"Courts can be frightening and arbitrary"},"answer":"C","stem":""},{"n":8,"options":{"A":"The ability to make arguments in a unique way","B":"The skill of preventing conflicts between parties concerned","C":"The skill of foreseeing any potential stakes in their work","D":"The ability to express themselves clearly and forcefully"},"answer":"D","stem":""}]},{"intro":"Questions 9 to 11 are based on the you have just heard","questions":[{"n":9,"options":{"A":"They looked into the relationship between one’s prior knowledge and creativity","B":"They offered novel ways to help older adults to keep their memories from aging","C":"They proposed an explanation for old people’s difficulty in retrieving memories","D":"They advanced a new model concerning human information storage and retrieval"},"answer":"C","stem":""},{"n":10,"options":{"A":"Young adults rely on memory while older adults keep notes as a reminder","B":"Older adults often retrieve irrelevant memories along with what they want","C":"Young adults accumulate knowledge much more quickly than older adults","D":"Older adults generally perform cognitive tasks much slower than young adults"},"answer":"B","stem":""},{"n":11,"options":{"A":"They show preserved, and sometimes enhanced, creativity","B":"They frequently suffer from disorderly crowded memories","C":"They can rely on their accumulated wisdom in an emergency","D":"They may well be served by forgetting their prior knowledge."},"answer":"A","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"They are actually proud of the goods and services they produce","B":"They are worried about being alienated from the outside world","C":"They are rarely in control of many things related to their work","D":"They are longing to share the profits made from their work"},"answer":"C","stem":""},{"n":13,"options":{"A":"The steady decrease in productivity","C":"The feeling of being time poor","B":"The adverse effect on physical health","D":"The rising economic inequality"},"answer":"C","stem":""},{"n":14,"options":{"A":"It alters the structure of work","B":"It puts jobs and wages at risk","C":"It liberates people from tedious and laborious work","D":"It creates new work opportunities in the IT industry"},"answer":"B","stem":""},{"n":15,"options":{"A":"Finding meaning in work","C":"Improving relationships in the community","B":"Prioritizing life over work","D":"Realizing one’s social value in the workplace"},"answer":"B","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"Affect our attitude to novel tasks","C":"Outweigh IQ in importance","B":"Distinguish us in the social world","D":"Impact academic achievements"},"answer":"D","stem":""},{"n":17,"options":{"A":"By pressing a hidden button","C":"By pressing two buttons at the same time","B":"By pushing a big button on top","D":"By helping the babies push the right button"},"answer":"A","stem":""},{"n":18,"options":{"A":"Perform difficult tasks successfully just by observing how adults acted","B":"Make generalizable inferences about persistence from a few examples","C":"Adapt themselves to different social contexts","D":"Work hard to interact with experimenters."},"answer":"B","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"Offering advice on overcoming habitual lateness","B":"Exemplifying various recreational opportunities","C":"Scrutinizing individuals’ defining traits","D":"Suggesting ways for setting priorities"},"answer":"A","stem":""},{"n":20,"options":{"A":"Make the breakfast simpler","C":"Ready yourself in the early dawn","B":"Take the alarms seriously","D":"Get prepared the night before"},"answer":"D","stem":""},{"n":21,"options":{"A":"Finish the prior task 30 minutes earlier","C":"Leave time in between activities","B":"Keep ourselves from hitting a bump","D":"Try to avoid possible hold-ups."},"answer":"C","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Their lifestyles vary","C":"They have different customs","B":"Their traits vary","D":"They have different feels"},"answer":"D","stem":""},{"n":23,"options":{"A":"They are not as willing to help strangers","C":"They violate traffic rules more frequently","B":"They are not as patient with one another","D":"They become more easily irritated in public"},"answer":"A","stem":""},{"n":24,"options":{"A":"It was practiced by Boston’s founding fathers","C":"It was adopted by Boston’s upper class","B":"It is not deemed exotic by Proper Bostonians","D":"It is not part of Boston’s local culture"},"answer":"D","stem":""},{"n":25,"options":{"A":"Stick to its own way of showing courtesy to strangers","B":"Follow the examples set by Paris and New York City","C":"Learn from the world’s major cities in promoting tourism","D":"Take pride in its history and adhere to its cultural tradition"},"answer":"B","stem":""}]}]},"cloze":{"passage":"In her second year, Charlene Duong learned of the use of poisonous, synthetic pesticides on her college campus. Shocked \nbut not surprised, she knew she had to do something. Along with a couple of classmates, Charlene did a quick web search and \ndiscovered a small but growing movement led by the organi zation, Herbicide-Free Campus (HFC), to rid college campuses \nof artificial herbicides (灭草剂). They were ___26___.  \nLike many, Charlene experiences climate anxiety —a ___27___ fear of a climate catastrophe  — and was, at the time, \nlooking for an ___28___. When she discovered the HFC movement, she said she felt she “had found a specific area to focus \non that still fit into the larger picture of fighting for a healthier, safer, cleaner ___29___ for all.”  \nToxic herbicide use in university land care is not unique. Most institutions of higher education rely on synthetic pesticides \nand fertilizers to achieve ___30___ goals. Having a “beautiful” campus means green and perfectly maintained lawns along \nwith flower beds and paved sidewalks. But these ___31___ managed campuses can come at a cost: increased cancer risk, \n___32___ waterways, poisoned wildlife and lifeless soil.  \nPesticide use on college campuses also contributes to our global climate crisis. The use of chemicals to get rid of insects \nor unwanted plant life can increase indirect ___33___, as they can include petroleum -based ingredients. Pesticide use also \ndecreases the life in soil, ___34___ the ability of soils to absorb carbon or retain water and thus reducing campuses ability to \nrecover quickly from climate-related extreme weather events like droughts and floods.  \nInstead of using toxic chemicals, students working with HFC help out with ___35___ the campus grounds.  \n“This work reminds me to be in the present moment as I play my role in reducing herbicide use and keeping my campus \nsafe and healthy,” says Charlene.","bank":[["A","aesthetic"],["I","infringement"],["B","chronic"],["J","intrigued"],["C","contaminated"],["K","juvenile"],["D","conventionally"],["L","outlet"],["E","emissions"],["M","rotating"],["F","environment"],["N","vibrations"],["G","hampering"],["O","weeding"],["H","incidentally"]],"answers":{"26":"J","27":"B","28":"L","29":"F","30":"A","31":"D","32":"C","33":"E","34":"G","35":"O"}},"matching":{"statements":[{"n":36,"text":"36. People going to the library in search of information can build connections with each other there","answer":"G"},{"n":37,"text":"37. According to advocates of libraries as community builders, librarians are not doing their job well if they do not change their communities","answer":"C"},{"n":38,"text":"38. With the costs of education continually rising, public libraries remain places where all people can have access to education","answer":"I"},{"n":39,"text":"39. Libraries draw large crowds, thus creating lots of business opportunities in neighboring areas","answer":"D"},{"n":40,"text":"40. With the world more and more digitalized, people sometimes underestimate the role of libraries as community and cultural centers","answer":"A"},{"n":41,"text":"41. Various programs organized by public libraries for children and adolescents help narrow the gap between students from varying economic backgrounds","answer":"L"},{"n":42,"text":"42. In an organized archive, people can do research on their family history and find out how their ancestors came to settle in the new land","answer":"F"},{"n":43,"text":"43. Public libraries organize cultural events, often allowing people of different income levels to attend free of charge","answer":"H"},{"n":44,"text":"44. Besides being an information provider, the library performs many other important services for the community","answer":"B"},{"n":45,"text":"45. Public libraries can help build small communities of people with different backgrounds and ideologies","answer":"K"}],"paragraphs":{"A":"Librarians know the value of their community services, and their patrons appreciate their importance as well. But in an increasingly digital world, we see the role of libraries as community and cultural centers at times undervalued. When shrinking municipal budgets combine with the nonstop technological revolution, public libra ry services that focus on building communities face-to-face, inspiring and educating patrons about art, literature, and music, and helping patrons engage in civil discourse can seem old -fashioned. But it is precisely those shrinking budgets and the assault of technologically mediated life that make public libraries cultural and community offerings more important than ever","B":"Many people point out the value public libraries bring to their communities. More than just books and banks of computers, libraries are still places where individuals gather to explore, interact, and imagine. Some of the specific ways in which libraries add value to our communities and serve as cultural centers for our patrons are community builders, centers for the arts, and champions of youth. Libraries serve in these capacities and are more than just about information","C":"As community builders, libraries are engaged in incredible work. From tiny public libraries to huge city institutions with multiple branches, libraries across the United States are building community and supporting local culture in exciting ways. These are inspiring and hopefully will encourage librarians interested in community services and cultural outreach to make connections with each other, share ideas, and build partnerships. Supporters of libraries as community builders claim that unless you are out there changing neighborhoods, you are not completing the work you are to do. Strengthening neighborhoods and championing the cultural lives of communities are big responsibilities","D":"Place-based economic development stresses the importance of offering attractive, functional and community-based places, such as libraries, in town squares and depressed neighborhoods. Like a major department store in a mall, libraries attract large numbers of people, creating economic opportunities for numerous businesses and organizations in the surrounding area. Large cities, medium-sized ones, and even small towns have successfully transformed their libraries into the hubs (枢 纽) of vibrant neighborhoods","E":"As key municipal agencies, and focal points for community education, libraries are major players in creating livable, environmentally friendly cities and towns. The Urban Libraries Council released a report detailing the unique wa ys in which libraries can further sustainability at the local level. Beyond ensuring that library construction projects consider environmental impact, libraries can take a lead in supporting local foods and craftsmen, like the Peabody Institute Library’s partnering with local businesses to pioneer a farmers ’ market in their courtyard, or the Richmond Public Library ’s seed lending library which “nurtures locally-adapted plant varieties, and fosters community resilience (韧性), self-reliance and a culture of sharing.”","F":"Archives preserve historic artifacts, oral histories, digital history projects, and scholarly writings relevant to the community, including minority groups. Communities lucky enough to have archivists have a great advantage when it comes to organizing historical records and artifacts. An organized archive is a place where people can research their ancestry and immigration history, do environmental research, and more. An archivist is an advocate for preservation who, among other things, coordinates the restoration of maps and paintings, the digitization of vital records, and the creation of oral history projects. With projects like the Massachussets Memories Road Show and the Veterans History Project , evidence of the importance of archives is everywhere","G":"In the words of Robert Putnam, “People may go to the library looking mainly for information, but they find each other there.” New moms connect at baby story-times; elderly people, often facing difficult life transitions, attend events and find that they make new friends; teenagers meet up in libraries’ teen spaces after school; and readers discuss current events in the periodicals room. In libraries, community-building connections are happening all the time","H":"As Keith Richards said, “The public library is the great equalizer.” Despite the rising costs of concert and theater tickets, public library events (including concerts, author visits, and gallery displays) are often offered free of charge, enabling people of any income level to attend. In addition, library book groups allow people to explore and discuss the literary arts, and the Great Stories Club introduces at-risk youth to literature. The best part: it’s all free and open to the public","I":"In a time when education is increasingly expensive, public libraries provide information and educational opportunities free for all people, regardless of their socio -economic status. Offered by libraries across the country, American Library Association’s Let’s Talk about It programs are wonderful examples of scholar-facilitated learning opportunities in libraries. In addition, many libraries present classes and discussion programs and some even provide online continuing education courses such as the Universal Class database","J":"Librarians know that patrons aren ’t just information consumers they’re information producers. Patrons use the library to gain knowledge in order to create their own new and independent works. Increasing numbers of libraries provide spaces and services that meet the needs of people who want to learn how to edit Wikipedia, set up blogs or podcasts, create their own magazines, and so much more. Many libraries offer art or writing workshops and groups, and some provide music practice rooms for patrons. Programs like ImaginOn in Charlotte, North Carolina, provide exciting models that take community partnership, creativity, and creation to a new level","K":"The decline of civil discourse stems in part from the fact that it is so easy for people to watch news about, buy products from, and engage —in both the virtual and real worlds —only with those of similar backgrounds and ideologies. Public libraries, through such programs as The Human Library and Socrates Café, can help build small communities of difference that encourage people to interact with and learn from each other through dialogue. By both actively promoting civil discourse through these programs, and modeling and upholding the principles of free inquiry and expression for all, libraries help individuals rediscover the importance of and increased need for civil discourse in American life","L":"Free tutoring, homework help programs, and summer reading programs for kids and teens help bridge the economic divide that impacts students’ academic performance. The cost of hiring a private tutor is well beyond what many library patrons can afford, so libraries offer homework help and tutoring online, by phone, in person, and even through social media and homework apps. Annual summer reading programs also have a positive impact on student performance and, according to a 2010 study conducted by Dominican University’s Graduate School of Library and Information Science, students’ reading skills get a boost from these popular nationwide events","M":"Through library collections, programs, and physical spaces, children learn to share to be engaged in their communities, to participate in the arts, and to explore their immediate world and the world at large. There are surely end less examples of innovative library services for children including the Middle Country Public Library ’s Nature Explorium, which engages children in learning about the natural world","N":"These examples are just a few of the many amazing things that public libraries around the Un ited States (and the world) are doing to build and maintain strong community connections. We encourage you to try some of these ideas in your own libraries, and we hope that these ideas will help you be better able to convince your community leaders of the important role that public libraries play in communities large and small"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Nationally, one in six children miss 15 or more days of school in a year. Education officials have deplored all this missed \ninstruction.  \nThese chronically absent students suffer academically because of all the classroom instruction they miss out on. In 2015, \nthe U.S. secretary of education responded to this crisis urging communities to support every student to attend every day and \nbe successful in school. His open letter stated that missing 10% of sch ool days in a year for any reason  — excused or \nunexcused — is a primary cause of low academic achievement.  \nWorrying about whether children attend school makes sense. After all, if students don ’t show up, teachers can ’t teach \nthem.  \nBut what if America’s attendance crisis is about much more than students missing class? What if instead, it is a reflection \nof family and community crises these students face — such as being ejected from the family apartment, fearing for their safety \nin their neighborhood or suffering an illness?  \nAs social scientists we investigated how excused and unexcused absences relate to children’s academic achievement.  \nWe find that absences excused by a parent do little to harm children ’s learning. In fact, children with no unexcused \nabsences — but 15 to 18 excused absences — have test scores equal to their peers who have no absences.  \nMeanwhile, the average child with even just one unexcused absence does much worse academically than peers with none.  \nWe believe unexcused absence is a strong signal of the many challenges children and families face, including economic \nand medical hardships. Unexcused absences can be a powerful signal of how those out-of-school challenges affect children’s \nacademic progress.  \nOur evidence suggests unexcused absences are problematic, but for a different reason than people often think. Absence \nfrom school and especially unexcused absence, matters mainly as a signal of many crises children and their families may be \nfacing. It matters less as a cause of lower student achievement due to missed instruction.  \nHow we choose to think of school absences matters for educational policy. School attendance policies typically hold \nschools and families accountable for the days children miss, regardless of whether they were excused or unexcused absences.  \nThese policies assume that missing school for any reason harms children academically because they are missing \nclassroom instruction. They also assume that schools will be able to effectively intervene by reducing student absen ces. We \nfind neither to be the case.  \nAs a result, these attendance policies end up disproportionately punishing families dealing with out -of-school crises in \ntheir lives and pressuring schools who serve them to get students to school more often.  \nWe instead suggest using unexcused absence from school as a signal to channel resources to the children and families \nwho need them most.","questions":[{"n":46,"stem":"46. What does the U.S. secretary of education say in his open letter?","options":{"A":"It is of vital importance to respond promptly to the school absence crisis","B":"The academic performance of chronically absent students is deplorable","C":"Low academic achievement is mainly attributed to school absences","D":"The effect of school absences on American education is worrisome"},"answer":"C"},{"n":47,"stem":"47.What do the authors find about school absences?","options":{"A":"Excused school absences have little impact on children’s learning","B":"There is little difference between unexcused and excused absences:","C":"Excused absences lead to comparatively better school performance","D":"Unexcused absences are a big challenge to both schools and families"},"answer":"A"},{"n":48,"stem":"48. What do the authors believe concerning unexcused school absences?","options":{"A":"They are likely to cause a decrease in students’ academic achievements due to missed instruction","B":"They point directly to many of the out-of-school challenges confronting children and their families","C":"They are matters the American government typically ignores when formulating educational policies","D":"They give a clear signal to children and their families of the crises they are likely to face in the future"},"answer":"B"},{"n":49,"stem":"49. What is the assumption underlying education policies in the U.S.?","options":{"A":"Children’s academic performance depends on reducing the number of absences:","B":"Schools can boost children’s academic performance by effective intervention","C":"Schools as well as families should be held responsible for out-of-school crises:","D":"Children’s academic performance is closely related to the quality of instruction"},"answer":"B"},{"n":50,"stem":"50. What do the authors suggest doing regarding school absences?","options":{"A":"Identifying their underlying causes","C":"Directing resources to helping needy children。","B":"Reframing school attendance policies","D":"Pressuring schools to reduce unexcused ones"},"answer":"C"}]},{"title":"Passage Two","passage":"After earning a bachelor’s degree, I was determined to do what I love. I headed straight to graduate school to investigate \nthe social problems that fascinated me.  \nFor almost a decade, I told everyone I encountered that they should do the same. “Follow your passion,” I counseled. \n“You can figure out the employment stuff later.”  \nIt wasn’t until I began to research this widely accepted career advice that I understood how problematic it really was.  \nAs a sociologist I interviewed college students and professional workers to learn what it really meant to pursue their \ndreams, which I will refer to here as the passion principle. I was stunned by what found out about this principle in the research \nfor my new book.  \nSurveys show the American public has long held the passion principle in high regard as a career decision-making priority. \nAnd its popularity is even stronger among those facing job instability.  \nAdvocates of the passion principle found it compelling because they believed that following one’s passion can provide \nworkers with both the motivation necessary to work hard and a place to find fulfillment.  \nYet, what I found is that following one’s passion does not necessarily lead to fulfillment, but is one of the most powerful \ncultural forces perpetuating overwork. I also found that promoting the pursuit of one ’s passion helps perpetuate social \ninequalities due to the fact that not everyone has the same economic resources to allow them to pursue their passion with ease.  \nWhile the passion principle is broadly popular, not everyone has the necessary resources to turn their passion into a stable, \ngood-paying job. Passion-seekers from wealthy families are better able to wait until a job t hey are passionate about comes \nalong without worrying about student loans in the meantime. They are also better situated to take unpaid internships to get \ntheir foot in the door while their parents pay their rent . And they often have access to parents ’ social networks to help them \nfind jobs. Surveys revealed that working-class and first-generation college graduates, regardless of their career field, are more \nlikely than their wealthier peers to end up in low-paying unskilled jobs when they pursue their passion.  \nColleges, workplaces and career counselors who promote the “follow your passion“ path for everyone, without leveling \nthe playing field, help perpetuate socioeconomic inequalities among career aspirants.  \nIt’s not just well-off passion-seekers who benefit from the passion principle, Employers of passionate workers do, too. \nPotential employers showed greater interest in passionate applicants in part because they believed the applicants would work \nhard at their jobs without expecting an increase in pay. They even sacrifice a good salary, job stability and leisure time to work \nin a job they love.","questions":[{"n":51,"stem":"51. What did the author advise people do for almost a decade?","options":{"A":"Figure out what is the most fascinating job","C":"Pursue their careers with passion","B":"Follow widely accepted career counsel","D":"Do whatever they are zealous for"},"answer":"D"},{"n":52,"stem":"52. How did the author feel about the passion principle through his research?","options":{"A":"He was astonished by its consequences","C":"He was actually right to follow it through","B":"He was further convinced of its soundness","D":"He was struck by its broad popularity"},"answer":"A"},{"n":53,"stem":"53. What is important to turning one’s passion into a stable, good-paying job?","options":{"A":"Willingness to take unpaid internships and low-paying jobs","B":"Full academic preparedness and sound career counseling","C":"Hard work and sacrifice of leisure time","D":"Financial backing and social connections"},"answer":"D"},{"n":54,"stem":"54. What happens when everyone is encouraged to follow their passion?","options":{"A":"Many more career aspirants end up unemployed","C":"Socioeconomic inequality is likely to persist","B":"People are less concerned with socioeconomic inequality","D":"Career counselors are going to lose credibility"},"answer":"C"},{"n":55,"stem":"55.What does the author say about employers of passionate workers?","options":{"A":"They provide these workers with job stability and a good salary","B":"They exploit these workers’ passion to benefit themselves","C":"They level the playing field for these workers to reach their goals","D":"They encourage these workers to realize their aspirations"},"answer":"B"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true},{"id":"2025-06-cet6-2","level":"CET6","year":2025,"month":6,"set":2,"title":"2025 年 6 月 · CET6 第 2 套","source":"2025年6月 第2套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"They have to make a choice by the end of the day","B":"Both candidates are very keen on getting the job","C":"They hold different views on the procedure","D":"Both candidates are quite competitive"},"answer":"D","stem":""},{"n":2,"options":{"A":"Both Rachel and Peter came across as respectful and professional","B":"Rachel scored moderately higher grades than Peter at school","C":"Both Rachel and Peter excelled in their academic pursuit","D":"Peter appeared slightly stronger than Rachel physically"},"answer":"B","stem":""},{"n":3,"options":{"A":"His use of body language","C":"His unusual state of mind","B":"His accumulation of experience","D":"His knowledge about the company"},"answer":"A","stem":""},{"n":4,"options":{"A":"Compare the candidates side by side again","C":"Find a way to break the tie next time","B":"Ask the board to cast the deciding vote","D":"Let John make the final decision."},"answer":"D","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"The private label “L’Orange”","C":"This season's new fashion","B":"The woman's latest collection","D":"The head designer's role"},"answer":"B","stem":""},{"n":6,"options":{"A":"Something reflecting the social norms","B":"Something meeting public expectations","C":"Something slightly absurd","D":"Something a bit ambiguous"},"answer":"C","stem":""},{"n":7,"options":{"A":"Merge styles often at opposite ends of the fashion spectrum","B":"Learn from the designs of the Asian rural mountain villagers","C":"Make velvet capes look both majestic and masculine","D":"Draw intricate patterns onto a traditional power suit"},"answer":"A","stem":""},{"n":8,"options":{"A":"Obtaining the woman's signature","B":"Seeing the woman's new creations","C":"Incorporating indigenous aspects into his work","D":"Sharing more ideas with the woman next time"},"answer":"B","stem":""}]},{"intro":"Questions 9 to 11 are based on the you have just heard","questions":[{"n":9,"options":{"A":"They could readily recognize their owner simply by looking","B":"They could understand the implications of human commands","C":"They could be domesticated to act as our companions","D":"They could follow pointing gestures without training"},"answer":"D","stem":""},{"n":10,"options":{"A":"Cultivating them to be intelligent creatures","B":"Training them to behave like domesticated dogs","C":"Understanding how humans impact their behavior","D":"Taking measures to reduce their numbers"},"answer":"C","stem":""},{"n":11,"options":{"A":"Tame them through repeated training","C":"Make them responsive to our commands","B":"Treat them with sensitivity and respect","D":"Watch their behavior and try to improve it."},"answer":"B","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"The temperature inside it varies from place to place","B":"Proper placement facilitates access to food products","C":"Its different shelves are designed for different purposes","D":"The space in an average fridge changes from top to bottom"},"answer":"A","stem":""},{"n":13,"options":{"A":"To slow the rising of temperature in it","C":"To prevent germs from growing quickly","B":"To provide a big box of evenly cold air","D":"To keep the food cold as long as possible"},"answer":"C","stem":""},{"n":14,"options":{"A":"On the top shelf","C":"On the inside of its doors","B":"In the middle section","D":"At the back of its bottom shelf"},"answer":"A","stem":""},{"n":15,"options":{"A":"They will be extra-chilly","C":"They will be contaminated","B":"They will be hard to defrost","D":"They will be ruined"},"answer":"D","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"Chronic depression","C":"Hip fracture","B":"Growing feebleness","D":"Fatal infections"},"answer":"C","stem":""},{"n":17,"options":{"A":"It feels real and relevant","C":"It outcompetes lots of academics’ research","B":"It contributes to psychology","D":"It wins recognition outside of Birmingham"},"answer":"A","stem":""},{"n":18,"options":{"A":"By bringing together experts old and young","B":"By counting on advanced modem technology","C":"By making full use of her expertise","D":"By combining multiple perspectives"},"answer":"D","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"They don't teach basic organization","C":"They attach little importance to recipes","B":"They don't focus on teaching techniques","D":"They hire very few distinguished chefs"},"answer":"A","stem":""},{"n":20,"options":{"A":"It's unique to celebrity chefs","C":"It’s too demanding for them","B":"It's a way of transformation","D":"It's a way of life to them"},"answer":"D","stem":""},{"n":21,"options":{"A":"Respect others so as to be respected","B":"Use time and resources in a wise way","C":"Cultivate a habit of self-discipline","D":"Learn from philosophers earnestly"},"answer":"B","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"The motive for hard work","C":"The basis for self-improvement","B":"The reason for stagnation","D":"The justification for self-confidence"},"answer":"C","stem":""},{"n":23,"options":{"A":"Feel confidence, happiness and satisfaction","C":"Use a key tool for setting ambitious goals","B":"Believe they have achieved their life goals","D":"Stop imagining further progress in life"},"answer":"D","stem":""},{"n":24,"options":{"A":"We feel we are always falling behind others","B":"We have to adapt to the ever-changing goal","C":"There are various misconceptions about goal setting","D":"There are always problems with the goal originally set"},"answer":"B","stem":""},{"n":25,"options":{"A":"A noticeable change in the number of goals to achieve","B":"Measuring always against the gap rather than the gain","C":"Measuring where we've come from instead of measuring against the goal","D":"A proper conception of what we fail to notice in trying to achieve our goals"},"answer":"C","stem":""}]}]},"cloze":{"passage":"No beast on Earth is  tougher than the tiny tardigrade ( 缓步类动物). It can “___26___ being frozen at -272° Celsius \nbeing exposed to the vacuum of outer space and even being ___27___ with 500 times the dose of X -rays that would kill a \nhuman. In other words, the creature can endure conditions that don’t even exist on Earth. And researchers are looking to the \nmicroscopic animals to learn how to prepare humans and crops to handle the ___28___ of space travel.  \nThe tardigrade’s indestructibility stems from its ___29___ to its environment — which may seem surprising, since it \nlives in ___30___ comfortable places like the cool, wet patches of moss (青苔) that dot a garden wall.  \nBut it turns out that a tardigrade’s damp, mossy home can dry out many times each year. Drying is pretty ___31___ for \nmost living things. It does damage to cells in some of the same ways that freezing, vacuum and radiation do. Tardigrades, \nhowever, have ___32___ special strategies for dealing with these kinds of damage.  \nAs a tardigrade dries out , its cells produce several strange proteins that are unlike anything found in other animals. In \nwater, the proteins are shapeless. But as water disappears, the proteins self -assemble into long fibers that fill the cell ’s \n___33___. The fibers support the cell’s membranes (细胞膜) and proteins, preventing them from breaking or ___34___. \nEmulating tardigrades could one day help humans colonize outer space. Food crops could be engineered to produce \ntardigrade proteins, allowing these organisms to grow more efficiently on spacecraft where levels of radiation are elevated \ncompared with on Earth.  \nSo if humans ever succeed in reaching the stars, they may accomplish this ___35___, in part, by standing on the shoulders \nof the tiny eight-legged endurance specialists in your backyard.","bank":[["A","adaptations"],["I","rigors"],["B","blasted"],["J","seemingly"],["C","catastrophic"],["K","survive"],["D","evolved"],["L","tempt"],["E","feat"],["M","thrill"],["F","interior"],["N","unanimously"],["G","probing"],["O","unfolding"],["H","recurrence"]],"answers":{"26":"K","27":"B","28":"I","29":"A","30":"J","31":"C","32":"D","33":"F","34":"O","35":"E"}},"matching":{"statements":[{"n":36,"text":"36. The FAO concluded that farm animals were producing more greenhouse gases than all modes of transportation combined","answer":"E"},{"n":37,"text":"37. Consumption of meat per person in developing countries is much less than that in countries like the U.S","answer":"K"},{"n":38,"text":"38. The FAO was worthy of praise in that it admitted its mistake once it was pointed out","answer":"H"},{"n":39,"text":"39. Environmentalists try hard to make people consume less meat to combat climate change","answer":"A"},{"n":40,"text":"40.Recent research has shown that even if Americans quit eating meat altogether, the resulting reduction of greenhouse gases in the U.S. would be slight","answer":"I"},{"n":41,"text":"41. More than half of the world’s farmland is suitable only for animals like cows to graze on","answer":"M"},{"n":42,"text":"42. The allegation that farm animals produce the world ’s largest portion of greenhouse gases is responsible for meat ’s bad reputation","answer":"D"},{"n":43,"text":"43. Raising farm animals makes it easier to meet people’s nutritional needs","answer":"L"},{"n":44,"text":"44.The author doesn’t believe giving up meat and meat products will be a cure-all for the environmental problem","answer":"C"},{"n":45,"text":"45.Changes in America’s farming technology and management in the past decades have increased effic iency and reduced greenhouse gas emissions in meat production","answer":"J"}],"paragraphs":{"A":"As the scale and impacts of climate change become increasingly alarming, meat is a popular target for action. Advocates for the protection of the natural environment from destruction or pollution urge the public to eat less meat. Some activists have even called for taxing meat to reduce consumption of it","B":"A key claim underlying these arguments holds that globally, meat production generates more greenhouse gases than the entire transportation sector. However, this claim is demonstrably wrong, as I will show. And its persistence has led to false assumptions about the linkage between meat and climate change","C":"My recent research focuses on ways in which animal agriculture affects air quality and climate change. In my view, there are many reasons for either choosing animal protein or opting for a vegetarian selection. However, abandoning meat and meat products is not the environmental panacea (万灵药) many would have us believe. And if taken to an extreme, it also could have harmful nutritional consequences","D":"A healthy portion of meat’s negative reputation centers on the assertion that livestock is the largest source of greenhouse gases worldwide. For example, an analysis published in 2009 by the World Watch Institute based in Washington, D.C. asserted that 51 percent of global greenhouse gas emissions come from rearing and processing livestock. According to the U.S. Environmental Protection Agency, the largest sources of U.S. greenhouse gas emissions in 2016 were electricity production (28 percent of tota l emissions), transportation (28 percent) and industry (22 percent). All of agriculture accounted for a total of 9 percent, but all of animal agriculture contributes less than half of this amount, representing 3.9 percent of the total greenhouse emission in the U.S. That is very different from claiming that livestock represents as much as or more than transportation","E":"Why is there such a misconception? In 2006 , the United Nations Food and Agriculture Organization (FAO) published a study titled “Livestock’s Long Shadow, ” which received widespread international attention. It stated that livestock produced a staggering 18 percent of the world ’s greenhouse gas emissions. The agency drew a startling conclusion that livestock was doing more to harm the climate than all modes of transportation combined. This latter claim was wrong, and has since been corrected by Henning Stenfeld, the report’s senior author","F":"The problem was that analysts from the FAO used a comprehensive life -cycle assessment to study the cli mate impact of livestock, but a different method when they analyzed transportation. For livestock, they considered every factor associated with producing meat. This included emissions from fertilizer production, converting land from forests to pastures, growing feed, and direct emissions from animals (manure as well as expelling of gas from the stomach) from birth to death","G":"However, when they looked at transportation’s carbon footprint, they ignored impacts on the climate from manufacturing vehicle materials and parts, assembling vehicles and maintaining roads, bridges and airports. Instead, they only considered the exhaust smoke emitted by finished cars, trucks, trains and planes. As a result, the FAO’s comparison of greenhouse gas emissions from livestock to those from transportation was greatly distorted","H":"I pointed out this flaw during a speech to fellow scientists in San Francisco on March 22, 2010, which led to a flood of media coverage. To its credit, the FAO immediately owned up to its error. U nfortunately, the agency’s initial claim that livestock was responsible for the lion’s share of world greenhouse gas emissions had already received wide coverage. To this day, we struggle to “unring” the bell. In its most recent assessment report, the FAO estimated that livestock produces 14.5 percent of global greenhouse gas emissions from human activities. There is no comparable full life-cycle assessment for transportation. However, as Stenfeld has pointed out, direct emissions from transportation versus livestock can be compared and amount to 14 versus 5 percent respectively","I":"Many people continue to think that avoiding meat as infrequently as once a week will make a significant difference to the climate. But according to one recent study, even if Ame ricans eliminated all animal protein from their diets, they would reduce U.S. greenhouse gas emissions by only 2.6 percent. According to our research at the University of California, Davis, if the practice of Meatless Monday were to be adopted by all Americans, we’d see a reduction of only 0.5 percent","J":"Moreover, technological, genetic and management changes that have taken place in U.S. agriculture over the past 70 years have made livestock production more e fficient and less greenhouse gas-intensive. According to the FAO ’s statistical database, total direct greenhouse gas emissions from U.S. livestock have declined by 11.3 percent since 1961, while production of livestock meat has more than doubled","K":"Demand for meat is rising in devel oping and emerging economies, especially in the Middle East, North Africa and Southeast Asia. For example, raising livestock such as goats in Kenya is an important source of food and income for many small-scale farmers and herders. But meat consumption per person in these regions still lags that of developed countries. In 2015, average annual meat consumption per person in developed countries was 92 kilograms, compared to 24 kilograms in the Middle East and North Africa and 18 kilograms in Southeast Asia. S till, given projected population growth in the developing world, there will certainly be an opportunity for countries such as the United States to bring their sustainable livestock rearing practices to the table","L":"Removing animals from U.S. agriculture would lower national greenhouse gas emissions to a small degree, but it would also make it harder to meet people’s nutritional requirements. Many critics of animal agriculture are quick to point out that if farmers raised only plants, they could produce more pounds of food and more calories per person. But humans also need many essential micro- and macro-nutrients for good health. It’s hard to make a compelling argument that the United States has a calorie deficit , given its high national rates of adult and child obesity. Moreover, not all plant parts are edible or desirable. Raising livestock is a way to add nutritional and economic value to plant agriculture","M":"As one example , the energy in plants that livestock consume is most often contained in cellulo se (纤维素), which is indigestible for humans and many other mammals. But cows, sheep and other ruminant ( 反刍的) animals can break cellulose down and release the solar energy contained in this vast resource. According to the FAO, as much as 70 percent of all agricultural land globally is range land that can only be utilized as grazing land for ruminant livestock","N":"The world population is currently projected to reach 9.8 billion by 2050. Feeding this many people will raise immense challenges. Meat is more calo rie-dense per serving than vegetarian options, and ruminant animals largely thrive on feed that is not suitable for humans. Raising livestock also offers much -needed income for small-scale farmers in developing nations. Worldwide livestock provides a livelihood for 1 billion people","O":"Climate change demands urgent attention, and the livestock industry has a large overall environmental footprint that affects air, water and land. These, combined with a rapidly rising world population, give us plenty of comp elling reasons to continue to work for greater efficiencies in animal agriculture. I believe the place to start is with science-based facts"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Why are we so worried about our careers? Partly it’s to do with money, but there’s a psychological aspect to our fears as \nwell.  \nWe worry because we suspect — not wrongly — that the world is full of a frightening sort of person ready to judge us \n\f\nruthlessly and swiftly: a person we can call a snob.  \nA snob is anyone who takes a relatively small part of  us and uses it to come to a rigid conclusion about how much of \ntheir attention we deserve. In the past that might be your ancestry and royal connections. Nowadays, the snob cares about one \nthing only: what you do for a living.  \nThis explains why the first question we will be asked in any new social context is “What do you do?” and according to \nhow we answer, snobs will either welcome us with broad smiles, or leave us in the cold.  \nAnd that is why we are fired up by Such a desperate urge to achieve and impress.  \nSometimes our behaviour is mistaken for greed and vanity, but it is more than this. A lot of our interest in fancy cars, \njobs and houses has nothing to do with materialism. It has to do with a hunger for the respect and esteem that is only available \nin our societies through the acquisition of material goods. It isn’t the goods themselves we seek, it is the love we stand to gain \nthrough our possession of them. The next time we see someone driving a Ferrari, we shouldn’t condemn them for their greed, \nwe should pity them for the intensity of their need for love from the world.  \nAt the root of snobbery is a lack of imagination and confidence about how to decide who in the world is valuable. The \nsnobs are brutally misguided and slavish in their beliefs about how the superior individuals can be identified. For snobs, it is \nthe already acclaimed and already successful who are the only ones worthy of respect. There is no room in their timid \nregimented minds to imagine that someone might be clever, kind or good — and yet somehow have been overlooked entirely \nby society, their qualities lying hidden beneath an unfamiliar veil, and having as yet discovered no obvious outlet.  \nThe true answer to snobbery is not to say that there is no such thing as a better or worse person, but to insist that better \nor worse exist in constantly unexpected places and carry none of the outward signs of distinction. And because we are such \npoor judges of the worth of others, our ultima te duty remains to be kind, good curious and imaginative about pretty much \neveryone who ever crosses our path.","questions":[{"n":46,"stem":"46. What gives rise to our worry about careers apart from money?","options":{"A":"Fear of being judged in a snobbish manner","C":"The ruthless way employees are often treated","B":"The prospect of facing fault-finding managers","D":"Fright at the difficulty in hunting for a job"},"answer":"A"},{"n":47,"stem":"47. What do we learn from the passage about today's snobs?","options":{"A":"They try hard to dig into a person's past","C":"They judge a person by their occupation","B":"They draw a rigid conclusion about people","D":"They tend to place people in a social context"},"answer":"C"},{"n":48,"stem":"48. What does the author say about people's interest in material goods?","options":{"A":"It is the cause for condemnation of their greed","B":"It has a lot to do with the comforts they provide","C":"It arouses pity rather than respect from the wealthy","D":"It arises from their craving for social recognition"},"answer":"D"},{"n":49,"stem":"49. What kind of people do snobs deem worth respect and esteem?","options":{"A":"Those with fame and fortune","C":"Those with intelligence and imagination","B":"Those with regimented minds","D":"Those with qualities lying hidden in disguise"},"answer":"A"},{"n":50,"stem":"50. What does the author imply we should do to avoid being snobbish?","options":{"A":"Be aware there has never been such a thing as a better or worse person","B":"Be kind to and curious about those who we happen to meet in our lives","C":"Realize that better or worse keeps changing in unexpected ways","D":"Judge people on the basis of their distinctive character traits"},"answer":"B"}]},{"title":"Passage Two","passage":"Women have historically been paid less. But in the US in the 1980s, they began to catch up — fast. During that decade, the \ngender pay gap closed by about one percentage point a year. Had that trend continued, the gender wage gap would have been \nclosed by 2017.  \nBut the trend didn’t continue, and the gap remains yawning.  \nAccording to a new study from academics at Harvard, the stagnation can be put down, perhaps counterintuitively, to the \n\f\nintroduction of state and federal family leave policies.  \nThe academics argue that during the 1990s, as governments began to introduce leave policies, it was  mainly women who \ntook advantage of them. Though the leave policies might have helped those women to stay in the workplace  — instead of \ndropping out to have families — those who returned saw their wages had increased at lower rates than the men.  \nAfter family leave was introduced in the US, in fact, the rate of gender wage convergence fell to just 0.03 percentage points \nper year, and has remained there ever since.  \nThose monitoring the process towards salary equity at work have long watched as progress slow ed in many countri es \naround the world. In fact, that progress began to reverse during the pandemic (大流行病).  \nThe gender pay gap is one of the most outstanding examples of that lack of parit y (平等), and still exists just about \neverywhere. The motherhood penalty has become a shorthand for describing why: In many places, especially rich countries, \nwomen earn the same as men until they reach their childbearing years. Women who have children begin to see their salaries \nslip behind their male counterparts.  \nPart of this is because women take on more of the unpaid labor at home, which can eat into time available for work and \nenergy for career advancement. But it’s also because mothers are passed over for raises and promotion, and because time out \nof the workplace sets women back, even if that time is taken voluntarily, and supported by company or government policy.  \nWhat would have happened if leave policies hadn’t been introduced? The study doesn’t go into that question, other than to \nsay that if the 1980s trend continued, we would have been at parity by now.  \nIt’s possible, however, that the journey towards wage parity would have stalled either way. If women’s gains in the 1980s \nwere made through the erasure of things like bias, once those less uncontrollable problems had been addressed, there would \nstill have been an issue with women — who are the ones to bear children and take care of them in the early weeks because of \nbiological factors like the ability to breastfeed, forcing them to take breaks, whether or not those breaks were mandated.","questions":[{"n":51,"stem":"51.What do we learn about the gender pay gap in the US during the 1980s?","options":{"A":"It was being slowly closed","C":"It started to yawn","B":"It was shrinking rapidly","D":"It remained substantial"},"answer":"B"},{"n":52,"stem":"52. What happened with the introduction of state and federal family leave policies?","options":{"A":"The process towards salary equity at work began to reverse","B":"The rate of gender wage convergence started to fall noticeably","C":"The trend of women returning to work after childbirth started","D":"The narrowing of the gender pay gap attracted more attention"},"answer":"B"},{"n":53,"stem":"53. What partly accounts for the slip in women’s salaries?","options":{"A":"The insufficient motivation women generally have for career advancement","B":"The opportunities numerous women give up for pay raise and promotion","C":"The huge amounts of time and energy women spend taking care of the family","D":"The lack of policy support from government and business corporations"},"answer":"C"},{"n":54,"stem":"54. What does the new study say about wage parity?","options":{"A":"It would have stalled if those controllable problems had not been addressed","B":"It would have halted if company and government had not worked together","C":"It would have been achieved with the complete erasure of gender biases","D":"It would have been attained with the continuation of the 1980s trend"},"answer":"D"},{"n":55,"stem":"55.What prevents women from achieving parity with men in the final analysis?","options":{"A":"Ignoring biases against women in the workplace","B":"Giving birth to children and taking care of them","C":"Failing to mandate breaks for childbirth and care","D":"Lacking resources to address biological problems"},"answer":"B"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true},{"id":"2025-06-cet6-3","level":"CET6","year":2025,"month":6,"set":3,"title":"2025 年 6 月 · CET6 第 3 套","source":"2025年6月 第3套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"本套官方未提供听力。","groups":[]},"cloze":{"passage":"The slow progress of women in elective office is frustrating for some political observers and experts — including myself. \nAchieving gender equality in Congress is an important goal. This is because the number of women involved in legislative \ndecisions has significant ___26___ for all the policies that go vernments ___27___. Female legislators are more likely than \nmen to introduce, speak about and work to pass policies that disproportionately affect women and girls, such as paid family \nleave, pay ___28___ and gender-based violence.  \nHaving more women in Congress also fosters a greater sense of connection between female voters and government. In \naddition, it ___29___ women’s sense that government cares about their concerns and inspires young women to become more \npolitically engaged.  \nWhile women are underrepresented in governments around the globe it is a particularly ___30___ problem in the United \nStates. Currently, the U.S. ranks 73rd in the world when it comes to female representation in government.  \nBut the reason women are so ___31___ underrepresented in U.S. government is not because they face resistance from \nvoters or struggle to raise money. On the contrary, decades of research shows that female candidates raise as much money and \nwin as often as male politicians with similar ___32___.  \nRather the slow progress of women in politics is a tale of two political parties. In the next Congress, there will be 107 \nfemale Democratic lawmakers and 42 female Republican lawmakers in the Senate and House combined.  \nIn order for women to gain half of the seats in Congress, more women need to run, ___33___ on Republican tickets. This \nwill require the Republican Party as a whole to ___34___ recruiting women — and not just for one election cycle but  in a \n___35___ way.","bank":[["A","bolsters"],["I","formidable"],["B","consequences"],["J","impetus"],["C","credentials"],["K","lavish"],["D","dramatically"],["L","prioritize"],["E","enact"],["M","suffices"],["F","equity"],["N","sustained"],["G","especially"],["O","tenured"],["H","evasively"]],"answers":{"26":"B","27":"E","28":"F","29":"A","30":"I","31":"D","32":"C","33":"G","34":"L","35":"N"}},"matching":{"statements":[{"n":36,"text":"36. Lots of research demonstrates that being socially isolated is harmful to the elderly","answer":"C"},{"n":37,"text":"37. Being alone enables artists to think and observe, which is a must for their creation","answer":"H"},{"n":38,"text":"38. To one writer, being forced to play with others was a penalty while being kept alone in a room was quite a pleasure","answer":"B"},{"n":39,"text":"39. Recent research shows for the first time that there is a specific link between being creative and being unsociable","answer":"I"},{"n":40,"text":"40. We must be willing to stay alone at least for some time in order to plot our own course","answer":"M"},{"n":41,"text":"41. According to new research, for people who prefer being alone, solitude can be beneficial to their work lives and emotional health","answer":"E"},{"n":42,"text":"42. It may tum out to be better for one to cultivate a few steady relationships than to busy themselves socialising","answer":"O"},{"n":43,"text":"43. Allowing your mind to wander freely is conducive to sharpening your focus in the long run","answer":"L"},{"n":44,"text":"44. Research conducted on artists and scientists indicates that creative people are less interested in hanging out with others","answer":"G"},{"n":45,"text":"45. According to Feist, you will have difficulty knowing yourself if you do not stay alone occasionally","answer":"N"}],"paragraphs":{"A":"I can be a reluctant socialiser. I’m sometimes secretly pleased when social plans are called off. I get restless a few hours into a hangout. I even once went on a free 10 -day silent meditation ( 冥想) retreat — not for the meditation, but for the silence","B":"So can relate to author Anneli Rufus, who wrote in Party of One: The Loners ’ Manifesto: “When parents on TV shows punished their kids by ordering them to go to their rooms, I was confused. I loved my room. Being there behind a locked door was a treat. To me a punishment was being ordered to play games with my cousin Louis.”","C":"Unsocial tendencies like these are often far from ideal. Abundant research shows the harms of social isolation, considered a serious public health problem in countries that have rapidly ageing populations (though talk of a ‘loneliness epidemic’ may be exaggerated). In the UK, the Royal College of General Practitioners says that loneliness has the same risk level for premature death as diabetes. Strong social connections are important for cognitive functioning, motor function and a smoothly running immune system","D":"This is especially clear from cases of extreme social isolation. Examples of people kept in captivity, children kept isolated in abusive orphanages, and prisoners kept in solitary confinement all show how prolonged solitude can lead to hallucinations (幻觉) and other forms of mental instability","E":"But these are severe and involuntary cases of aloneness. For those of us who just prefer plenty of alone time, emerging research suggests some good news: there are upsides to being alone — for both our work lives and our emo tional well- being","F":"Solitude is a time for reflection, for thinking about things more deeply. In a world increasingly focused on speed and competitiveness, solitude is precious and something to be treasured. And there are benefits in learning to love your solitude","G":"One key benefit of solitude is improved creativity. Gregory Feist, who focuses on the psychology of creativity at California’s San Jose State University, has defined creativity as thinking or activity with two key elements: originality and usefulness. He has found that personality traits commonly associated with creativity are openness (receptiveness to new thoughts and experiences), self-confidence, and autonomy — which may include “a lack of concern for social norms” and “a preference for being alone”. In fact, Feist’s research on both artists and scientists shows that one of the most prominent features of creative folks is their lesser interest in socialising","H":"One reason for this is that such people are likely to spend sustained time alone working on their craft. Plus, Feist says, many artists “are trying to make sense of their internal world and a lot of internal personal experiences that they’re trying to give expression and meaning to through their art.” Solitude allows for the reflection and observation necessary for that creative process","I":"A recent justification of these ideas came f rom University at Buffalo psychologist Julie Bowker , who researches social withdrawal. Social withdrawal is usually categorised into three types: shyness caused by fear or anxiety; avoidance, from a dislike of socialising; and unsociability, from a preference for solitude. A paper by Bowker and her colleagues was the first to show that a type of social withdrawal could have a positive effect — they found that creativity was linked specifically to unsociability. They also found that unsociability had no correlation with aggression (shyness and avoidance did). This was significant because while previous research had suggested that unsociability might be harmless, Bowker and colleagues’ paper showed that it could actually be beneficial. Unsociable people are likely to be “having just enough interaction, ” Bowker says. “They have a preference for being alone, but they also don’t mind being with others.”","J":"Still, it turns out that solitude is important for more than creativity. It’s commonly believed that leaders need to be sociable. But this depends, among other things, on the personalities of their employees. One 2011 study showed that in branches of a pizza chain where employees were more passive, outgoing bosses were associated with higher profits. But in branches where employees were more active, introverted (内向的) leaders were more effective. One reason for this is that introverted people are less likely to feel threatened by strong personalities and suggestions. They’re also more likely to listen","K":"Since ancient times, meanwhile, people have been aware of a link between isolation and mental focus. After all, cultures with traditions of religious hermits (隐士) believe that solitude is important for enlightenment. Recent research has given us a better understanding of why. One benefit of unsociability is the brain ’s state of active mental rest, which goes hand- in-hand with the stillness of being alone. When another person is present, your brain can’t help but pay some attention. This can be a positive distraction. But it’s still a distraction","L":"Daydreaming in the absence of such distractions activates the brain’s default-mode network. Among other functions, this network helps to consolidate memory and understand others’ emotions. Giving free rein to a wandering mind not only helps with focus in the long term but strengthens you r sense of both yourself and others. Paradoxically, therefore, periods of solitude actually help when it comes time to socialise once more. And the occasional absence of focus ultimately helps concentration in the long run","M":"A more recent advocate of thoughtful and productive solitude is Susan Cain, author of Quiet: The Power of Introverts in a World That Can't Stop Talking and founder of Quiet Revolution, a company that promotes quiet and introvert -friendly workplaces. “These days, we tend to believe that creativity emerges from a decidedly unreserved socialising process, but in fact it requires sustained attention and deep focus,” she says. “Also, humans are such absorbent social beings that when we surround ourselves with others, we automatically take in their opinions and aesthetics. To truly chart our own path or vision, we have to be willing to isolate ourselves, at least for some period of time.”","N":"Still , the line between useful solitude and dangerous isolation can b e blurry. “Almost anything can be adaptive and maladaptive, depending on how extreme they get, ” Feist says. A disorder has to do with dysfunction. If someone stops caring about people and cuts off all contact , this could point to an irrational neglect of s ocial relations. But creative unsociability is a far cry from this. In fact, Feist says, “there’s a real danger with people who are never alone.” It’s hard to examine one’s own thoughts, feelings and motives, to be self-aware, and fully relaxed unless you have occasional solitude. In addition, introverts tend to have fewer but stronger friendships — which has been linked to greater happiness","O":"As with many things, quality reigns over quantity. Nurturing a few solid relationships without feeling the need to constantly populate your life with endless chatting ultimately may be better for you","P":"Thus, if your personality tends toward unsociability, you shouldn ’t feel the need to change. Of course, that comes with qualifications. But as long as you have regular social contact you are choosing solitude rather than being forced into it, you have at least a few good friends and your solitude is good for your well -being or productivity, there’s no point agonising over how to fit a square personality into a round hole"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O","P"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Simulators are most often utilized within industries such as nuclear power, aviation and surgery where failure results in \ndisastrous consequences. To maximize the value from a simulation learning experience, participants should immediately and \ndirectly apply their learning to a specific intervention within their organization.  \nMost organizations aspire to deploy significant change programs, only to find them nearly impossible to implement. That \nis largely because successful change requires more than a vision, it requires a workforce that not only doesn’t resist change, \n\f\nbut embraces it.  \nTo achieve success, an organization must build a transformation program that will allow change to be rapidly pulled \nacross its departments and throughout its layers. Regardless of the level of senior management commitment, unless key \nthought leaders at all levels embrace the change, the initiative will wither and die. To create this kind of widespread passion, \nlearning leaders must expose the workforce to what could be, which will enable them to rethink their mental models, enable \nthem to break free from their deep-rooted paradigms and embrace the opportunity to learn.  \nAllowing participants to enter a simulated environment provides them with the opportunity to experience alternative \nrealities which can prompt them to rethink their current beliefs.  \nBehavioral change is not easy for m ost adults. Lectures, training programs and workshops can explain the intellectual \nelements of transformation, but they are seldom effective at getting to the behavioral aspects that lie at the heart of a significant \nchange initiative. Further, under normal working conditions, managers rarely see the full effect of their employee development \nefforts. As such, an intervention like a simulation can provide the stimulus for change.  \nAn effective simulation can be better than experience as a learning tool becau se it accelerates time, compresses space, \nand unlike reality, is specifically designed to maximize participant learning. Simulations provide an immersive learning \nexperience where skills, processes and knowledge all can be highlighted in a way reality cann ot. The ability to explore, \nexperiment and repeatedly apply new knowledge in unlimited, risk -free models is what makes simulation one of  the most \nproductive forms of learning.  \nWell-designed simulations can enable individuals and groups to develop a deep level of understanding about how their \ndecisions and intuitive responses to business stimuli affect their fellow participants and the organization as a whole. To reap \nthe benefits, however, simulations must feel like reality. At the end of the successful si mulation, participants must declare \n“this is us. ” If they don ’t, they will view the experience as a game, which can be difficult to apply on the job, or worse, \nirrelevant to everyday work tasks. To maximize benefits from simulation, participants should immediately apply the learning \nfrom the experience to forge a smooth link between learning and doing.","questions":[{"n":46,"stem":"46. What do we learn about successful changes in organizations?","options":{"A":"They can be immediately implemented with great ease","B":"They are usually led by organization leaders of vision","C":"They call for enthusiastic support from the workforce","D":"They often result from simulation learning experiences"},"answer":"C"},{"n":47,"stem":"47.What should learning leaders do to arouse learners’ passion for change?","options":{"A":"Allow them to see what could possibly be achieved","B":"Help them break free from their old paradigms","C":"Encourage them to rethink their thought models","D":"Stimulate them to embrace fresh opportunities"},"answer":"A"},{"n":48,"stem":"48. What does the passage say about lectures, training programs and workshops?","options":{"A":"They are generally incapable of changing workers’ behaviors on the job","B":"They are interventions different from simulations in creating stimuli for change","C":"They aim at transforming the behaviors of the workers in an organization","D":"They help managers achieve the full effect of employee development efforts"},"answer":"A"},{"n":49,"stem":"49. What makes simulation one of the most fruitful forms of learning?","options":{"A":"Its capability of saving time by accelerating the immersive learning experience","B":"Its potential for learners to examine their skills, knowledge and learning process","C":"Its capability of providing all participants with a practical learning experience","D":"Its potential for learners to explore, experiment and practice without any risk"},"answer":"D"},{"n":50,"stem":"50. What should participants do in a simulation to reap the greatest benefits possible?","options":{"A":"Take the experience as a mere game","B":"Apply promptly what they learn to their jobs","C":"Develop a deep level of understanding","D":"Strive to connect closely with their leaders"},"answer":"B"}]},{"title":"Passage Two","passage":"GDP growth is not a good indicator of how well a country is performing, and should not be the primary goal of \ngovernments. Unlimited growth is not sustainable, and economic thinking is moving toward the idea that we should aim for \nsustainability in our economic models. But while a sustainable economy is vital to our future, it is a means to an end, not an \nend in itself.  \nThe idea that governments should focus on happiness has its critics. There are concerns about how  happiness can be \nmeasured. Is happiness not a fleeting and subjective psychological state? Don’t different people experience different levels of \nhappiness? Even on the broadest interpretation of ‘happiness’ as prosperity or ‘life satisfaction’, people want different things.  \nOf course, governments cannot impose life satisfaction on citizens. But our happiness relies on collaborative efforts as a \nsociety. A government’s obligation lies in creating conditions that promote prosperi ty. And there is good reason to suppose \nthat such conditions exist, are globally applicable, and are discoverable through research.  \nIn a recently published article, philosopher Julian Baggini suggests we should focus on ‘real wealth’ for citizens, which \ndoes not depend on GDP growth. Access is key: people do not need to own, but rather access things that enable them to live \nwell. Technological advances and changes in social behavior enable us to make more efficient use of the assets that we already \nhave. And focusing on access to the resources people need to live better lives could help reduce inequality.  \nAs far as it goes, this has much in common with proposals tabled by ‘happiness’ advocates. But it sets the bar far too low \nfor what governments can and should be doing for their citizens.  \nFor example, it’s not clear how a ‘real wealth’ economy would remedy the epidemic of mental ill-health that plagues our \nsociety. In Western countries, at least — poor mental health is more detrimental to wellbeing than poverty. Over and above a \nvastly improved provision of therapeutic mental healthcare, there are preventative measures for improving mental health that \ngovernments could and should adopt. The WHO recommends establishing institutions that facilitate community participation \n— educational programs and interventions that provide skills for promoting mental wellbeing. It says a lot, however, that the \nWHO feels the need to appeal to the economic benefits of improving mental health to persuade governments that the cost of \ntaking proposed measures is justified. As long as the economy is their priority, governments need go no further than ensuring \ncitizens’ continued productivity.  \nTo demand that governments set the ‘happiness’ of citizens as their highest priority is to demand that they view citizens \nas ends in themselves.","questions":[{"n":51,"stem":"51. What does the passage say is the more recent thinking of economic growth?","options":{"A":"It should be made sustainable","C":"It should be governments’ chief concern","B":"It is vital to the future of humanity","D":"It is an indicator of government performance"},"answer":"A"},{"n":52,"stem":"52. Why are some people opposed to the idea that governments should focus on happiness?","options":{"A":"Governments cannot impose happiness on citizens","C":"Happiness means different things to different people","B":"People’s happiness is built upon their own endeavor","D":"Happiness depends on sustainable economic growth"},"answer":"C"},{"n":53,"stem":"53. What does philosopher Julian Baggini suggest governments do in a recently published article?","options":{"A":"Try to reduce inequality between the rich and the poor","B":"Provide people with access to resources for a better life","C":"Change people’s behaviors to put social wealth to better use","D":"Make use of advanced technologies to improve people’s lives"},"answer":"B"},{"n":54,"stem":"54. Why does the WHO feel the need to appeal to the economic benefits of improving mental health to justify its recommendations?","options":{"A":"Mental health programs cannot be executed without GDP growth","B":"Psychological interventions are conducive to people’s wellbeing","C":"Poor mental health is detrimental to a nation’s economic system","D":"Governments still take economic development as their priority"},"answer":"D"},{"n":55,"stem":"55. What message does the author try to convey at the end of the passage?","options":{"A":"Governments’ goal should be prosperity-driven","B":"Governments’ goal should be people-oriented","C":"Governments should consider citizens’ views in decision-making","D":"Governments should set sustained productivity as their top priority"},"answer":"B"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true},{"id":"2024-12-cet6-1","level":"CET6","year":2024,"month":12,"set":1,"title":"2024 年 12 月 · CET6 第 1 套","source":"2024年12月 第1套","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"To\nincrease the likelihood of success, one should set realistic goals and work persistently towards them, \" You\ncan make comments, cite examples or use your personal experiences to develop your essay. You should write at\nleast 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"Preparing for a job interview","B":"Writing a work report together","C":"Going through a couple of issues the company faces","D":"Discussing the woman’s annual performance review"},"answer":"D","stem":""},{"n":2,"options":{"A":"The overall culture of the company","C":"The honesty of the manager","B":"The instruction from her supervisor","D":"The recognition of her merits"},"answer":"D","stem":""},{"n":3,"options":{"A":"Her inadequate language proficiency。","B":"Her inability to interact with colleagues properly","C":"Her inappropriate behavior at company meetings","D":"Her simplistic approach to dealing with others"},"answer":"B","stem":""},{"n":4,"options":{"A":"To avoid offending the recipients","C":"To save time","B":"To show her unique writing style","D":"To be frank."},"answer":"C","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"Provide medical service to the community","C":"Obtain a doctoral degree in internal medicine","B":"Make healthcare in her hometown the best","D":"Have a profound impact on people around her"},"answer":"A","stem":""},{"n":6,"options":{"A":"They have constantly urged her to study hard","B":"They have worked hard to finance her education","C":"They have tried to create a positive learning environment","D":"They have pursued the family’s dreams together with her"},"answer":"A","stem":""},{"n":7,"options":{"A":"It is a key medical branch conducive to realizing her dreams","B":"It connects many other specialties with its broad coverage","C":"It has a long history in the man’s prestigious institution","D":"It is a medical branch both of her parents specialize in"},"answer":"B","stem":""},{"n":8,"options":{"A":"Problematic","C":"Inconsistent","B":"Competitive","D":"Trustworthy"},"answer":"C","stem":""}]},{"intro":"Questions 9 to 11 are based on the you have just heard","questions":[{"n":9,"options":{"A":"To prevent hackers from cracking our secret codes","B":"To show that all the guidelines are being followed","C":"To provide evidence that passwords are forgotten","D":"To convince our computer that we are human"},"answer":"D","stem":""},{"n":10,"options":{"A":"Put an end to the hacking phenomenon","C":"Reduce the intricacy of the password itself","B":"Help people remember their passwords","D":"Explain the need for different email accounts"},"answer":"B","stem":""},{"n":11,"options":{"A":"Innovate technologies to ensure the safety of users’ accounts","B":"Provide incentives for the application of creative passwords","C":"Explore the possibility of using simpler secret codes","D":"Take steps to encourage users to log in more often."},"answer":"D","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"Her work no longer interested her","C":"Her fitness fell into a slump","B":"Her training app did not fit her","D":"Her business deteriorated,"},"answer":"C","stem":""},{"n":13,"options":{"A":"Help users keep track of their fitness levels","C":"Strengthen ties among users worldwide","B":"Design personalised training programmes","D":"Select well-qualified human coaches"},"answer":"B","stem":""},{"n":14,"options":{"A":"They are never repeated","C":"They are of no extreme intensity","B":"They help enrich her life","D":"They keep her focused on her goal"},"answer":"A","stem":""},{"n":15,"options":{"A":"They will not be able to take the place of human personal trainers","B":"They will not be able to comprehend some of the profiles users put in","C":"They cannot lead to optimal results with their mathematical approach","D":"They cannot match humans in arranging meticulous workout schedules"},"answer":"A","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"All societies are built upon the cornerstones of basic values","B":"Everyone everywhere demonstrates seven character traits","C":"All societies are kept together by seven basic moral rules","D":"Everyone everywhere shares a universal moral standard"},"answer":"C","stem":""},{"n":17,"options":{"A":"Ascertain whether deferring to authority was confined to right-wing people","B":"Find out whether different societies had different versions of morality","C":"Make clear whether all societies faced the same moral issues","D":"Find out whether left-wing people still had a group loyalty"},"answer":"B","stem":""},{"n":18,"options":{"A":"Make independent descriptions of cultures around the world","B":"Strive to understand the basic differences between peoples","C":"Appreciate the foundational value of the existing data","D":"Carry out systematic field studies to gather new data."},"answer":"D","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"They might be the most important part of our eating experience","B":"They can activate our brain functions in a most direct fashion","C":"They can be viewed as the windows to our soul","D":"They could mislead us in more ways than one"},"answer":"A","stem":""},{"n":20,"options":{"A":"It attracts food companies’ growing attention","C":"It invariably determines how food sells","B":"It adversely impacts one’s eating experience","D":"It changes the way people taste food"},"answer":"D","stem":""},{"n":21,"options":{"A":"Enhance the taste","C":"Identify distinct flavors","B":"Make predictions","D":"Enrich the eating experience."},"answer":"B","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Social status","C":"Meaning","B":"Financial resources","D":"Happiness"},"answer":"C","stem":""},{"n":23,"options":{"A":"Their effect on people’s happiness has long been overstated","B":"Their influence on people’s life varies with social contexts","C":"They can affect people’s experience of meaning","D":"They can ensure people’s overall well-being"},"answer":"C","stem":""},{"n":24,"options":{"A":"It used questions totally different from those in their first study","B":"It focused on the sense of meaning of French participants","C":"It analysed cases from a daily poll of US residents","D":"It examined data collected from multiple countries"},"answer":"D","stem":""},{"n":25,"options":{"A":"They might have more access to external sources of happiness","B":"They might focus on an individual sense of satisfaction or meaning","C":"They might be less easily affected by a community’s overall feeling","D":"They might be less adversely impacted by failure to achieve a purpose"},"answer":"A","stem":""}]}]},"cloze":{"passage":"With the rapid progress in the economy, it is natural that people’s ideology is bound for change. Being ___26___ is no \nlonger a virtue to some people, and they are not alone in holding this view. Each might have different viewpoints on how to \nlead one’s lifestyle: some prefer simplicity, some love luxuries, some spend ___27___, Some accumulate as much as they can \nlike a country mouse. As I was born poor and in the countryside, the simple rural life seldom loses its ___28___ to me, but as \nmy station changes, I have an opportunity to ___29___ with the newly rich, an experience which has revolutionized my view \nof lifestyle.  \nIt is evil or sinful to spend little and to save much, an idea only recently being revealed to me. Actually the whole world \nis in a ___30___ to borrow and to spend, with the USA leading the trend. The USA is still the richest and most powerful \ncountry in the world, but the ___31___ is that they borrow money from us. Though a ___32___ of economics, at least I know \nthat investing with borrowed money will turn the borrower into the ___33___ rather than the dece nt and kind lender. An \napparent case is real estate. Those who are ___34___ and have got loans from the bank become relatively rich by selling their \npurchased home at a price several folds higher. Even education is not immune from this theory. Many of those poor parents \nwho have the vision to send their children to college have benefited from this investment. even though they have to ___35___ \na living. It is reasonable to conclude that spending is praise worthy, supposing it is not beyond your means.","bank":[["A","appeal"],["I","meadow"],["B","extravagantly"],["J","mingle"],["C","intrinsically"],["K","predator"],["D","irony"],["L","rage"],["E","layman"],["M","scrape"],["F","literally"],["N","shrewd"],["G","majestic"],["O","thrifty"],["H","malicious"]],"answers":{"26":"O","27":"B","28":"A","29":"J","30":"L","31":"D","32":"E","33":"K","34":"N","35":"M"}},"matching":{"statements":[{"n":36,"text":"36. According to a senior researcher, we will have secure food supply if we rid ourselves of ignorance about native crops","answer":"F"},{"n":37,"text":"37. Most of the world’s food supply comes from a tiny number out of thousands of crops that have been grown for centuries","answer":"C"},{"n":38,"text":"38. To provide their family with food when the staple crops failed, some African women farmers grew local crops in their backyards","answer":"G"},{"n":39,"text":"39. High-yielding crops have occupied a dominant position in modern agriculture since the green revolution in the last century","answer":"J"},{"n":40,"text":"40. Growing alternative crops proved feasible in a variety of environments, but the critical question was whether they would be marketable","answer":"H"},{"n":41,"text":"41. According to a professor, when the yields of staple crops fall, we will have to adapt to eating foods from alternative crops","answer":"O"},{"n":42,"text":"42. Urgent measures have to be taken to provide food for the projected world population without aggravating the climate","answer":"D"},{"n":43,"text":"43. Colonial rule marginalised local crops by punishing Africans who grew them","answer":"I"},{"n":44,"text":"44. As existing crops are endangered by global warming, we can increase food security by bringing back the many forgotten food crops","answer":"E"},{"n":45,"text":"45. Researchers are trying to find out how higher temperatures and CO2 levels affect the nutritional composition of alternative crops","answer":"K"}],"paragraphs":{"A":"On a small fruit farm near the Straits of Malacca, Lim Kok Ann is down to just one tree growing kedondong, a crunchy, sour berry that Malaysians mostly use in pickles (腌菜) and salads. “It's not very well-known,” says the 45-year-old, who is instead focusing on longan (龙眼) berries and pineapples, which have bigger markets. “We have to grow what is profitable,” he says","B":"But less than an hour away in the Malaysian countryside, inside three giant, silver domes, scientists are trying to change the future o f food. They're pushing the boundaries of what humans eat by growing and processing so-called “alternative” crops --- such as kedondong. At the headquarters of global research centre Crops For the Future (CFF), this particular under- used fruit has been turned into a sugar-free juice, high in vitamin C and getting top marks in sensory evaluations. “Anything you see here is a forgotten crop,” says Sayed Azam-Ali of the abundant plants weaving through the gardens of CFF outside Malaysia’s capital Kuala Lumpur","C":"Prof Azam-Ali explains that just four crops --- wheat, maize, rice and soybean --- provide two-thirds of the world’s food supply. “We're dependent on these four. ” he says. “But actually there’re 7,000 crops we've been farming for thousands of years. We ignore all of those.” Researchers are trying to unlock the potential of these ignored crops --- plants they describe as forgotten, under-used, or “alternative” as they are displaced by increasingly uniform diets fuel ed by processed ingredients from the major crops","D":"It’s a timely quest. The food sector is already responsible for nearly a third of global greenhouse gas emissions. By 2050 it estimates the world must produce 50% more food to feed the projected global population of 10 billion. Meeting this demand without contributing to climate change calls for urgent solutions","E":"Forgotten crops hold key answers. By investing in neglected local plants, countries can reduce their reliance on imported crops and their carbon-heavy supply chains. Bringing back the variety of crops humans once ate also boosts food security at a time warming climates threaten existing crops. On top of that, forgotten crops are among the most climate-resilient (具有 气候韧性的) and nutritious, argues Azam-Ali. His summary is plain: “Dietary diversification is critical to the future of humanity.”","F":"Food security experts agree. “There is no food insecurity in the world, there is food ignorance,” says Cecilia Tortajada, a senior research fellow at the Institute of Water Policy at the National University of Singapore. “Whenever we have native crops we tend to disregard them as if they were not valuable but they are.” she adds","G":"Azam-Ali knows that scepticism firsthand. He came across alternative crops in the 1980s through the work of women farmers he met in Niger. The then-PhD student remembers marvelling at the crops they grew in their backyards, without the benefits of technology, to feed their families when the big crops failed. He saw a tremendous opportunity to build alternative food systems. But “the resistance was enormous,” he recalls","H":"Undeterred, he ploughed o n. Project after projec t helped prove these crops were viable in different environments as alternatives to the staple ones. But the question of whether these crops would be marketable remained. “That’s the critical thing.” he says. In one of the centre’s domes, food technologist Tan Xinlin uses powdered moringa (辣木) leaves in place of some wheat flour to bake a cake lower in gluten (谷胺) and higher in nutrients. Tan’s job is to create recipes with these still unfamiliar ingredients that will appeal to both local and international tastes. In recent years, she has used some of the forgotten crops grown at CFF, such as moringa and bambara groundnut, to make everything from instant soup to Indian snacks. “I try to modernise forgotten crops instead of using old recipes.” says Tan, who is also a trained chef. It’s a strategy to appeal to the world’s growing middle classes who are increasingly turning to the fast and processed food industries. It's also a way to help counter perceptions of local crops as “old or poor people’s food” or as inferior “women’s crops“, adds Tan","I":"The roots of these connotations about local foods can run deep. The bambara groundnut, a protein-rich native crop of sub- Saharan Africa that is also grown in parts of southeast Asia , can trace its marginalisation to colonial rule. “African women who grew bambara groundnut were actually punished for growing it.” says Azam-Ali. “Colonial powers said you can’t grow that because there’s no oil. We can’t get a market for it.” But today the bambara murukku is one of CFF’s best reviewed foods and they are aiming to get it into grocery stores, pointing to the success of crops like quinoa to potential investors. Some 30 years ago. quinoa was virtually unheard of outside its native mountains in Bolivia and Peru. Today the nutritious grain is found on the menus of lavish restaurants across the world","J":"Measuring crops by nutrition instead of yield is at the he art of the forgotten foods enterprise. Ever since the “green revolution” of the 1960s, high-yielding crops have dominated modern agriculture. That was in part a crucial response to devastating famines at a time when the world needed to increase its food supply. Today “nutrition is becoming a time bomb”, says Azam-Ali, as growing carbon dioxide levels strip crops of their minerals. Instead of bio-fortifying major crops we should be investing in those forgotten crops that are already more nutritious, he asserts","K":"In the bowels of CFF’s third dome, lab manager Gomathy Sethuraman opens a window into the centre’s “crown jewels”, revealing vines of wing ed beans growing under a bright yellow light. It's one of multiple chambers where scientists are studying the impact of higher temperatures and carbon dioxide levels on the nutritional make -up of alternative crops. This research is “the game changer”. says Azam-Ali, ensuring that “future crops” are also the healthiest ones in warmer climates","L":"There is a growing glo bal momentum around forgotten foods, says Danielle Nierenberg , president of Food Tank, a US- based think tank. Other than CFF, which bills itself as the world’s first research centre dedicated solely to under-utilised crops, there are other key groups champ ioning agricultural diversity including Crop Trust, Slow Food, Icrisat and Bioversity International. Add to that more middle-income consumers searching for nutritious foods and others eager to try the unprocessed foods their grandparents once ate, she says","M":"But the rising interest in forgotten foods in some quarters is overtaken by the global spread of Western-style diets heavy in sugar, fat and processed foods in others","N":"A key obstacle to promoting fading local crops in Malaysia, for example, is “the obsession with imported products”, says Jenifer Kuah, co -founder of a restaurant that champions locally -sourced food in an affluent suburb of Kuala Lumpur. Customers at Sitka, regarded as a pioneer in the country’s small farm-to-table dining scene, still seek foreign ingredients as a “status’s symbol”, she says","O":"The argument for forgotten foods feels i ntuitive. Some analysts say it is in fact inevitable. “Climate change is going to mean almost certainly tastes are going to be forced to change,” says Tim Lang, professor of food policy at City, University of London. We “have to get used to eating other crops” as yields of staple crops fall, he says"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Imagine you're an alien sent to Earth to document the behaviour of the mammals inhabiting the planet. You stumble into \na movie theatre that’s showing the latest Hollywood horror film.  \nSeveral dozen humans are gathered together in a dark,  undecorated room. They're all staring at a rectangular area on \nwhich patterns of light change rapidly.  \nThey are clearly in a state of high arousal. Their heart rate is elevated, they occasionally glance around nervously, and \n\f\nthey sometimes jump collectively in their seats, and emit high-pitched warning calls.  \nEventually, the lights come up and the rectangular screen goes black. The humans stand up and leave the room, chatting \nand laughing, and showing signs of pleasure.  \nWhy do these humans voluntarily expose themselves to what appears to be a deeply unpleasant experience? And why do \nthey react so strongly to those patterns of light on a screen?  \nI am fascinated with the paradox of horror --- the strange fact that many people seek out scary entertainment.  \nI think the answer to the puzzle lies in human nature.  \nMy research suggests that we humans evolved to find pleasure in situations that allow us to experience negative emotions \nin a safe context. You can see these elements of horror in children ’s games. Take hide -and-seek for example,  which is a \nsimulation of a predator-prey interaction. The kid hides and the adult pretends to be a predator, searching for the child while \nhowling like a dangerous beast.  \nThis simulation gives the child crucial information about how to avoid becoming prey, and children tend to find that kind \nof activity deeply satisfying, presumably because it gives them a safe experience of a potentially catastrophic scenario.  \nThey find it pleasurable, and pleasure is evolution’s way of motivating us toward adaptive behaviour.  \nHorror is pleasurable to many people because it lets us play with negative emotions and develop coping strategies. We \nlearn what it feels like to be truly afraid, and we learn how to handle negative emotion.  \nHow, then, does horror work? My research suggests that horror works by exploiting an ancient set of biological defence \nmechanisms --- an evolved fear system, which we share with ot her animals. But humans are uniquely imaginative, and we \nuse our evolved imagination to travel into virtual worlds that are full of danger.  \nThere are good reasons for watching a horror film. even if you're not a loyal horror fan. If you make it through the film \nin one piece. you'll probably experience a strong sense of mastery, a sense that you were able to make it through an appalling \nexperience. Anyway, watching a horror  film makes you better at handling your own fear, and who knows when that will \nbecome critically relevant?","questions":[{"n":46,"stem":"46. The alien finds the audience in the movie theatre clearly in a state of","options":{"A":"total mindfulness","C":"spiritual elevation","B":"extreme excitement","D":"intense curiosity"},"answer":"B"},{"n":47,"stem":"47. Why do many people seek out scary entertainment, according to the author’s research?","options":{"A":"They gain experience in overcoming horror in real life","B":"They find joy in going through simulated horrible experiences","C":"They have learned from hide-and-seek as kids the thrill involved","D":"They have evolved to gain pleasure in escaping life-threatening situations"},"answer":"B"},{"n":48,"stem":"48. What do children learn from hide-and-seek?","options":{"A":"How to avoid falling prey to an attacker","B":"How to simulate a predator-prey interaction","C":"How to keep themselves from catastrophic errors","D":"How to turn a dangerous scenario into a safe one"},"answer":"A"},{"n":49,"stem":"49. Why is horror gratifying to many people?","options":{"A":"It reminds them of an ancient set of biological defence mechanisms","B":"It triggers their imagination to travel into dangerous virtual worlds","C":"It allows them to learn what fear feels like and how to tackle it","D":"It activates their evolved fear system and their unique fantasy。"},"answer":"C"},{"n":50,"stem":"50. What will one experience if they watch a horror film through without being hurt?","options":{"A":"A strong sense of clear relevance","C":"A profound sense of intense relief","B":"A profound sense of good fortune","D":"A strong sense of being in control"},"answer":"D"}]},{"title":"Passage Two","passage":"An awakening has been taking place in the physical world against the beauty model that has been dictated to us for years. \nBut in the digital arena, social media determines what is considered beautiful.  \n\f\nThe two opposing struggles are taking place in parallel. In the physical world, the struggle goes against the underlying \npressure exerted on women to conform to an unrealistic beauty ideal. As part of the struggle, various media outlets have \npresented women whose bodies don’t correspond to the so-called ideal. All those women who had previously been excluded \nfrom the covers of magazines, television series and the public agenda, have become “legitimate”. At the same time, a group \nof influencers have begun to upload to social media photos of themselves without makeup, and even photos in which they \nhighlight supposed flaws.  \nTechnology has reshaped our beauty ideal and is doing a great job communicating that message to the masses. One of \nthe bizarre legacies of the past decade is the popularity of the “cyborg look”, which illustrates what Americans will look like \nin 2050.  \nThe cyborg look spread rapidly. Today, however, the Instagram face has become the new beauty ideal.  \nThe internalization of accepted beauty norms is much more effective when t here is active involvement in the learning \nprocess. The active i nvolvement of users is reflected in the gamified ( 游戏化的) interaction offered by the social media \nplatforms --- the ability to like, write a comment, compare, share.  \nOnce the desired beauty ideal has been internalized, users are given tools or features to change their appearance to suit \nthe accepted beauty ideal such as editing the image, choosing the ideal filter, the right background.  \nA survey conducted in the United States revealed that more than 50% filter the images before posting them. And you \nwill not be surprised to hear that the majority of them are women. One of the significant consequences of obsessive filtering \nis the emerging tendency to treat o neself as an object to be observed and valued, in the same way another person observes \nand judges from the side.  \nThe effect of the filters is already far beyond amiable amusement. The filters and the entire game played on the networks \naffect the mental health of the users. According to a study, apps like Instagram, Snapchat and FaceTune allow users to achieve \na level of perfection that was previously only observed in beauty magazines.  \nEven though humanity has always cherished beauty, in the last decade o ur obsession with looks has reached an \nunprecedented peak. The time spent on social media creates an  urge to achieve an impossible beauty ideal so powerful that \nthe only thing that can fix it is not cosmetic intervention, but mental health care.","questions":[{"n":51,"stem":"51. What do we learn about beauty in the digital arena?","options":{"A":"It dictates the taste of digital media","C":"It has ushered in a new awakening","B":"It has been in the making for years","D":"It is defined by social media"},"answer":"D"},{"n":52,"stem":"52. What does the passage say about beauty in the physical world?","options":{"A":"Women are under constant pressure to keep up with beauty models","B":"Women are encouraged to pursue a beauty ideal that has never existed","C":"A fight is going on to remove pressure on women to conform to an absurd beauty ideal","D":"Media outlets have begun to present as beauty models trendy women without any makeup"},"answer":"C"},{"n":53,"stem":"53. What do we learn from the passage about the Instagram face?","options":{"A":"It is now regarded as the new beauty ideal","B":"It is what most women will go after in 2050","C":"It is being much talked about on social media","D":"It is a perfect illustration of the ultimate beauty"},"answer":"A"},{"n":54,"stem":"54. What has obsessive filtering resulted in?","options":{"A":"A good many women striving to reach an impossible level of perfection","B":"An urge to turn the entire game played on the network to one’s advantage","C":"A tendency to regard one’s body as an object of observation and judgment","D":"An increasing number of women filtering their images before uploading them"},"answer":"C"},{"n":55,"stem":"55. What does the author want to emphasize at the end of the passage regarding Americans’ obsession with looks?","options":{"A":"Cosmetic surgery should be made more accessible to the masses","B":"Psychological intervention should be introduced to alleviate it","C":"Their time spent on social media should be strictly controlled","D":"Its root cause should be meticulously examined and analyzed"},"answer":"B"}]}],"translation":{"prompt":"","guide":[]},"answersReady":true},{"id":"2024-12-cet6-2","level":"CET6","year":2024,"month":12,"set":2,"title":"2024 年 12 月 · CET6 第 2 套","source":"2024年12月 第2套","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence\n\"Nowadays, more and more students have realized the importance of self-discipline in their personal\ngrowth.\" You can make comments, cite examples or use your personal experiences to develop your essay. You\nshould write at least 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"Changing his major","C":"Revising his graduation thesis","B":"His family situation","D":"His passion for Art History"},"answer":"A","stem":""},{"n":2,"options":{"A":"He doesn’t think it legitimate to depend on his father","B":"He thinks his financial situation has now changed","C":"He doesn’t think it will provide him with a living","D":"He thinks it nourishes the financially secure only"},"answer":"C","stem":""},{"n":3,"options":{"A":"Try his best to socialize and build a network in the art industry。","B":"Seek financially viable employment opportunities after graduation","C":"Investigate all possible ways to become a celebrity in the art world","D":"Strike a balance between intellectual pursuits and financial security"},"answer":"A","stem":""},{"n":4,"options":{"A":"Money","B":"Time","C":"Determination","D":"Optimism."},"answer":"B","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"Their decision on investigating beef consumption","B":"Their original ideas about the domestic market","C":"Their different approaches to a case study","D":"Their end-of-semester business projects"},"answer":"D","stem":""},{"n":6,"options":{"A":"Expanding farmland out west","C":"Raising cattle domestically","B":"Importing most of the beef","D":"Continuing to boost economic growth"},"answer":"C","stem":""},{"n":7,"options":{"A":"Technical equipment","C":"Beef","B":"Business consultancy","D":"Car washing"},"answer":"D","stem":""},{"n":8,"options":{"A":"Car owners of all walks of life","B":"High-end customers in big cities","C":"Consumers craving for professional service","D":"Well-off dealers seeking a profitable markup"},"answer":"B","stem":""}]},{"intro":"Questions 9 to 11 are based on the passage you have just heard","questions":[{"n":9,"options":{"A":"Parents’ talking with them during TV time raises their curiosity levels","B":"Their daily television exposure cuts parent-child conversation time","C":"The more TV they watch the poorer their progress in development","D":"Their socioeconomic levels impact their academic achievement"},"answer":"A","stem":""},{"n":10,"options":{"A":"Kids’ enhanced learning","C":"Kids’ reading and math","B":"Kids’ curiosity levels","D":"Kids’ behavioral development"},"answer":"B","stem":""},{"n":11,"options":{"A":"It can hinder kids from getting on with their peers","B":"It can cut into kids’ time on exploratory activities","C":"It can arouse kids’ interest in how people interact in real life","D":"It can widen the gap between kids from different economic statuses."},"answer":"B","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"Exerting ourselves too hard in order to attain our life’s goals","B":"Being possessed with a single thought of professional success","C":"Trying every means to beat others in terms of personal aspirations","D":"Being mindlessly driven to possess more and more material things"},"answer":"D","stem":""},{"n":13,"options":{"A":"We might isolate ourselves from our fellow beings","B":"We might acquire an incorrect sense of well-being","C":"We might end up pursuing all the wrong things","D":"We might make a mess of our personal lives"},"answer":"C","stem":""},{"n":14,"options":{"A":"They should be based on solid theoretical concepts:","B":"They should take personal interests into account","C":"They should include goals to help other people","D":"They should increase our sense of worthiness"},"answer":"C","stem":""},{"n":15,"options":{"A":"Drifting through life aimlessly","C":"Abandoning all that life has to offer","B":"Giving up the chance to fulfill yourself","D":"Spoiling your character and integrity"},"answer":"A","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"Grade-raising ways and means","C":"Revision-conducting approaches","B":"Pressure-alleviating exercise","D":"Brain-boosting food and drink"},"answer":"D","stem":""},{"n":17,"options":{"A":"Buying it from coffee shops","C":"Drinking it after 2 pm","B":"Building up a tolerance of it","D":"Consuming it with sugar"},"answer":"C","stem":""},{"n":18,"options":{"A":"By taking varied vitamin supplements","C":"By eating both oranges and frozen berries","B":"By consuming a rich variety of foods","D":"By getting components packaged in tablets."},"answer":"B","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"Many people across advanced economies think the world is going from bad to worse","B":"The news focuses on reporting catastrophes that occur across the world","C":"A significant part of the world is experiencing another great recession","D":"Many people have no idea of those living under miserable conditions"},"answer":"A","stem":""},{"n":20,"options":{"A":"It has experienced ups and downs like any other historical trend","B":"It is hailed as a miracle by both economists and ordinary people","C":"It is the only way for all countries to share economic prosperity","D":"It has given more and more countries a rare chance to thrive"},"answer":"C","stem":""},{"n":21,"options":{"A":"Their fortunes may take a downturn","C":"Their living standards have been deteriorating","B":"They can be classified as middle class","D":"They are experiencing a radical transformation."},"answer":"B","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Why smells can activate emotional memories","B":"How powerful the sense of smell can become","C":"How scent particles revive memories forgotten","D":"Why the scent of bread has a strong mental impact"},"answer":"A","stem":""},{"n":23,"options":{"A":"The brain cells’ processing of memories experienced as strongly emotional","B":"The activation of the brain’s emotion processing area by chemical particles:","C":"The interaction between chemical particles and the brain cells responsible for smell","D":"The sensations of scents going directly to the brain’s emotional and memory centers"},"answer":"D","stem":""},{"n":24,"options":{"A":"Imagination","B":"Association","C":"Experience","D":"Context"},"answer":"D","stem":""},{"n":25,"options":{"A":"Inaccuracy and alterability","C":"Being personal and individualistic","B":"Susceptibility to polar interpretations:","D":"Being dependent on relevant scenarios"},"answer":"A","stem":""}]}]},"cloze":{"passage":"Directions; In this section, there is a passage with ten blanks. You are required to select one word for each blank from a list \nof choices given in a word bank following the passage. Read the passage through carefully before making your choices. Each \nchoice in the bank is identified by a letter. Please mark the corresponding letter for each item on Answer Sheet 2 with a single \nline through the centre. You may not use any of the words in the bank more than once.  \n \nEver been talking about something important with someone you care about and found the discussion frustrating instead \nof fruitful? Negative energy can then cast a ___26___ over your efforts to build a shared understanding.  \nIn fact, collaborative problem-solving conversations require skills. Strong listening skills are essential. Sprinkling in \npositivity via appreciation, ___27___ smiles, and warm comments helps. So does the essential ability to keep your emotional \ntone in the calm z one. If the tone of a dialogue heats up and anger erupts, the dialogue ___28___ from collaborative to \nadversarial, and progress is likely to come to an immediate ___29___. \nIn addition, effective dialogue generally has another important characteristic: symmetry.  \nSymmetry in dialogue refers to the balance of how much each partner talks. Are you each getting equal airtime? When \none participant does most of the talking, this asymmetry or lack of balance tends to become annoying to one or both of you. \nThe silent partner ___30___ tires of only listening, while the talker can feel ___31___. Usually, both would prefer more equal \ngive and take.  \nDifferent rates of speech and levels of voice volume can ___32___ symmetry as well. The faster or louder partner can \neasily begin taking up more airtime. The slower-talking or softer-voiced one can have trouble getting the floor.  \nConversations also lose balance when one partner’s opinions count more than the other’s. One person’s input may carry \nmore sway because their style of expression is more ___33___. One viewpoint may tend to get lost because it is expressed \nmore ___34___.  \nIf either partner fairly consistently ___35___ or evaporates, modifying the pattern will be helpful. The dialogue will feel \nmore productive, and at the same time, the relationship overall is likely to feel more positive.","bank":[["A","affectionate"],["I","predominates"],["B","approximately"],["J","propagate"],["C","elapses"],["K","scenario"],["D","erode"],["L","shadow"],["E","flattered"],["M","tentatively"],["F","flips"],["N","typically"],["G","halt"],["O","vigorous"],["H","overburdened"]],"answers":{"26":"L","27":"A","28":"F","29":"G","30":"N","31":"H","32":"D","33":"O","34":"M","35":"I"}},"matching":{"statements":[{"n":36,"text":"36. We cannot see the moon at times when it is positioned right between the earth and the sun","answer":"E"},{"n":37,"text":"37. V olcanic eruptions may cause the moon to assume a moody blue color","answer":"K"},{"n":38,"text":"38. The moon will be closest to the earth when the supermoon occurs in February","answer":"G"},{"n":39,"text":"39. There is nothing unusual about the super blood wolf moon, which will bear no resemblance to a bloody wolf head","answer":"B"},{"n":40,"text":"40. The moon will appear orange when the light reflecting from it travels through an atmosphere thicker than usual","answer":"H"},{"n":41,"text":"41. It is contrary to logic to claim the name of wolf moon originates from the cultures of American Indians。","answer":"M"},{"n":42,"text":"42. As the moon’s orbit is not a hundred-percent circle, its distance from the earth changes","answer":"F"},{"n":43,"text":"43. A full moon in a given month or season gets a specific name in different cultures","answer":"N"},{"n":44,"text":"44. There are likely lots of people who know absolutely nothing about why the moon appears to change its size regularly but act like they know","answer":"D"},{"n":45,"text":"45. When a full moon appears twice in the same month, it is nicknamed a blue moon","answer":"J"}],"paragraphs":{"A":"Blue moons, rose moons, supermoons. For some reason all the websites seem to think you really want to know all about these moons. “Catch This Weekend ’s AMAZING SUPERMOON\" , one headline will announce. “The Supermoon Isn ’t Actually A Big Deal And You’re All Ruining Astronomy”, another will complain","B":"The latest example is the super blood wolf moon eclipse which sounds like the name of an emotional song I would have performed a modern dance routine to in 9th grade, but is, in fact, an astronomical event set to occur on January 20. As we'll explain below, there is nothing truly mysterious or otherwise special about this moon, and it will not look like a bloody wolf head in the sky or anything wild like that. We get these super lunar events by smashing together all the qualifiers we've historically used to keep track of full moons throughout the year, and in the age of the internet we can get a little too enthusiastic","C":"Consider this your go-to resource for all moon-gazing news. Here’s what you need to know about the latest lunar event","D":"Look, it’s okay if you don’t know. There are probably loads of folks who walk around pretending they totally know why that thing in the sky seems to get bigger and smaller at regular intervals but who totally do not","E":"The moon orbits Earth, and it’s tidally locked --- that means it always shows us the same face, instead of spinning around like our planet does. That’s why you can always see the man on the moon (or the moon rabbit, depending on your cultural preferences) even as it spins around us. But while the moon is big and bright in the sky when it’s full, that’s only because it’s reflecting light from the sun. But the moon is always moving. so it’s getting hit with sunlight at different angles. It’s invisible to us during the new moon, because our satellite is parked right between us and the sun; the so-called dark side of the moon is lit up like Las Vegas, but the side we can see is in shadow. A full moon happens when the earth is right between the sun and the moon, so sunlight hits the part we can see. And all the other phases are just the transition from one of those extremes to the other","F":"The moon isn’t always exactly the same distance from Earth, because its orbit isn’t perfectly circular. We call the closest point perigee (近地点), and the most distant point is apogee ( 远地点). 2018's closest perigee and most distant apogee bo th happened in January, and the difference was about 30,000 miles","G":"The reason you care about this ordinary change in distance is that it turns a moon super. When a full moon happens close to perigee. it's going to look a bit bigger. Honestly, the difference is not that profound, but if you’re in a position to photograph the supermoon next to something that shows the slight increase in scale, it can look pretty cool, January’s super blood wolf moon eclipse is super because the date lines up with the closest the moon will get to us during January,but the moon won't actually be at its closest for the year until February’s supermoon, which you can expect plenty of undue excitement over","H":"Blood moons only occur during total lunar eclipses (which can happe n a few times a year in any given location). When the moon slips through our shadow, we give it a reddish coloring. The moon can also look orange whenever it's rising or setting, or if it hangs low in the horizon all night --- the light bouncing off of it has to travel through a thicker atmosphere there, which scatters more blue light away. But you'll probably only see that deep, sinister red during an eclipse","I":"A lot of headlines about moons are just ridiculous (you do not need to be particularly excite d about a blue moon. it just looks like a regular full moon), but you should definitely roll out of bed to look at a blood moon if one is going to be visible in your region, even though they’re just lunar eclipses and not evidence of bloody battles between the sky gods","J":"In March of 2018, we had our second “blue moon” of the year, to much acclaim. And while that’s not necessarily special in an oh-gosh-get-out-and-look-at-it way, it’s certainly special: a blue moon is a nickname for when two full moons fall in the same calendar month, and we hadn’t previously had two in one year since 1999. We won’t have it happen again until 2037. Astronomer David Chapman explained that this is merely a peculiarity of our calendar; once we stopped doing things based on the moon and started trying to follow the sun and the seasons, we stopped ha ving one reliable full moon per month. The moon cycle is 29.53 days long on average, so in most months we stil l end up with a single new moon and a single full one. But every once in a while, one month steals a full moon from another. In 2018 (and in 1999, and again in 2037) both January and March stacked full moons on the first and last nights of the month. leaving February in the dark","K":"Getting two blue moons a year is rare, but we have individual blue moons every few years. Also, fun fact: not actually blue. A moon can indeed take on a moody blue color, but this only happens when particles of just the right size disperse through the sky --- and it has nothing to do with the moon’s status as “blue”. Big clouds of ash from volcanic eruptions or fires can do the trick, but it doesn’t happen often, and the stars would certainly have to align for two such rare instances to occur at once","L":"You may have heard that the super special second blue moon of 2018 was also a Paschal moon. This is true! That just means it was the first full moon of spring, which is often used to determine the date of Easter Sunday. All of this is just calendar nonsense and we refuse to go into it further","M":"Sometimes you'll see a headline that promises a moon with so many qualifiers it makes your head spin. A super blue blood worm moon, perhaps? Or a super blood wolf moon? Lots of websites will tell you that “wolf moon” is the traditional name of the first full moon of the year in “Native American” cultures, which is kind of a weird thing to claim given that there are 573 registered Tribal Nations in the US alone today, not to mention historically. The idea that hungry, howling wolves were such a univ ersal constant in January that all of North America with its different cultures, geographies, and languages spontaneously came up with the same nickname is illogical","N":"Many cultures have traditional names for the full moon in a given month or season, so there’s quite a list to draw from if you’re trying to really juice up a story on a slightly-bigger-than-average view of the moon. But these are all based on human calendars and activities and folklore; you will not go outside and see a pink moon in April, though I wish it were so"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"With population increases and global urbanisation ever accelerating, much attention is focused on the sustainability of \nour cities and scarce attention is paid to the countryside.  \nRural life is associated with closely-knit communities, sense of belonging, and a simple. tranquil life. Yet whilst some or \nall of these elements exist in the countryside, so do conservatism and a lack of  employment opportunities. And it is mostly \ndue to the latter that rural communities are suffering. Attracted by the improved economics of urban areas, country-dwellers \nacross the world are moving out, contributing to the excessive crowdedness of densely p opulated cities, and leaving the \ncountryside in desolation.  \nSo how can the countryside ensure its survival among these changes; or should it at all? Due to both the distance between \nresidences and facilities and often intermittent public transport, those living in the countryside are heavier automobile users. \nRural dwellers also use more energy maintaining their mostly detached buildings. We may be piled up like boxes in the city, \nbut this brings energy efficiency that the countryside cannot match. Rural e nergy requirements result in higher carbon \nemissions per person than in the city, so it is actually irresponsible to endorse such a lifestyle choice.  \nProtecting the countryside is a hot topic. Those who have made their fortunes in the city often buy second homes in the \n\f\ncountryside, visiting intermittently for a sample of a supposedly simple life. The side -effect of this is that house prices are \npushed up due to increased demand, leaving them unaffordable for local people. A solution has yet to be found for  this \nchallenge, for market forces are further forcing residents out of the countryside. For those who believe in rural preservation, \nthis is deplorable.  \nWhilst an idealised view of the countryside is common,  the reality is that rural life has continuousl y evolved. \nIndustrialisation brought an increase in divisions of labour, changing social links between rural people. The internet has \nintroduced once foreign cultures into the countryside. Improved travel connections and affordability have made the world \nmore accessible, creating a “global village”. Considering these changes, surely an evolving countryside is inevitable.  \nPerhaps the countryside should also prepare itself for massive population increases in the future. With cities across the \nworld growing rapidly, how will the current urban generation respond to the inevitable social changes of mass urbanization? \nWill the longing for a simpler life become stronger, fueling a rural renaissance?  \nAs the world continues to urbanise,  the voices calling for rural preservation may well grow louder. But change is \ninevitable, we know that the world is going to see new cities emerging from the dust and current cities growing into megacities, \nbut the future of the countryside is less clear.","questions":[{"n":46,"stem":"46. What has become of the rural areas nowadays?","options":{"A":"They are becoming somewhat deserted","C":"They are closely-knit communities","B":"They are being increasingly urbanised","D":"They are haunted by conservatism"},"answer":"A"},{"n":47,"stem":"47. What does the author think of the rural lifestyle","options":{"A":"It is unlikely to survive given the on-going changes","B":"It is less energy-efficient compared to that in cities","C":"It is highly dependent upon heavy automobiles","D":"It is a choice more affluent people will endorse"},"answer":"B"},{"n":48,"stem":"48. What does the author think of rich urban residents buying a second home in the countryside?","options":{"A":"It is bound to mar the traditional rural life","B":"It adversely impacts rural social stability","C":"It hinders rural economies’ revitalisation","D":"It is detrimental to rural preservation"},"answer":"D"},{"n":49,"stem":"49. What do we learn about the countryside with industrialisation and technological advances?","options":{"A":"It is destined to change gradually","C":"It is likely to embrace foreign cultures","B":"It will present an idealised way of life","D":"It will become increasingly diversified"},"answer":"A"},{"n":50,"stem":"50. What does the author think of the future of the countryside compared with cities?","options":{"A":"It is going to be harder for the locals","C":"It is less likely to stay static","B":"It is going to resemble that of cities","D":"It is less easy to envisage"},"answer":"D"}]},{"title":"Passage Two","passage":"Statements, like “beauty is in the eye of the beholder (观看者)”, are rarely questioned. They’ve become so embedded in \nour consciousness that people think it’s absurd to think otherwise. It might be useful, however, to at least push back on this \nassumption because people evaluate environment, situations, and people aesthetically. We may find that we still believe it is \ncorrect, but we may also find that there is a lot more to the situation than you suppose.  \nA recent study exploring aesthetic taste was published in Cognition. The results from this study show that people agree \nvery much in their aesthetic evaluation of natural objects, but they disagree more about artifacts, or human-made objects.  \nThe study found that shared taste was most common for faces and natural landscapes, but least common among works \nof architecture and art. The hypothesis is the commonly pleasing features, like proportion or symmetry, are at work.  \nPreferences for natural scenes might be learned through life experiences. Factors like habitability, safety, and openness \nmight be preferred as people develop. Some of the details of landscapes change, but the basics are more common, e.g., water, \nopen spaces, and signs of care.  \nArt and architecture, unlike natural spaces, do not have the same level of exposure. So, people do not have the same level \nof shared taste.  \n\f\nIt’s possible that the lower amount of agreement in the shared taste  of artifacts has to do more with elements of style, \nrather than “behavioral consequences”.  \nAll of the consequences seem reasonable (or at least possible) , but I think there might be an interesting philosophical \nconclusion that they did not draw. It seems that there is an objective ground to our aesthetic preferences or evaluations. I am \nnot saying this would mean beauty is completely objective , just that there could possibly be general objective principles at \nwork, i.e., beauty is not simply in the eye of the beholder. \nNature exhibits some of the universal a esthetic features such as radiance in a common way throughout the world. It ’s \nnot exactly the same everywhere,  but it is common. For example, a sunset is similar enough in different places to warrant \nalmost universal appeal.  \nPossible universal principles of beauty --- such as proportion, fittingness, radiance, and others --- are general categories, \nwhich allow for a wide array of embodiments. When people get involved in making artifacts in architecture or art, they apply \nthese very general concepts in unique ways. But the way they applied the principle may not have universal appeal.  \nThis is why it’s important to experience diverse cultures and their artifacts because it opens us up to different ways o f \napproaching or constructing beauty. And it is always good to question our assumptions.","questions":[{"n":51,"stem":"51. What does the passage say about the statement “beauty is in the eye of the beholder”?","options":{"A":"It has hardly ever been disputed","C":"Many people have found it absurd","B":"It can be interpreted aesthetically","D":"People have long been misled by it"},"answer":"A"},{"n":52,"stem":"52. What does a recent study exploring aesthetic taste show?","options":{"A":"Aesthetic tastes tend to differ from person to person","B":"Natural beauty is rarely surpassed by artificial beauty","C":"There is less consensus on objects shaped by human craft","D":"There is general agreement on what is pleasing to the eye"},"answer":"C"},{"n":53,"stem":"53. Why do people differ in their aesthetic appraisal of artifacts?","options":{"A":"They come out in a great variety of designs","B":"They lead to varying behavioral consequences","C":"They take up much less natural space than landscapes","D":"They come into people’s view less often than natural spaces"},"answer":"D"},{"n":54,"stem":"54. What does the example of sunset tell about nature?","options":{"A":"It creates a powerful appeal through its brilliant radiance","B":"It displays aesthetic traits in a similar way the world over","C":"It embodies beauty with a wide array of aesthetic features","D":"It establishes the principles of beauty in a number of ways"},"answer":"B"},{"n":55,"stem":"55. Why do artifacts not always hold universal appeal?","options":{"A":"The appreciation of their beauty is not subject to objective standards","B":"The universal principle of beauty prevents a wide array of embodiments","C":"The way their creators apply the principle of beauty may not be pleasing to everybody","D":"Their creators interpret the universal principle of beauty each in their preferred way"},"answer":"C"}]}],"translation":{"prompt":"","guide":[]},"answersReady":true},{"id":"2024-12-cet6-3","level":"CET6","year":2024,"month":12,"set":3,"title":"2024 年 12 月 · CET6 第 3 套","source":"2024年12月 第3套","writing":{"prompt":"Directions: For this part, you are allowed 30 minutes to write an essay that begins with the sentence \"College\nprovides a great opportunity for students to explore various possibilities and find the right path for\nthemselves. \" You can make comments, cite examples or use your personal experiences to develop your essay.\nYou should write at least 150 words but no more than 200 words.\n     You should copy the sentence given in quotes at the beginning of your essay.","cn":"","guide":[]},"listening":{"audio":"","note":"2024.12 六级听力音频待接入；题干在音频中，卷面只给选项。","groups":[]},"cloze":{"passage":"About 23% of the global population lives in absolute poverty. In developing countries, there is a low life expectancy, a \nhigh infant ___26___ rate, high levels of unemployment and illiteracy , nutritional levels below acceptable standards and \nwidespread disease with very little or poor-quality medical assistance. Others live ___27___ wealthy and luxurious lives and \nso the wealth is distributed in a very ___28___ manner. These are the central problems to questions of charity though charity \nalso includes many other areas such as assisting the elderly.  \nWe all ___29___ when very rich people pledge to give away most of their billions, but they are usually left with millions \nto pass on, still much more than most people would expect to earn in their lifetime. Even comparatively ___30___ salaries in \nthe west are very high when compared globally. Someone on £20,000 could easily afford to give away £2,000 per year and \nstill have plenty to live on plus some luxuries.  \nMost people agree that giving to charity is morally ___31___ but charitable behaviour tends to be regarded as above and \nbeyond the call of duty. Some argue, however, that charitable behaviour is morally required. This means that to fail to behave \ncharitably would be wrong. The majority of arguments in this vein refer to giving aid to poorer nations but they may also refer \nto giving time within one ’s ___32___ community. Arguments tend to place different requirements on people in different \nincome brackets and ___33___ entirely people who are merely making ends meet. Some argue that people should all \ncontribute a certain percentage of their earnings. I will ___34___ together all those arguments that place a moral requirement \non people to give to charity, despite the fact that there is wide disagreement as to the ___35___ of that moral requirement.","bank":[["A","applaud"],["I","moderate"],["B","casualty"],["J","mortality"],["C","exclude"],["K","overt"],["D","extent"],["L","praiseworthy"],["E","group"],["M","probe"],["F","hierarchical"],["N","sceptically"],["G","immediate"],["O","unequal"],["H","incredibly"]],"answers":{"26":"J","27":"H","28":"O","29":"A","30":"I","31":"L","32":"G","33":"C","34":"E","35":"D"}},"matching":{"statements":[{"n":36,"text":"36. People became more and more reliant on others for basic needs as they entered the modern world even though they might feel less so","answer":"G"},{"n":37,"text":"37. On the topic of trade, productive debates might be possible, in contrast to the familiar mutual condemnation in discussing other issues","answer":"C"},{"n":38,"text":"38. We feel great er independence than we actually possess because money allows us to buy things without building any relationships","answer":"I"},{"n":39,"text":"39. The trouble with today’s trade stems from misconceptions rather than money","answer":"D"},{"n":40,"text":"40. For their arguments to prevail, advocates of free trade must try to forge bonds of affection between consumers at home and producers overseas","answer":"M"},{"n":41,"text":"41. According to Tocqueville, unlike our ancestors, we and the people we do trade with are strangers to each other","answer":"J"},{"n":42,"text":"42. In primitive societies, people had to rely mostly on themselves to meet their personal needs","answer":"E"},{"n":43,"text":"43. Few commodities in American homes are not reliant on people abroad in the process of manufacture and sale","answer":"H"},{"n":44,"text":"44. Protectionists argue against free trade by referring to the losses suffered by domestic producers and communities","answer":"A"},{"n":45,"text":"45. It is extremely hard to make people feel dependent on and grateful to strangers overseas","answer":"L"}],"paragraphs":{"A":"Trade is one of the policy areas where the hostility that exists between populists ( 民粹主义者) and classical liberals is most visible. Free-traders point to the undeniable good that tariff-free trade has done for consumers across the world and to the observable alleviation of poverty in corners of the world where previously closed markets have b een opened up . Protectionists point to the domestic producers who've paid the price for this globalized economy in the form of lost livelihoods and hollowed-out communities","B":"The ongoing conservative civil war often degenerates into content-free tribal warfare, but trade is a rare exception. There are substantial, thought-out policy proposals on both sides of the argument","C":"Consequently, trade as a topic of discussion provides an opportunity for liberals and populists to have a real meeting of minds. Fruitful debates might actually take place in this area, as opposed to the familiar ritual we've become accustomed to of condemnation met with counter-condemnation","D":"Strange as it might sound, the problem with trade in the modern world isn’t a matter of dollars and cents. It’s a matter of false consciousness. This observation is bound to set Marxist alarm bells ringing in the minds of some readers, but it was first made by Alexis de Tocqueville in 1840","E":"Tracking the economic development of mankind fr om primitive to modern soci eties, Tocqueville observed a paradox unfolding over the centuries as economic realities and human experience of those realities strayed further and further from each other. In primitive societies , he notes, the division of labor was as yet undeveloped for the most part , requiring each person, family, or tribe to be relatively independent when it came to meeting their own basic material needs. Men built their own dwellings, farmed their own land, tended to their own livestock. This is not to deny that basic forms of trade took place, but, for the most part, our primitive ancestors lived fairly self-reliant, if crushingly poor, lives","F":"However, the exclusively local and face-to-face nature of economic and political organization in the ancient and prehistoric worlds constantly impressed upon these primitive peoples the uncontrollable reality of others and their needs. As Tocqueville notes, “as soon as a man begins to deal with common affairs in public, he begins to perceive that he is not so independent of his fellow men as he had first imagined, and that in order to obtain their support he must often lend them his cooperation.”","G":"At the advent of the modern world, the division of labor spread further and further throughout society. Each person became more and more dependent on others for their basic needs. And yet, robbed of the engagement with our neighbors and with our local communities that our ancestors were forced into by circumstance. We feel ourselves to be more and more independent of one another. As we become more and more dependent on others, we become less and less conscious of our dependence on others. This is the paradox of trade in the modern world","H":"The false consciousness that this paradox generates causes havoc on the debates we have about free trade. There is scarcely a single commodity in any American household that isn’t dependent for its manufacture and sale, through one supply chain or another, on scores of different people spread out across the entire globe. But as Tocqueville already foresaw in 1840, we do not feel dependent on these strangers for our way of life. No sense of the dependence of our own material welfare on their work ever strikes our national consciousness. We rarely contemplate the globalized avenues of free trade with gratitude","I":"There are two reasons for this. The first, to put it bluntly, is money. Money allows us to purchase the work of others without giving any thought to them as human beings. Unlike our ancestors in their primitive townships, we rarely have to meet face- to-face the people who've invented, built, shipped, or supplied our goods. No relationship has to be built before an exchange can take place. Simply agree on a price, and you can have any goods you wish without taking a second thought for the human being involved on the other side of the transaction. In this way, money makes us feel more independent than we actually are. Each of us senses the hold that it has over our fellows. We know that if we bid highly enough we can buy ourselves out of the time-consuming labor of building relationships. Money is kind of like magic in that way. It gives us a set of rituals to perform and promises that if we do so we'll be able to wi eld power over others. The illusion is created that having enough money to buy something is the equivalent of knowing how to make it yourself. Gratitude for the anonymous men and women who make up the supply chain rarely makes its way into our consciousness","J":"Anonymity, in fact, is the second root cause of the free-trade paradox. Modernity has emancipated everyone from the limits of location and community. By and large, when we trade, we trade with strangers; when we vote, we vote for strangers; when we watch, read, or listen to stories, the tellers of the tales are strangers. As opposed to the ancestors Tocqueville compares us to, we do not know the people with whom we have to do, in either the economic or the political sphere. This is simply the shadow side of the miracle of markets , which, for the first time in history, have allowed strangers to look after each other . They've also allowed each of us to live more and more of our lives exclusively as strangers to other people. This is how Tocqueville --- rather pessimistically --- describes us: Each, standing apart, is like a stranger to the destiny of others; his children and personal friends forming for him the entire human race. As for the remainder of his fellow citizens, he is beside them, but he does not see them. He touches them, but he does not feel them. He exists only in and for himself","K":"The last sentence but one is as apt a summary as one could hope to come by of how each of us functions in the modern economy: “He touches them, but he does not feel them.”","L":"This is the greatest challenge facing defenders of free trade. It ’s exceedingly difficult for human beings to feel gratitude toward strangers, and the global marketplace that has made us so rich has also made us strangers to one another. Our brains are hardwired for tribal life, and tribes do not take kindly to strangers. Impressing a sense of dependence upon and gratitude toward foreign strangers is therefore an uphill task","M":"If free-traders are going to win policy arguments in the future, they'll have to find a wa y of forging bonds of affection between American consumers and foreign producers. Only by de-anonymizing the men and women who supply us with the goods and services we enjoy from overseas and by creating a sense of solidarity and relationship across borders that transcends economic interest can free trade win the day. Otherwise, the inborn biological upper hand that protectionists have in the form of nationalist solidarity is bound to win the day at the ballot box"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"There are hundreds of personality quizzes online that assert they can ascertain whether the right or left half of your brain \nis dominant. Left-brained people are supposedly logical and excel at language and math while right-brained people are more \nimaginative, emotionally intelligent and skilled with spatial reasoning. There’s just one problem: That’s not how brains work.  \nPopular science enthusiasts sort of took this idea and ran with it, and it’s become woven in popular culture now, and it’s \nnot going away.  \nDespite this enduring belief, there’s no such thing as being “right-brained” or “left-brained”. Whether you’re someone \nwho tends more towards creativity or logic has nothing to do with one hemisphere of your brain being dominant over the \nother. But the actual science of how the two halves of our brains work together is sometimes stranger than fiction.  \nThe human brain is divided  into two hemispheres, the left and right. In all vertebrate ( 脊椎的 ) animals, the right \nhemisphere controls the left side of the body and vice versa. And scientists have long known, thanks to the behaviors of \npatients who suffered brain injuries, that different areas of the brain do different things.  \n\f\nBut many scientists struggled with this idea, because the very suggestion that the left and right halves of the brain operate \ndifferently disrupted the idea that nature tends toward perfect symmetry.  \nWork by neuroscientists (神经科学家) has revealed the importance of different hemispheres of the brain for different \nactivities. However, their research quickly saw some misinterpretations in the general public: Some presumed creative people \nmust be right-brained and logical people left-brained. It is proven that not only is personality unrelated to the different halves \nof the brain, but people aren’t really right- or left-brained to begin with. The idea that we have left-dominant people and right-\ndominant people, and that this is related to personality, is categorically false. That’s never been supported in the neuroscience \ncommunity. Neuroscientists don’t believe that and never have.  \nWhat scientists learned is that there are really important differences between the left hemisphere and the right hemisphere. \nIt’s just that they have nothing to do with personality or whether cognitive strategy is more logical or free spirited or creative. \nWhile researchers have shown the limitations of how the hemispheres of our brains influence our lives, it ’s not difficult to \nunderstand the appeal of such ideas. People are endlessly fascinated by themselves and their friends, and the subtle differences \nin how people think about the world are really meaningful to them. When you come up with an online quiz that tells us \nsomething about ourselves, we’re drawn to that. It’s irresistible. But you have to take it with an enormous grain of salt.","questions":[{"n":46,"stem":"46. What do numerous personality quizzes online claim they are able to do?","options":{"A":"Distinguish between the two hemispheres of one’s brain","B":"Determine whether one is left-brained or right-brained","C":"Tell if one is more of a linguist or of a mathematician","D":"Ascertain how one’s brain performs different tasks"},"answer":"B"},{"n":47,"stem":"47. What does the author say is sometimes stranger than fiction?","options":{"A":"How one hemisphere of the brain impacts creativity","B":"How the two halves of our brains work alternately","C":"How the two hemispheres of our brains cooperate","D":"How one half of the brain dominates the other"},"answer":"C"},{"n":48,"stem":"48. Why did many scientists have difficulty endorsing the idea that different areas of the brain do different things?","options":{"A":"It contradicts the assumption that the two hemispheres of the brain are symmetrical","B":"It dismisses the view that the universe has been evolving in a consistent manner","C":"It is in conflict with the suggestion that the left and right halves of the brain work together","D":"It disrupts the idea that the right hemisphere of the brain controls the left side of the body"},"answer":"A"},{"n":49,"stem":"49. What belief have neuroscientists long rejected according to the passage?","options":{"A":"There are left-dominant people and right-dominant people with different personalities","B":"There are noticeable differences between the left and right hemispheres of the brain","C":"One’s personality is hardly related to the different halves of the brain","D":"Different areas of the brain are responsible for different activities"},"answer":"A"},{"n":50,"stem":"50. What are we advised to do with an online quiz that tells us something about ourselves?","options":{"A":"Challenge its authority","C":"Evaluate its popularity","B":"Scrutinize its originality","D":"Question its reliability"},"answer":"D"}]},{"title":"Passage Two","passage":"One hundred thirty-five students, four teachers, one giant classroom: This is what 9th grade looks like at Westwood High \nSchool, in Mesa, Arizona’s largest school system. There, an innovative teaching model has taken hold, an d is spreading to \nother schools in the district and beyond.  \nFive years ago, faced with high teacher turnover and declining student enrollment,  Westwood’s leaders decided to try \nsomething different. Working with professors at Arizona State University’s teachers college, they piloted a classroom model \nknown as team teaching, which allows teachers to dissolve the walls that separate their classes across physical or grade divides.  \nThe teachers share large groups of students --- sometimes 100 or more --- and rotate between group instruction, one-on-\none interventions, small study groups, or whatever the teachers as a team agree is a priority that day. What looks at times like \nchaos is in fact a carefully orchestrated plan: Each morning, the Westwood teams meet to hammer out a personalized program \n\f\nfor every student the team will focus on that day.  \nBy giving teachers more opportunity to collaborate, Mesa’s administrators hoped to fill staffing gaps and boost teacher \nmorale and retention. Initial research suggests the gamble could pay off.  \n“Teachers are doing fantastic things, but it's very rare a teacher walks into another room to see What’s happening,” said \nAndi Fourlis, superintendent of Mesa Public Schools. “Our profession is so slow to  advance because we are working in \nisolation.”  \nOf course, overhauling teaching approaches can't fix all the frustrations teachers have, such as low pay, but early results \nfrom Mesa show team teaching may be helping to reverse low morale. In a survey of hu ndreds of the district ’s teachers, \nresearchers found those who worked on teams reported greater job satisfaction, more frequent collaborations with colleagues, \nand more positive interactions with students.  \nAnother benefit of teams, teachers say, is that t hey can help each other improve their instruction. During one planning \nsession, English teacher Jeff Hall shared a performance appraisal with a science teacher: Her recent lecture on something she \ncalled “the central dogma of biology” had bewildered him and their other teammates.  \n“If the science is too confusing for me can you imagine the frustration you feel as kids? ” Hall said. But the science \nteacher, he said, wouldn’t have known about the confusion on her own.  \nThe model is not for everyone. Some teach ers approached about volunteering for a team have said they prefer to work \nalone. Team teaching can also be a scheduling nightmare. especially at schools like Westwood where only some staff work in \nteams. There are also thorny questions like how to evaluate four teachers on the performance of 135 students. But for the time \nbeing. it seems to be working.","questions":[{"n":51,"stem":"51. What do we learn about team teaching from the passage?","options":{"A":"It is generally conducted in classrooms without walls","B":"It allows students to choose teachers they favor most","C":"It prioritizes peer work over classroom instruction","D":"It is closely coordinated despite seeming confusion"},"answer":"D"},{"n":52,"stem":"52. What does initial research suggest regarding Westwood’s innovative teaching model?","options":{"A":"It could help raise teachers’ pay","C":"It could cut down overall costs:","B":"It could turn out to be a success","D":"It could end up like a gamble"},"answer":"B"},{"n":53,"stem":"53. What did superintendent Andi Fourlis say about the teaching profession?","options":{"A":"Morale cannot be boosted until teaching models are overhauled","B":"Teachers are simply too busy to visit classes of their colleagues","C":"Progress is slow due to lack of collaboration among teachers:","D":"Teachers often do fantastic things without being noticed"},"answer":"C"},{"n":54,"stem":"54. What does the author want to show by citing English teacher Jeff Hall’s experience?","options":{"A":"English teachers and science teachers are complementary in performing their tasks","B":"A teacher of arts and letters is completely puzzled by what a science teacher teaches","C":"The new teaching model helps inform the teacher how their instruction is received","D":"Science teachers will hardly know the confusion they create without a performance appraisal"},"answer":"C"},{"n":55,"stem":"55. What does the author think is one of the difficult problems in implementing the new teaching model?","options":{"A":"What to do with teachers working alone","C":"How to recruit volunteers for a team","B":"What to include in teaching schedules","D":"How to assess each teacher’s performance"},"answer":"D"}]}],"translation":{"prompt":"","guide":[]},"answersReady":true},{"id":"2024-06-cet6-1","level":"CET6","year":2024,"month":6,"set":1,"title":"2024 年 6 月 · CET6 第 1 套","source":"2024年6月 第1套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"Reply to the man's last proposal within a short time","B":"Sign the agreement if one small change is made to it","C":"Make a sponsorship deal for her client at the meeting","D":"Give the man some good news regarding the contract"},"answer":"B","stem":""},{"n":2,"options":{"A":"They are becoming impatient","C":"They are used to making alterations","B":"They are afraid time is running out","D":"They are concerned about the details"},"answer":"A","stem":""},{"n":3,"options":{"A":"To prevent geographical discrimination","C":"To avoid any conflict of interest","B":"To tap the food and beverage market","D":"To reduce unfair competition"},"answer":"C","stem":""},{"n":4,"options":{"A":"It is a potential market for food and beverage","C":"It is a negligible market for his company","B":"It is very attractive for real estate developers","D":"It is very different from other markets."},"answer":"C","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"They are thrilled by a rare astronomic phenomenon","B":"They are celebrating a big event on mountain tops","C":"They are enthusiastic about big science-related stories","D":"They are joined by astronomers all across North America"},"answer":"A","stem":""},{"n":6,"options":{"A":"It will be the most formidable of its kind in over a century","B":"It will come closest to Earth in more than one hundred years","C":"It will eclipse many other such events in human history","D":"It will be seen most clearly from Denver's mountain tops"},"answer":"B","stem":""},{"n":7,"options":{"A":"A blur","B":"Stars","C":"The edge of our galaxy","D":"An ordinary flying object"},"answer":"A","stem":""},{"n":8,"options":{"A":"Use professional equipment","C":"Fix their eyes due north","B":"Climb to the nearby heights","D":"Make use of phone apps"},"answer":"D","stem":""}]},{"intro":"Questions 9 to 11 are based on the passage you have just heard","questions":[{"n":9,"options":{"A":"Whether consumers should be warned against ultra-processed foods","B":"Whether there is sufficient scientific consensus on dietary guidelines","C":"Whether guidelines can form the basis for nutrition advice to consumers","D":"Whether food scientists will agree on the concept of ultra-processed foods"},"answer":"A","stem":""},{"n":10,"options":{"A":"By the labor cost for the final products","C":"By the extent of chemical alteration","B":"By the degree of industrial processing","D":"By the convention of classification"},"answer":"B","stem":""},{"n":11,"options":{"A":"Increased consumers' expenses","C":"People‘s misunderstanding of nutrition","B":"Greater risk of chronic diseases","D":"Children’s dislike for unprocessed foods"},"answer":"B","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"They begin to think of the benefits of constraints","C":"They try hard to maximize their mental energy","B":"They try to seek solutions from creative people","D":"They begin to see the world in a different way"},"answer":"D","stem":""},{"n":13,"options":{"A":"It is characteristic of all creative people","C":"It is a creative persons response to limitation","B":"It is essential to pushing society forward","D":"It is an impetus to socio-economic development"},"answer":"C","stem":""},{"n":14,"options":{"A":"Scarcity or abundance of resources has little impact on people's creativity","B":"Innovative people are not constrained in connecting unrelated concepts","C":"People have no incentive to use available resources in new ways","D":"Creative people tend to consume more available resources"},"answer":"C","stem":""},{"n":15,"options":{"A":"It is key to a company's survival","C":"It is essential to meeting challenges","B":"It shapes and focuses problems:","D":"It thrives best when constrained"},"answer":"D","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"Because they are learned","C":"Because they have to be properly personalized","B":"Because they come naturally","D":"Because there can be more effective strategies"},"answer":"A","stem":""},{"n":17,"options":{"A":"The extent of difference and of similarity between the two sides","B":"The knowledge of the specific expectation the other side holds","C":"The importance of one's goals and of the relationship","D":"The approaches one adopts to conflict management"},"answer":"C","stem":""},{"n":18,"options":{"A":"The fox","B":"The owl","C":"The shark","D":"The turtle."},"answer":"B","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"Help save species from extinction and boost human health","B":"Understand how plants and animals perished over the past","C":"Help gather information publicly available to researchers","D":"Find out the cause of extinction of Britain's 66,000 species"},"answer":"A","stem":""},{"n":20,"options":{"A":"It was once dominated by dinosaurs","C":"Its prospects depend on future human behavior","B":"It has entered the sixth mass extinction","D":"Its climate change is aggravated by humans"},"answer":"B","stem":""},{"n":21,"options":{"A":"It dwarfs all other efforts to conserve, protect and restore biodiversity on earth","B":"It is costly to get started and requires the joint efforts of thousands of scientists","C":"It can help to bring back the large numbers of plants and animals that have gone extinct","D":"It is the most exciting, most relevant, most timely and most internationally inspirational"},"answer":"D","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Cultural identity","C":"The Copernican revolution","B":"Social evolution","D":"Human individuality"},"answer":"D","stem":""},{"n":23,"options":{"A":"It is a delusion to be disposed of","C":"It is a myth spread by John Donne’s poem","B":"It is prevalent even among academics","D":"It is rooted in the mindset of the 17th century"},"answer":"A","stem":""},{"n":24,"options":{"A":"He believes in Copernican philosophical doctrines about the universe","B":"He has gained ample scientific evidence at the University of Reading","C":"He has found that our inner self and material self are interconnected","D":"He contends most of our body cells can only live a few days or weeks"},"answer":"D","stem":""},{"n":25,"options":{"A":"By coming to see how disruptive such problems have got to be","B":"By realising that we all can do our own bit in such endeavours","C":"By becoming aware that we are part of a bigger world","D":"By making joint efforts resolutely and persistently"},"answer":"C","stem":""}]}]},"cloze":{"passage":"It’s quite remarkable how different genres of music can spark unique feelings, emotions, and memories. Studies have \nshown that music can reduce stress and anxiety before surgeries and we are all attracted toward our own unique life \nsoundtrack.  \nIf you're looking to ___26___ stress, you might want to give classical music a try.  \n\f\nThe sounds of classical music produce a calming effect letting ___27___ “pleasure-inducing dopamine(多巴胺) in the \nbrain that helps control attention, learning and emotional responses. It can also turn down the body’s stress response, \nresulting in an overall happier mood. It turns out a pleasant mood can lead to ___28___ in a person’s thinking.  \nAlthough there are many great ___29___ of classical music like Bach, Beethoven and Handel, none of these artists' \nmusic seems to have the same health effects as Mozart’s does. According to researchers, listening to Mozart can increase \nbrain wave activity and improve ___30___ function. Another study found that the distinctive features of Mozart’s music \ntrigger parts of the brain that are responsible for high-level mental functions. Even maternity ___31___ use Mozart to help \nnewborn babies adapt to life outside of the mother’s belly.  \nIt has been found that listening to classical music ___32___ reduces a person’s blood pressure. Researchers believe \nthat the calming sounds of classical music may help your heart ___33___ from stress. Classical music can also be a great \ntool to help people who have trouble sleeping. One study found that students who had trouble sleeping slept better while \nthey were listening to classical music.  \nWhether classical music is something that you listen to on a regular basis or not, it wouldn't ___34___to take time out \nof your day to listen to music that you find ___35___. You will be surprised at how good it makes you feel and the \npotentially positive change in your health.","bank":[["A","alleviate"],["I","loose"],["B","clarity"],["J","majestic"],["C","cognitive"],["K","mandatory"],["D","composers"],["L","recover"],["E","hurt"],["M","significantly"],["F","inhibiting"],["N","soothing"],["G","interrogation"],["O","wards"],["H","intrinsically"]],"answers":{"26":"A","27":"I","28":"B","29":"D","30":"C","31":"O","32":"M","33":"L","34":"E","35":"N"}},"matching":{"statements":[{"n":36,"text":"36.Jackson was said to have transferred his ownership of the oak tree to itself in order to protect it from being destroyed","answer":"C"},{"n":37,"text":"37.No proof has been found from an extensive search that Jackson had ever owned the land where the oak tree grew","answer":"H"},{"n":38,"text":"38.When it was raining heavily, Jackson often took shelter under a big tree that is said to own itself","answer":"B"},{"n":39,"text":"39.There is no evidence that Jackson had made arrangements to pay property taxes for the land on which the oak tree sat","answer":"K"},{"n":40,"text":"40.Professor Ward paid Jackson over one thousand dollars when purchasing a piece of land from him. 41.1t is said the tree that owned itself fell in a heavy windstorm","answer":"I"},{"n":42,"text":"42.The story of the oak tree is suspected to have been invented as a thought exercise","answer":"N"},{"n":43,"text":"43.Jackson's little plantation was auctioned off to settle his debt in the mid-19th century","answer":"J"},{"n":44,"text":"44.An official ceremony was held to celebrate the transplanting of a small tree to where its ancestor had stood","answer":"E"},{"n":45,"text":"45.The story of the Tree That Owns Itself appeared in the local paper several times, with slight alterations in wording","answer":"O"}],"paragraphs":{"A":"ln the city of Athens, Georgia, there exists a rather curious local landmark—a large white oak that is almost universally stated to own itself. Because of this, it is considered one of the most famous trees in the world. So how did this tree come to own itself and the land around it?","B":"Sometime in the 19th century a Georgian called Colonel William Jackson reportedly took a liking to the said tree and endeavored to protect it from any danger. As to why he loved it so, the earliest documented account of this story is an anonymously written front page article in the Athens Weekly Banner published on August 12,1890. It states, “Col. Jackson had watched the tree grow from his childhood, and grew to love it almost as he would a human. Its luxuriant leaves and sturdy limbs had often protected him from the heavy rains, and out of its highest branches he had many a time gotten the eggs of the feathered singers. He watched its growth, and when reaching a ripe old age he saw the tree standing in its magnificent proportions, he was pained to think that after his death it would fall into the hands of those who might destroy it.”","C":"Towards this end, Jackson transferred by means of a deed ownership of the tree and a little land around it to the tree itself. The deed read, “W. H. Jackson for and in consideration of the great affection which he bears the said tree, and his great desire to see it protected has conveyed unto the said oak tree entire possession of itself and of all land within eight feet of it on all sides.”","D":"In time, the tree came to be something of a tourist attraction known as The Tree That Owns Itself. However, in the early 20th century, the tree started showing signs of its slow death, with little that could be done about it. Father time comes for us all eventually, even our often long lived tall and leafy fellow custodians(看管者) of Earth. Finally, on October 9,1942, the over 30 meter tall and 200-400 year old tree fell, rumor has it, as a result of a severe windstorm and/or via having previously died and its roots rotted","E":"About four years later, members of the Junior Ladies Garden Club (who’d tended to the tree before its unfortunate death) tracked down a small tree grown from a nut taken from the original tree. And so it was that on October 9,1946, under the direction of Professor Roy Bowden of the College of Agriculture at the University of Georgia, this little tree was transplanted to the location of its ancestor. A couple of months later, an official ceremony was held featuring none other than the Mayor of Athens, Robert L McWhorter, to commemorate the occasion","F":"This new tree became known as The Son of the Tree That Owns Itself, and it was assumed that as the original tree’s heir, it naturally inherited the land it stood on. Of course, there are many dozens of other trees known to exist descending from the original as people taking a nut from it to grow elsewhere was a certainty. That said, to date, none of the original trees other children have petitioned the courts for their share of the land, so it seems all good. In any event, The Son of the Tree That Owns Itself still stands today, though often referred to simply as The Tree That Owns Itself","G":"This all brings us around to whether Jackson ever actually gave legal ownership of the tree to itself in the first place and whether such a deed is legally binding","H":"Well, to begin with, it turns out Jackson only spent about three years of his life in Athens, starting at the age of 43 from 1829 to 1832, sort of dismissing the idea that he loved the tree from spending time under it as a child and watching it grow, and then worrying about what would happen to it after he died. Further, an extensive search of land ownership records in Athens does not seem to indicate Jackson ever owned the land the tree sits on","I":"He did live on a lot of land directly next to it for those three years, but whether he owned that land or not isn't clear. Whatever the case, in 1832 a four acre parcel, which included the land the tree was on and the neighboring land Jackson lived on, among others, was sold to University professor Malthus A Ward. In the transaction, Ward was required to pay Jackson a sum of $1,200 (about $31,000 today), either for the property itself or simply in compensation for improvements Jackson had made on the lot. In the end, whether he ever owned the neighboring lot or was simply allowed to use it while he allegedly worked at the University, he definitely never owned the lot the tree grew on, which is the most important bit for the topic at hand","J":"After Professor Ward purchased the land, Jackson and his family purchased a 655 acre parcel a few miles away and moved there. Ten years later, in 1844, Jackson seemed to have come into financial difficulties and had his little plantation seized by the Clarke County Sheriff’s office and auctioned off to settle the mortgage. Thus, had he owned some land in Athens itself including the land the tree sat on, presumably he would have sold it to raise funds or otherwise had it taken as well","K":"And whatever the case there Jackson would have known property taxes needed to be paid on the deeded land for the tree to be truly secure in its future. Yet no account or record indicates any trust or the like was set up to facilitate this","L":"On top of all this, there is no hard evidence such a deed ever existed, despite the fact that deed records in Athens go back many decades before Jackson's death in 1876 and that it was supposed to have existed in 1890 in the archives according to the original anonymous news reporter who claims to have seen it","M":"As you might imagine from all of this, few give credit to this side of the story. So how did all of this come about then?","N":"It is speculated to have been invented by the imagination of the said anonymous author at the Athens Weekly Banner in the aforementioned 1890 front page article titled “Deeded to Itself”, which by the way contained several elements that are much more easily proved to be false. As to why the author would do this, it's speculated perhaps it was a 19th century version of a click-bait thought exercise on whether it would be legal for someone to deed such a non-conscious living thing to itself or not","O":"Whatever the cases the next known instance of the Tree That Owns Itself being mentioned wasn't until 1901 in the Centennial Edition of that same paper the Athens Weekly Banner. This featured another account very clearly just copying the original article published about a decade before, only slightly reworded. The next account was in 1906, again in the Athens Weekly Banner, again very clearly copying the original account, only slightly reworded, the 19th century equivalent of re-posts when the audience has forgotten about the original"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N","O"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"It is irrefutable that employees know the difference between right and wrong.  So why don't more employees intervene \nwhen they see someone exhibiting at-risk behavior in the workplace?  \nThere are a number of factors that influence whether people intervene. First, they need to be able to see a risky situation \nbeginning to unfold. Second, the company's culture needs to make them feel safe to speak up.  And third, they need to have \nthe communication skills to say something effectively.  \nThis is not strictly a workplace problem, it is a growing problem off the job too. Every day people witness things on the \nstreet and choose to stand idly by.  This is known as the bystander effect —the more people who witnes s an event, the less \nlikely anyone in that group is to help the victim. The psychology behind this is called diffusion of responsibility. Basically the \nlarger the crowd, the more people assume that someone else will take care of it —meaning no one effectively intervenes or \nacts in a moment of need.  \nThis crowd mentality is strong enough for people to evade their known responsibilities. But it's not only frontline workers \nwho don't make safety interventions in the workplace. There are also instances where supervisors do not intervene either.  \nWhen a group of employees sees unsafe behavior not being addressed at a leadership level it creates the precedent that \nthis is how these situations should be addressed, thus defining the safety culture for everyone.  \nDespite the fact that workers are encouraged to intervene when they observe unsafe operations,  this happens less than \nhalf of the time. Fear is the ultimate factor in not intervening.  There is a fear of penalty, a fear that they'll have to do more \nwork if they  intervene. Unsuccessful attempts in the past are another strong contributing factor to why people don't \nintervene—they tend to prefer to defer that action to someone else for all future situations.  \nOn many worksites, competent workers must be appointed. Part of their job is to intervene when workers perform a task \nwithout the proper equipment or if the conditions are unsafe.  Competent workers are also  required to stop work from \ncontinuing when there's a danger.  \nSupervisors also play a critical role. Even if a competent person isn't required, supervisors need a broad set of skills to \nnot only identify and alleviate workplace hazards but also build a safety climate within their  team that supports intervening \nand open communication among them.  \n\f\nBeyond competent workers and supervisors,  it's important to educate everyone within the organization that they are \nobliged to intervene if they witness a possible unsafe act  whether you're a designated competent person, a supervisor, or a \nfrontline worker.","questions":[{"n":46,"stem":"46.What is one of the factors contributing to failure of intervention in face of risky behavior in the workplace?","options":{"A":"Slack supervision style","C":"Unforeseeable risk","B":"Unfavorable workplace culture","D":"Blocked communication"},"answer":"B"},{"n":47,"stem":"47.What does the author mean by “diffusion of responsibility” (Para.3)?","options":{"A":"The more people are around, the more they need to worry about their personal safety","B":"The more people who witness an event, the less likely anyone will venture to participate","C":"The more people idling around on the street, the more likely they need taking care of","D":"The more people are around, the less chance someone will step forward to intervene"},"answer":"D"},{"n":48,"stem":"48.What happens when unsafe behavior at the workplace is not addressed by the leaders?","options":{"A":"No one will intervene when they see similar behaviors","B":"Everyone will see it as the easiest way to deal with crisis","C":"Workers have to take extra caution executing their duties","D":"Workers are left to take care of the emergency themselves"},"answer":"A"},{"n":49,"stem":"49.What is the ultimate reason workers won't act when they see unsafe operations?","options":{"A":"Preference of deferring the action to others","C":"Fear of being isolated by coworkers","B":"Anticipation of leadership intervention","D":"Fear of having to do more work"},"answer":"D"},{"n":50,"stem":"50.What is critical to ensuring workplace safety?","options":{"A":"Workers be trained to operate their equipment properly","B":"Workers exhibiting at-risk behavior be strictly disciplined","C":"Supervisors create a safety environment for timely intervention","D":"Supervisors conduct effective communication with frontline workers"},"answer":"C"}]},{"title":"Passage Two","passage":"The term “environmentalist” can mean different things. It used to refer to people trying to protect wildlife and natural \necosystems. In the 21st century, the term has evolved to capture the need to combat human-made climate change.  \nThe distinction between these two strands of environmentalism is the cause of a split within the scientific community \nabout nuclear energy  \nOn one side are purists who believe nuclear power isn’t worth the risk and the exclusive solution to the climate crisis is \nrenewable energy. The opposing side agrees that renewables are crucial, but says society needs an amount of power \navailable to meet consumers basic demands when the sun isn’t shining and the wind isn't blowing. Nuclear energy, being far \ncleaner than oil, gas and coal, is a natural option, especially where hydroelectric capacity is limited.  \nLeon Clarke, who helped author reports for the UN’s Intergovernmental Panel on Climate Change, isn’t an uncritical \nsupporter of nuclear energy, but says it's a valuable option to have if we're serious about reaching carbon neutrality.  \n“Core to all of this is the degree to which you think we can actually meet climate goals with 100% renewables,” he \nsaid. “If you don’t believe we can do it, and you care about the climate, you are forced to think about something like \nnuclear.”  \nThe achievability of universal 100% renewability is similarly contentious. Cities such as Burlington, V ermont have \nbeen “100% renewable” for years. But these cities often have small populations, occasionally still rely on fossil fuel energy \nand have significant renewable resources at their immediate disposal. Meanwhile, countries that manage to run off \nrenewables typically do so thanks to extraordinary hydroelectric capabilities.  \nGermany stands as the best case study for a large, industrialized country pushing into green energy. Chancellor Angela \nMerkel in 2011 announced Energiewende, an energy transition that would phase out nuclear and coal while phasing in \nrenewables. Wind and solar power generation has increased over 400% since 2010, and renewables provided 46% of the \ncountry’s electricity in 2019.  \n\f\nBut progress has halted in recent years. The instability of renewables doesn't just mean energy is often not produced at \nnight but also that solar and wind can overwhelm the grid during the day, forcing utilities to pay customers to use their \nelectricity. Lagging grid infrastructure struggles to transport this overabundance of green energy from Germany's north to its \nindustrial south, meaning many factories still run on coal and gas. The political limit has also been reached in some places, \nwith citizens meeting the construction of new wind turbines with loud protests.  \nThe result is that Germany's greenhouse gas emissions have fallen by around 11.5% since 2010—slower than the EU \naverage of 13.5%.","questions":[{"n":51,"stem":"51.What accounts for the divide within the scientific community about nuclear energy?","options":{"A":"Attention to combating human-made climate change","B":"Emphasis on protecting wildlife and natural ecosystems","C":"Evolution of the term ‘green energy’ over the last century","D":"Adherence to different interpretations of environmentalism"},"answer":"D"},{"n":52,"stem":"52.What is the solution to energy shortage proposed by purists' opponents?","options":{"A":"Relying on renewables firmly and exclusively","C":"Opting for nuclear energy when necessary","B":"Using fossil fuel and green energy alternately","D":"Limiting people’s non-basic consumption"},"answer":"C"},{"n":53,"stem":"53.What point does the author want to make with cities like Burlington as an example?","options":{"A":"It is controversial whether the goal of the whole world's exclusive dependence on renewables s attainable","B":"It is contentious whether cities with large populations have renewable resources at their immediate disposal","C":"It is arguable whether cities that manage to run off renewables have sustainable hydroelectric capabilities","D":"It is debatable whether traditional fossil fuel energy can be done away with entirely throughout the world"},"answer":"A"},{"n":54,"stem":"54.What do we learn about Germany regarding renewable energy?","options":{"A":"It has increased its wind and solar power generation four times over the last two decades","B":"It represents a good example of a major industrialized country promoting green energy","C":"It relies on renewable energy to generate more than half of its electricity","D":"It has succeeded in reaching the goal of energy transition set by Merkel"},"answer":"B"},{"n":55,"stem":"55.What may be one of the reasons for Germany's progress having halted in recent years?","options":{"A":"Its grid infrastructure's capacity has fallen behind its development of green energy","B":"Its overabundance of green energy has forced power plants to suspend operation during daytime","C":"Its industrial south is used to running factories on conventional energy supplies","D":"Its renewable energy supplies are unstable both at night and during the day"},"answer":"A"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true},{"id":"2024-06-cet6-2","level":"CET6","year":2024,"month":6,"set":2,"title":"2024 年 6 月 · CET6 第 2 套","source":"2024年6月 第2套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"听力音频待接入；题干在音频中，卷面只给选项。","groups":[{"intro":"Questions 1 to 4 are based on the conversation you have just heard","questions":[{"n":1,"options":{"A":"Read numerous comments users put online","B":"Blended all his food without using a machine","C":"Searched for the state-of-the-art models of blenders","D":"Did thorough research on the price of kitchen appliances"},"answer":"A","stem":""},{"n":2,"options":{"A":"Eating any blended food","C":"Using machines to do her cooking","B":"Buying a blender herself","D":"Making soups and juices for herself"},"answer":"B","stem":""},{"n":3,"options":{"A":"Cooking every meal creatively in the kitchen","C":"Eating breakfast punctually every morning","B":"Paying due attention to his personal hygiene","D":"Making his own fresh fruit juice regularly"},"answer":"D","stem":""},{"n":4,"options":{"A":"One-tenth of it is sugar","C":"One's fancy may be tickled by it","B":"It looks healthy and attractive","D":"It contains an assortment of nutrients."},"answer":"A","stem":""}]},{"intro":"Questions 5 to 8 are based on the conversation you have just heard","questions":[{"n":5,"options":{"A":"How he has made himself popular as the mayor of Berkton","B":"How the residents will turn Berkton into a tourist attraction","C":"How charming he himself considers the village of Berkton to be","D":"How he has led people of Berkton to change the village radically"},"answer":"D","stem":""},{"n":6,"options":{"A":"It was developed only to a limited extent","C":"It was relatively unknown to the outside","B":"It was totally isolated as a sleepy village","D":"It was endowed with rare natural resources"},"answer":"C","stem":""},{"n":7,"options":{"A":"The people in Berkton were in a harmonious atmosphere","B":"The majority of residents lived in harmony with their neighbors","C":"The majority of residents enjoyed cosy housing conditions","D":"AII the houses in Berkton looked aesthetically similar"},"answer":"D","stem":""},{"n":8,"options":{"A":"They have helped boost the local economy","B":"They have made the residents unusually proud","C":"They have contributed considerably to its popularity","D":"They have brought happiness to everyone in the village"},"answer":"A","stem":""}]},{"intro":"Questions 9 to 11 are based on the passage you have just heard","questions":[{"n":9,"options":{"A":"They have created the smallest remote-controlled walking robot in the world","B":"They are going to publish their research findings in the journal Science Robotics","C":"They are the first to build a robot that can bend, crawl, walk, turn and even jump","D":"They are engaged in research on a remote-controlled robot which uses special power"},"answer":"A","stem":""},{"n":10,"options":{"A":"It changes its shape by complex hardware","B":"It is operated by a special type of tiny motor","C":"It moves from one place to another by memory","D":"It is powered by the elastic property of its body"},"answer":"D","stem":""},{"n":11,"options":{"A":"Replace humans in exploratory tasks","B":"Perform tasks in tightly confined spaces","C":"Explore the structure of clogged arteries","D":"Assist surgeons in highly complex surgery"},"answer":"B","stem":""}]},{"intro":"Questions 12 to 15 are based on the passage you have just heard","questions":[{"n":12,"options":{"A":"She threw up in the bathroom","B":"She slept during the entire ride","C":"She dozed off for a few minutes","D":"She boasted of her marathon race"},"answer":"B","stem":""},{"n":13,"options":{"A":"They are mostly immune to cognitive impairment","B":"They can sleep soundly during a rough ride at sea","C":"They are genetically determined to need less sleep","D":"They constitute about 13 percent of the population"},"answer":"C","stem":""},{"n":14,"options":{"A":"Whether there is a way to reach elite status","B":"Whether it is possible to modify one's genes","C":"Whether having a baby impacts one's passion","D":"Whether one can train themselves to sleep less"},"answer":"D","stem":""},{"n":15,"options":{"A":"It is in fact quite possible to nurture a passion for sleep","B":"Babies can severely disrupt their parents' sleep patterns","C":"Being forced to rise early differs from being an early bird","D":"New parents are forced to jump out of bed at the crack of dawn"},"answer":"C","stem":""}]},{"intro":"Questions 16 to 18 are based on the recording you have just heard","questions":[{"n":16,"options":{"A":"We have poor awareness of how many controversial issues are being debated","B":"No one knows better than yourself what you are thinking about at the moment","C":"No one can change your opinions more than those who speak in a convincing tone","D":"We are likely to underestimate how much we can be swayed by a convincing article"},"answer":"D","stem":""},{"n":17,"options":{"A":"Their belief about physical punishment changed","B":"Their memory pushed them toward a current belief","C":"The memory of their initial belief came back to them","D":"Their experiences of physical punishment haunted them"},"answer":"A","stem":""},{"n":18,"options":{"A":"They apparently have little to do with moderate beliefs","B":"They don't reflect the changes of view on physical punishment","C":"They may not apply to changes to extreme or deeply held beliefs","D":"They are unlikely to alter people's position without more evidence"},"answer":"C","stem":""}]},{"intro":"Questions 19 to 21 are based on the recording you have just heard","questions":[{"n":19,"options":{"A":"American moms have been increasingly inclined to live alone","B":"The American population has been on the rise in the past 25 years","C":"American motherhood has actually been on the decline","D":"The fertility rates in America have in fact been falling sharply"},"answer":"C","stem":""},{"n":20,"options":{"A":"More new mothers tend to take greater care of their children","B":"More new mothers are economically able to raise children","C":"A larger proportion of women take pride in their children","D":"A larger proportion of women really enjoy motherhood"},"answer":"B","stem":""},{"n":21,"options":{"A":"The meaning of motherhood has changed considerably","B":"More and more mothers go shopping to treat themselves","C":"More mothers have adult children celebrating the holiday","D":"The number of American mothers has been growing steadily"},"answer":"C","stem":""}]},{"intro":"Questions 22 to 25 are based on the recording you have just heard","questions":[{"n":22,"options":{"A":"Add to indoor toxic pollutants","C":"Beautify the home environment","B":"Absorb poisonous chemicals","D":"Soak up surrounding moisture"},"answer":"B","stem":""},{"n":23,"options":{"A":"NASA did experiments in sealed containers resembling the super-insulated offices of 1970s","B":"It was based on experiments under conditions unlike those in most homes or offices","C":"NASA conducted tests in outer space whose environment is different from ours","D":"It drew its conclusion without any contrastive data from other experiments"},"answer":"B","stem":""},{"n":24,"options":{"A":"Natural ventilation proves much more efficient for cleaning the air than house plants","B":"Houseplants disperse chemical compounds more quickly with people moving around","C":"Natural ventilation turns out to be most effective with doors and windows wide open","D":"Houseplants in a normal environment rarely have any adverse impact on the air"},"answer":"A","stem":""},{"n":25,"options":{"A":"The root cause for misinterpretations of scientific findings","B":"The difficulty in understanding what's actually happening","C":"The steps to be taken in arriving at any conclusion with certainty","D":"The necessity of continually re-examining and challenging findings"},"answer":"D","stem":""}]}]},"cloze":{"passage":"The Sun Is Also a Star is a truly lovely story of love, romance, fate, and destiny. \nNatasha is a Jamaican-born immigrant living __26__ in America, not by choice exactly. Her parents brought her over \nand created the situation she __27__ to be out of. \nDaniel is an American born of Korean immigrants. He believes in true love, fate, and all that other nonsense that \n\f\nNatasha __28__ through scientific reasoning.\nDaniel and Natasha meet by __29__ on the streets of New York on the day that she is to be __30__ . She doesn't tell \nhim that but does allow him to keep her company while he tries to get her to fall in love with him over the course of the day.\nNatasha is me. I found her so similar to myself. She's scientifically-minded, practical, somewhat cynical, and always \n__31__.Her obsession with the universe through a scientific lens is infectious and I __32__ Daniel seeing that too\nDaniel is charming and passionate and has a way with words that even __33__ Natasha's tough outer shell. By the end \nof the book I fell in love with both of them.\nI used to find romance stories to always be cheap or laughable. I think now I can see the value in escaping into a story \nof pure optimism. I got __34__ in The Sun Is Also a Star and finished it cover to cover in a weekend. I couldn't wait to get \nto what I hoped would be a happy ending.\nIt's nice every once in a while to give in to magic. It doesn't have to be a hard fantasy novel with actual spells, it can be \nthe magic found between two people who just have that special something. That __35__ that causes them to react and spark \nwhen they're near each other","bank":[["A","adore"],["I","illegally"],["B","appraise"],["J","lost"],["C","assaults"],["K","perpetually"],["D","chemistry"],["L","prescribed"],["E","coincidence"],["M","shrewd"],["F","cracks"],["N","skeptical"],["G","deported"],["O","strives"],["H","dismisses"]],"answers":{"26":"I","27":"O","28":"H","29":"E","30":"G","31":"N","32":"A","33":"F","34":"J","35":"D"}},"matching":{"statements":[{"n":36,"text":"36.There is general consensus among experts that willpower alone cannot guarantee one's success in changingand maintaining a habit","answer":"D"},{"n":37,"text":"37.One need not abandon their goals completely just because they missed their target temporarily; they can start anew","answer":"I"},{"n":38,"text":"38.Research shows it is quite another challenge to maintain a behavioral change after you have initiated it","answer":"A"},{"n":39,"text":"39.It is wrong to assume the strategies we use to start a change of behavior will work equally well in helping maintain it","answer":"K"},{"n":40,"text":"40.Sometimes, it may not be successful to simply substitute one activity with another to effect a change of habit; you may need extra reinforcement","answer":"H"},{"n":41,"text":"41.One should introduce something new to replace an old habit instead of simply kicking it","answer":"F"},{"n":42,"text":"42.Perfectionists focus too much on their big target and neglect celebrating the small gains they make in theprocess","answer":"J"},{"n":43,"text":"43 It is of great benefit to us in the long term to conquer the inertia that stops us from making behavioral changes","answer":"L"},{"n":44,"text":"44.The strategy that successfully changed one of your behaviors may not work for some other behavior of yours","answer":"G"},{"n":45,"text":"45.Without a happy mood, it seems that our wisdom to adopt a different behavior vanishes","answer":"K"}],"paragraphs":{"A":"According to recent research, behavioral change involves physical changes in the brain. In the past decade, researchers have shown that when it comes to the duration of making a new behavior a deep-rooted habit there is not a simple answer. Even for the most productive and disciplined among us, undoing something that has become an automatic part of who we are takes more than an overnight effort. Once we've successfully made that change, we then have to make other adjustments to our lives to ensure that we continue to maintain it, which is often a whole other challenge in itself","B":"At its core, success in changing and maintaining a behavior rarely occurs without the introduction of some sort of system. When there isn't the right framework in place, we face a greater likelihood of derailing our hard-earned progress. To ensure success in changing and maintaining a behavior, we should stay away from some detrimental habits","C":"The first one to avoid is relying on willpower. Think about the last time you vowed to resist a temptation. Perhaps you didn't want to check your phone every 15 minutes, or you were determined not to reach for a chocolate bar at 3 p.m. Think about how difficult it must have been not to glance at your phone when it waswithin reach, or not to walk to the vending machine when your afternoon slump hit","D":"The research on whether we have finite or infinite willpower is inconclusive, but experts do generally agree that you can't change and sustain a habit if you rely on your willpower alone. The old military saying “You never rise to the occasion, you only sink to the level of training” also applies to behavior change. The idea is simple—you repeat something so many times that it becomes automatic","E":"Think about what else you can change about your surrounding that makes it easier for you to perform this change on a daily basis. This is called your “cue”. Basically, it's a trigger to perform that particular habit. If you don't want to reach for a sugary treat at 3 p.m., have a box of herbal tea ready at your desk. When 3 p.m. comes around, that's your cue to pour yourself a cup of hot water and drink that tea, instead of walking to the vending machine","F":"The second one to avoid is focusing on negative goals. Sometimes, it's not your process that lets you down, but the habit that you want to change in the first place. For starters, not eating chocolate to beat your afternoon slump is a harder goal than swapping chocolate for herbal tea when you reach the designated time. Your brain wants to find routines that have succeeded in the past and allow you to repeat those actions again in the future without having to think about them explicitly. However, this habit-learning system isn't so effective when it comes to learning not to do something. That's why rather than giving up something, think about introducing something in its place. Focus on actions you are going to take that will ultimately conflict with the behaviors you want to stop. When your attention is on doing something new, you give your habit system a chance to operate","G":"The third one to avoid is using the same strategies in different circumstances. Because we are creatures of habit, it's natural to assume that when we do manage to adopt and sustain a desirable behavior, that same strategy will work when we want to make another behavior change. But that's not always the case. Sometimes, the system that got you to change one behavior might not work for another","H":"Sometimes we become accustomed to relying on our guts when it comes to decision-making. This serves us well in certain situations, but can hinder us in others especially when we need to consider metrics and data,rather than letting our instinct override everything. For example, if you want to stop checking your email first thing in the morning, you might decide to substitute another activity in its place. But if you want to stop indulging in video games, simply deciding you will go for a run might not be as effective. You might need to introduce another reinforcement, such as meeting a friend and booking an exercise class together","I":"The fourth one to avoid is not forgiving ourselves for slipping up. Of course, even the best-laid plans fail sometimes. You might have stuck to your screen-free nighttime routine for five days, and then a big project landed on your desk and you found yourself in bed with your laptop before you went to sleep. Or you prepared meals on Sunday and stuck to eating healthy dinners at home, but by Friday you found yourself so exhausted and opted to order greasy takeout. Life happens and even if your behavior change is small, every single day can prove pretty inflexible, and at some point your luck may run out, even if just for a day. The perfectionist in you might be screaming to abandon your goals altogether, but try to see it in the bigger picture. Just because you might have temporarily strayed off course doesn't mean you can't start afresh thenext day","J":"The final one to avoid is discounting small progress. There's a habit that many perfectionists tend to fall into when they try to establish a behavior change. They focus too much on the big goal and don't take the time to celebrate the small progress they make in the process. Your brain responds to rewards. The basal ganglia, the brain region linked to our performance of habits, is most active at the beginning of a behavior, when the habit is cued, and at the end, when it's rewarded. Say your goal is to run five miles three times a week, and this week you ran one mile on Monday, Wednesday, and Friday. Rather than focusing on how far you've gone toward your goal, think about how you can reward yourself for the progress you've made. It doesn't have to be big or expensive; it can be something as simple as making your favorite fruit juice after your run. Whatever your reward, it has to be more than just the activity itself to get you going","K":"Initiating a new behavior usually seems like the hardest part of the process of change. However, people often fail to adequately prepare for maintaining it. One of the reasons for this is because we mistakenly believethe strategies we used to initiate the change will be equally effective in helping us continue the change. But they won't. Where changing a strongly deep-rooted habit requires changing our belief about that habit that penetrates deeply into our lives, continually manifesting that wisdom requires that we maintain a positive outlook. If our mood is low, the wisdom to behave differently seems to disappear and we go back to eating more and exercising less. The key, then, to maintaining new behaviors is to be happy! Which is why it's so hard to maintain new behaviors","L":"Remember, overcoming the behavioral inertia that prevents us from implementing new changes, like eating a healthy diet or exercising, can benefit us in the long run and can improve our physical and mental health. No one was born with habits. They were all learned, and can all, therefore, be unlearned. The question is: how badly do you really want to change?"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"The “American Dream” promises that in the Land of Opportunity,  any individual can climb the economic ladder and \nprosper through hard work and ambition alone.  And yet. young Americans today are struggling to earn more than  their \nparents did at the same age,  and upward mobility in the US actually  compares unfavourably to that of other industrialised \nnations.\nSo why does the idea of the America n Dream persist?  A new study in the American Journal of Political Science \nidentifies one factor that has been overlooked: the influence of reality TV.\nReality shows have come to dominate US television over the past 20 years,  notes Eunji Kim  from Vanderbilt \nUniversity. And the overwhelming majority of these have a “rags-to-riches” storyline: they feature ordinary Americans who \nwork hard to achieve great economic success.  And while these programmes are regularly among the most-watched shows, \nnews broadcasts—which paint a more realistic view of the economic hardship faced by millions of Americans—get a much \nsmaller proportion of the viewership\nRags-to-riches stories are ubiquitous (无处不在的) on TV —but does watching these programmes  actually convince \npeople that economic mobility is easily attainable?  To find out, Kim's team had participants watch a 5 -minute clip from a \nreality show with a rags-to-riches storyline. Control participants watched a clip from a reality show that didn't h ave a rags-\nto-riches story. After watching the shows,  participants rated how much they agreed with four statements relating to the \nAmerican Dream\nThe results showed that those who'd watched a rags-to-riches clip did indeed have a significantly greater belief in the \nAmerican Dream. Interestingly, when participants were separated by party affiliation, this effect was significant among \nRepublicans but not Democrats, suggesting that the kind of messages implicit in these TV shows may play into people's \n\f\nexisting socioeconomic beliefs.\nKim also conducted a survey of 3,000 US residents. They also rated the extent to which they believed success in life is \nrelated to various internal factors (such as ambition) and external factors (such as family wealth). Finally, they read a list of \nTV programmes and indicated which they regularly watched.\nParticipants who were heavy viewers of rags-to-riches programmes or frequent viewers had a stronger belief in the \nAmerican Dream than those who never watched such shows.\nKim concludes that “rags-to-riches entertainment media are an important cultural force that promotes and perpetuates \nbeliefs in upward mobility”.  And here's the problem:  if people mistakenly believe that hard work is all that is needed for \nindividuals to make a better life for themselves,  they may be less supportive  of policies that could actually  combat \ninequality.\n“In this era of choice, entertainment media are what captures hearts and minds,” Kim writes. “Its political \nconsequences are anything but trivial”.","questions":[{"n":46,"stem":"46.What do we learn from the passage about young Americans of today?","options":{"A":"They have greater ambitions than their parents","B":"They find it difficult to achieve upward mobility","C":"They have overtaken their parents in terms of earnings","D":"They envy the opportunities in other industrialised nations"},"answer":"B"},{"n":47,"stem":"47.What does Kim's team find about reality TV shows in America?","options":{"A":"They reinterpret the essence of the popular rags-to-riches culture","B":"They urge people to achieve economic success through hard work","C":"They help strengthen people's conviction in the American Dream","D":"They feature ordinary Americans striving for social recognition"},"answer":"C"},{"n":48,"stem":"48.What does the author say about news broadcasts in America?","options":{"A":"They attract far fewer viewers than reality TV","C":"They stand in striking contrast with reality TV","B":"They are bent on reporting the dark side of life","D":"They focus on Americans' economic hardships"},"answer":"A"},{"n":49,"stem":"49.What can we infer from the passage about Republicans in general?","options":{"A":"They believe strongly in the American Dream","B":"They strive to climb the socio-economic ladder","C":"They have a very strong affiliation with their party","D":"They tend to watch more rags-to-riches TV shows"},"answer":"A"},{"n":50,"stem":"50.What is stated about people who believe in upward mobility?","options":{"A":"They are likely to blame the government for their plight","B":"They regard political consequences as anything but trivial","C":"They respect individuals striving to climb the social ladder","D":"They are less likely to approve of policies to fight inequality"},"answer":"D"}]},{"title":"Passage Two","passage":"When someone asks us 'what do you do?'  we nearly always reply with our occupation. Work, for many of us, is much \nmore than a job. It is the defining aspect of our identity. For many of us it is through our job that we can define ourselves.\n“Without my job I don't know who I am,” is a sentence that has been uttered on more than a handful of occasions from \nmy office chair. Indeed, it can be one of the most challenging aspects I work on with clients whohave lost or been forced \ninto changing their jobs. This loss provokes an identity crisis much greater than the loss of the job itself.\n\f\nOne of the things I have come to understand, however, is that our identity is much more complex than we recognise at \nfirst glance. If we take the time to reflect we might recognise that as well as our work we can also identify as a friend, a \nspouse, a son or daughter, a parent, a member of a sports team or religious community. We may recognise that we feel and \nact differently in these roles and relationships than we do at work. The passive daughter becomes an assertive leader at work. \nFurthermore, our identities at work are not static. They change over time. I myself have been a shop assistant, a waitress, a \nstudent, a graduate, and a clinical psychologist. At each stage my ability to adapt to and develop my career identity has been \ncrucial to my wellbeing. Whilst we like to eliminate uncertainty in our lives at some level we have to manage uncertainty, \nespecially in today's volatile and ever-shifting job market.\nHow we see ourselves is central to the issue of our identity. When we tell ourselves “I'm good at starting projects but \nnot so great at seeing them through.” it can become part of our belief system. But if you have the unfortunate experience of \nan enforced job change you will need to examine those beliefs to see how grounded in reality they are. You will be required \nto ask yourself how helpful these beliefs are and consider personal change We can change our beliefs, behaviours and \nemotional experience at any time through experimentation, practice and conscious self-discipline. In an age where career \nprogression may lead us into new sectors it is ever more important to challenge our sense of self and explore whether you \ncan create a new experience of your identity by changing the beliefs you hold about yourself in order to expand your career \noptions. Ultimately it is you who define who you are. You are only your job if you let it be so.","questions":[{"n":51,"stem":"51.What do we learn from the passage about one's loss of a job?","options":{"A":"It compels them to visit a clinical psychologist","B":"It offers them a chance to play different roles","C":"It renders them puzzled about who they are","D":"It forces them to redefine their life's goals"},"answer":"C"},{"n":52,"stem":"52.What has the author come to understand about our identity?","options":{"A":"It is crucial to our emotional wellbeing","C":"It reflects our changing status in society","B":"It plays a big role in many facets of life","D":"It is more complicated than it appears"},"answer":"D"},{"n":53,"stem":"53.What does the passage say about our identities at work?","options":{"A":"They are essential to our self-esteem","C":"They overrule all other self-perceptions","B":"They evolve with the passage of time","D":"They are key to understanding ourselves"},"answer":"B"},{"n":54,"stem":"54. What do we have to do in today's ever-changing job market?","options":{"A":"Strive to develop our social identity","C":"Try to be assertive at all times","B":"Prepare for different career paths","D":"Learn to manage uncertainty"},"answer":"D"},{"n":55,"stem":"55.What should we do to expand our career options?","options":{"A":"Alter our perceptions of ourselves","C":"Look into newly emerging sectors","B":"Compare various job opportunities","D":"Exercise self-discipline consciously"},"answer":"A"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true},{"id":"2024-06-cet6-3","level":"CET6","year":2024,"month":6,"set":3,"title":"2024 年 6 月 · CET6 第 3 套","source":"2024年6月 第3套","writing":{"prompt":"本套写作题面待接入；按 CET 作文要求写 120–180 词。","cn":"","guide":["先表明立场，再给两条理由。","结尾给方案或重申。"]},"listening":{"audio":"","note":"本套官方未提供听力。","groups":[]},"cloze":{"passage":"A rainbow is a multi-colored, arc-shaped phenomenon that can appear in the sky. The colors of a rainbow are produced \nby the reflection and ___26___ of light through water droplets (小滴) present in the atmosphere. An observer may \n___27___ rainbow to be located either near or far away, but this phenomenon is not actually located at any specific spot. \nInstead, the appearance of a rainbow depends entirely upon the position of the observer in ___28___ to the direction of \nlight. ln essence, a rainbow is an ___29___ illusion.  \nRainbows present a ___30___ made up of seven colors in a specific order. In fact, school children in many English-\nspeaking countries are taught to remember the name “Roy G.Biv” as an aid for remembering the colors of a rainbow and \ntheir order. “Roy G.Biv” ___31___ for: red, orange, yellow, green, blue, indigo, and violet. The outer edge of the rainbow \narc is red. while the inner edge is violet.  \nA rainbow is formed when light (generally sunlight) passes through water droplets ___32___ in the atmosphere. The \nlight waves change direction as they pass through the water droplets resulting in two processes: reflection and refraction (折\n射). When light reflects off a water droplet, it simply ___33___ back in the opposite direction from where it ___34___. \nWhen light refracts, it takes a different direction. Some individuals refer to refracted light as “bent light waves”. A rainbow \nis formed because white light enters the water droplet where it bends in several different directions. When these bent light \nwaves reach the other side of the water droplet, they reflect back out of the droplet instead of ___35___ passing through the \nwater. Since the white light is separated inside of the water, the refracted light appears as separate colors to the human eye.","bank":[["A","bounces"],["I","permeates"],["B","completely"],["J","ponder"],["C","dispersion"],["K","preceding"],["D","eccentric"],["L","recklessly"],["E","hanging"],["M","relation"],["F","optical"],["N","spectrum"],["G","originates"],["O","stands"],["H","perceive"]],"answers":{"26":"C","27":"H","28":"M","29":"F","30":"N","31":"O","32":"E","33":"A","34":"G","35":"B"}},"matching":{"statements":[{"n":36,"text":"36.Although employees are said to be fatigued by meetings, the condition has not been considered worthy of further research until recently","answer":"D"},{"n":37,"text":"37.Mroz and his team compiled a list of what to do and what not to do to remedy the problem of MRS","answer":"H"},{"n":38,"text":"38.Companies can get rid of the root cause of MRS if they give priority to workers' time","answer":"N"},{"n":39,"text":"39.If workers are exhausted to a dangerous degree, it is extremely hard for them to transition to the next task","answer":"F"},{"n":40,"text":"40.Employees in America spend a lot of time attending meetings while the number of hours managers meet is several times more","answer":"B"},{"n":41,"text":"41.Phyllis Hartman has learned by herself many of the ways Mroz suggested in his study and made remarkable success in freeing herself from unnecessary meetings","answer":"K"},{"n":42,"text":"42.When meetings continue too long or don't engage employees, they deplete vitality","answer":"E"},{"n":43,"text":"43.When the time of meetings is reduced, employees will be more engaged in the meetings they do participate in","answer":"I"},{"n":44,"text":"44.Some employees consider meetings one of the most dispensable parts of the workday","answer":"C"},{"n":45,"text":"45.According to Mroz, if all his suggestions were applied, a very obvious change would be a steep decrease in the number of meetings scheduled","answer":"L"}],"paragraphs":{"A":"Phyllis Hartman knows what it is like to make one's way through the depths of office meeting hell. Managers at one of her former human resources jobs arranged so many meetings that attendees would fall asleep at the table or intentionally arrive late. With hours of her day blocked up with unnecessary meetings, she was often forced to make up her work during overtime. “I was actually working more hours than I probably would have needed to get the work done,” says Hartman, who is founder and president of PGHR Consulting in Pittsburgh, Pennsylvania","B":"She isn't alone in her frustration. Between 11 million and 55 million meetings are held each day in the United States, costing most organizations between 7% and 15% of their personnel budgets. Every week, employees spend about six hours in meetings, while the average manager meets for a staggering 23 hours","C":"And though experts agree that traditional meetings are essential for making certain decisions and developing strategy, some employees view them as one of the most unnecessary parts of the workday. The result is not only hundreds of billions of wasted dollars, but an annoyance of what organizational psychologists call “meeting recovery syndrome” (MRS): time spent cooling off and regaining focus after a useless meeting. If you run to the office kitchen to get some relief with colleagues after a frustrating meeting, you're likely experiencing meeting recovery syndrome","D":"Meeting recovery syndrome is a concept that should be familiar to almost anyone who has held a formal job. It isn't ground-breaking to say workers feel fatigued after a meeting, but only in recent decades have scientists deemed the condition worthy of further investigation. With its links to organizational efficiency and employee wellbeing, MRS has attracted the attention of psychologists aware of the need to understand its precise causes and cures","E":"Today, in so far as researchers can hypothesis, MRS is most easily understood as a slow renewal of finite mental and physical resources. When an employee sits through an ineffective meeting their brain power is essentially being drained away. Meetings drain vitality if they last too long, fail to engage employees or turn into one-sided lectures. The conservation of resources theory, originally proposed in 1989 by Dr Stevan Hobfoll, states that psychological stress occurs when a person's resources are threatened or lost. When resources are low, a person will shift into defence to conserve their remaining supply. In the case of office meetings, where some of employees’ most valuable resources are their focus, alertness and motivation, this can mean an abrupt halt in productivity as they take time to recover","F":"As humans, when we transition from one task to another on the job—say from sitting in a meeting to doing normal work—it takes an effortful cognitive switch. We must detach ourselves from the previous task and expend significant mental energy to move on. If we are already drained to dangerous levels, then making the mental switch to the next thing is extra tough. It’s common to see people cyber-loafing after a frustrating meeting, going and getting coffee interrupting a colleague and telling them about the meeting, and so on","G":"Each person's ability to recover from horrible meetings is different. Some can bounce back quickly, while others carry their fatigue until the end of the workday. Yet while no formal MRS studies are currently underway, one can loosely speculate on the length of an average employee's lag time. Switching tasks in a non-MRS condition takes about 10 to 15 minutes. With MRS, it may take as long as 45 minutes on average. It's even worse when a worker has several meetings that are separated by 30 minutes. “Not enough time to transition in a non-MRS situation to get anything done, and in an MRS situation, not quite enough time to recover for the next meeting.” Says researcher Joseph Allen, “Then, add the compounding of back-to-back bad meetings and we may have an epidemic on our hands.”","H":"In an effort to combat the side effects of MRS, Allen, along with researcher Joseph Mroz and colleagues at the University of Nebraska-Oma has published a study detailing the best ways to avoid common traps including a concise checklist of do's and don’ts applicable to any workplace. Drawing from around 200 papers to compile their comprehensive list. Mroz and his team may now hold a remedy to the largely undefined problem of MRS","I":"Mroz says a good place to start is asking ourselves if our meetings are even necessary in the first place. If all that’s on the agenda is a quick catch-up, or some non-urgent information sharing, it may better suit the group to send around an email instead. “The second thing I would always recommend is keep the meeting as small as possible.” says Mroz, “If they don't actually have some kind of immediate input then they can follow up later. They don’t need to be sitting in this hour- long meeting.” Less time in meetings would ultimately lead to more employee engagement in the meetings they do attend, which experts agree is a proven remedy for MRS","J":"Employees also feel taxed when they are invited together to meetings that don’t inspire participation, says Cliff Scott, professor of organizational science. It takes precious time for them to vent their emotions, complain and try to regain focus after a pointless meeting — one of the main traps of MRS. Over time as employees find themselves tied up in more and more unnecessary meetings — and thus dealing with increasing lag times from MRS — the waste of workday hours can feel insulting","K":"Despite the relative scarcity of research behind the subject. Hartman has taught herself many of the same tricks suggested in Mroz's study and has come a long way since her days of being stuck with unnecessary meetings. The people she invites to meetings today include not just the essential employees but also representatives from every department that might have a stake in the issue at hand. Managers like her, who seek input even from non-experts to shape their decisions, can find greater support and cooperation from their workforce, she says","L":"If an organization were to apply all 22 suggestions from Mroz and Allen’s findings, the most noticeable difference would be a stark decrease in the total number of meetings on the schedule, Mroz says. Less time in meetings would ultimately lead to increased productivity, which is the ultimate objective of convening a meeting. While none of the counter- MRS ideas have been tested empirically yet, Allen says one trick with promise is for employees to identify things that quickly change their mood from negative to positive. As simple as it sounds, finding a personal happy place, going there and then coming straight back to work might be key to facilitating recovery","M":"Leaders should see also themselves as “stewards of everyone else’s valuable time”, adds Steven Rogelberg, author of The Surprising Science of Meetings. Having the skills to foresee potential traps and treat employees’ endurance with care allows leaders to provide effective short-term deterrents to MRS","N":"Most important, however, is for organizations to awaken to the concept of meetings being flexible, says Allen. By reshaping the way they prioritise employees' time, companies can eliminate the very sources of MRS in their tracks"},"letters":["A","B","C","D","E","F","G","H","I","J","K","L","M","N"],"note":"完整 A–N 段落已接入。"},"reading":[{"title":"Passage One","passage":"Sarcasm and jazz have something surprisingly in common: You know them when you hear them. Sarcasm is mostly \nunderstood through tone of voice, which is used to portray the opposite of the literal words. For example, when someone \nsays, “Well, that's exactly what I need right now,” their tone can tell you it’s not what they need at all.  \nMost frequently, sarcasm highlights an irritation or is, quite simply, mean. \n\f\nIf you want to be happier and improve your relationships, cut out sarcasm. Why? Because sarcasm is actually hostility \ndisguised as humor.  \nDespite smiling outwardly, many people who receive sarcastic comments feel put down and often think the sarcastic \nperson is rude, or contemptible. Indeed. it's not surprising that the origin of the word sarcasm derives from the Greek word \n“sarkazein” which literally means “to tear or strip the flesh off.” Hence, it's no wonder that sarcasm is often preceded by the \nword “cutting” and that it hurts.  \nWhat’s more, since actions strongly determine thoughts and feelings, when a person consistently acts sarcastically it \nmay only serve to heighten their underlying hostility and insecurity. After all, when you come right down to it, sarcasm can \nbe used as a subtle form of bullying — and most bullies are angry, insecure, or cowardly.  \nAlternatively, when a person stops voicing negative comments, especially sarcastic ones, they may soon start to feel \nhappier and more self-confident. Also. other people in their life benefit even more because they no longer have to hear the \nemotionally hurtful language of sarcasm.  \nNow, I'm not saying all sarcasm is bad. It may just be better used sparingly—like a potent spice in cooking. Too much \nof the spice, and the dish will be overwhelmed by it. Similarly, an occasional dash of sarcastic wit can spice up a chat and \nadd an element of humor to it. But a big or steady serving of sarcasm will overwhelm the emotional flavor of any \nconversation and can taste very bitter to its recipient.  \nSo, tone down the sarcasm and work on clever wit instead, which is usually without any hostility and thus more \nappreciated by those you're communicating with. In essence, sarcasm is easy while true, harmless wit takes talent.  \nThus, the main difference between wit and sarcasm is that as already stated, sarcasm is often hostility disguised as \nhumor. It can be intended to hurt and is often bitter and biting. Witty statements are usually in response to someone's \nunhelpful remarks or behaviors, and the intent is to untangle and clarify the issue by emphasizing its absurdities. Sarcastic \nstatements are expressed in a cutting manner; witty remarks are delivered with undisguised and harmless humor.","questions":[{"n":46,"stem":"46.Why does the author say sarcasm and jazz have something surprisingly in common?","options":{"A":"Both are recognized when heard","C":"Both mean the opposite of what they appear to","B":"Both have exactly the same tone","D":"Both have hidden in them an evident irritation"},"answer":"A"},{"n":47,"stem":"47.How do many people feel when they hear sarcastic comments?","options":{"A":"They feel hostile towards the sarcastic person","C":"They feel a strong urge to retaliate","B":"They feel belittled and disrespected","D":"They feel incapable of disguising their irritation"},"answer":"B"},{"n":48,"stem":"48.What happens when a person consistently acts sarcastically?","options":{"A":"They feel their dignity greatly heightened","B":"They feel increasingly insecure and hostile","C":"They endure hostility under the disguise of humor","D":"They taste bitterness even in pleasant interactions"},"answer":"B"},{"n":49,"stem":"49.What does the author say about people quitting sarcastic comments?","options":{"A":"It makes others happier and more self-confident","B":"It restrains them from being irritating and bullying","C":"It benefits not only themselves but also those around them","D":"It shields them from negative comments and outright hostility"},"answer":"C"},{"n":50,"stem":"50.What is the chief difference between a Speaker’s wit and sarcasm?","options":{"A":"Their clarity","C":"Their emphasis","B":"Their appreciation","D":"Their intention"},"answer":"D"}]},{"title":"Passage Two","passage":"Variability is crucially important for learning new skills. Consider learning how to serve in tennis. Should you always \npractise serving from the exactly same location on the court aiming at the same spot? Although practising in more variable \nconditions will be slower at first, it will likely make you a better tennis player in the end. This is because variability leads to \nbetter generalisation of what is learned.  \nThis principle is found in many domains, including speech perception and learning categories. For instance, infants \nwill struggle to learn the category “dog” if they are only exposed to Chihuahuas, instead of many different kinds of dogs.  \n“There are over ten different names for this basic principle,” says Limor Raviv, the senior investigator of a recent \nstudy. “Learning from less variable input is often fast, but may fail to generalise to new stimuli.”  \nTo identify key patterns and understand the underlying principles of variability effects, Raviv and her colleagues \nreviewed over 150 studies on variability and generalisation across fields including computer science, linguistics, \ncategorization, visual perception and formal education.  \nThe researchers discovered that across studies, the term variability can refer to at least four different kinds of \nvariability, such as set size and scheduling. “These four kinds of variability have never been directly compared — which \nmeans that we currently don’t know which is most effective for learning,” says Raviv.  \nThe impact of variability depends on whether it is relevant to the task or not. But according to the ‘Mr. Miyagi \nprinciple’ practising seemingly unrelated skills may actually benefit learning of other skills.  \nBut why does variability impact learning and generalization? One theory is that more variable input can highlight \nwhich aspects of a task are relevant and which are not.  \nAnother theory is that greater variability leads to broader generalisations. This is because variability will represent the \nreal world better. including atypical (非典型的) examples.  \nA third reason has to do with the way memory works: when training is variable, learners are forced to actively \nreconstruct their memories.  \n“Understanding the impact of variability is important for literally every aspect of our daily life. Beyond affecting the \nway we learn language, motor skills, and categories, it even has an impact on our social lives,” explains Raviv. “For \nexample, face recognition is affected by whether people grew up in a Small community or in a larger community. Exposure \nto fewer faces during childhood is associated with diminished face memory.”  \n“We hope this work will spark peoples curiosity and generate more work on the topic.” concludes Raviv. “Our paper \nraises a lot of open questions. Can we find similar effects of variability beyond the brain, for instance, in the immune \nsystem?”","questions":[{"n":51,"stem":"51.What does the passage say about infants learning the category “dog” if they are exposed to Chihuahuas only?","options":{"A":"They will encounter some degree of difficulty","B":"They will try to categorise other objects first","C":"They will prefer Chihuahuas to other dog species","D":"They will imagine Chihuahuas in various conditions"},"answer":"A"},{"n":52,"stem":"52.What does Raviv say about the four different kinds of variability?","options":{"A":"Which of them is most relevant to the task at hand is to be confirmed","B":"Why they have an impact on learning is far from being understood","C":"Why they have never been directly compared remains a mystery","D":"Which of them is most conducive to learning is yet to be identified"},"answer":"D"},{"n":53,"stem":"53.How does one of the theories explain the importance of variability for learning new skills?","options":{"A":"Learners regard variable training as typical of what happens in the real world","B":"Learners receiving variable training are compelled to reorganise their memories","C":"Learners pay attention to the relevant aspects of a task and ignore those irrelevant","D":"Learners focus on related skills instead of wasting time and effort on unrelated ones"},"answer":"B"},{"n":54,"stem":"54.What does the passage say about face recognition?","options":{"A":"People growing up in a small community may find it easy to remember familiar faces","B":"Face recognition has a significant impact on literally every aspect of our social lives:","C":"People growing up in a large community can readily recognise any individual faces","D":"The size of the community people grew up in impacts their face recognition ability"},"answer":"D"},{"n":55,"stem":"55.What does Raviv hope to do with their research work?","options":{"A":"Highlight which aspects of a task are relevant and which are not to learning a skill","B":"Use the principle of variability in teaching seemingly unrelated skills in education","C":"Arouse people’s interest in variability and stimulate more research on the topic","D":"Apply the principle of variability to such fields of study as the immune system"},"answer":"C"}]}],"translation":{"prompt":"本套翻译题面待接入。","guide":["先拆句，再定主谓。","文化词先意译再补注释。"]},"answersReady":true}];a.forEach(function(e){window.CET_DATA.exams.push(e)});})();
